options.afterRender:
// --- Reports shared helpers and states (dashboard_src/reports/_shared/states.js) ---
// Declares one name: rpt. Business Text afterRender only (it reads context.grafana).
const rpt = (() => {
  const grafana = (typeof context !== 'undefined' && context.grafana) || {};
  // A variable's value; '' when the dashboard has no such variable (replaceVariables leaves `${name}`).
  const v = (name) => { const x = grafana.replaceVariables ? String(grafana.replaceVariables('${' + name + '}')) : ''; return x === '${' + name + '}' ? '' : x; };

  const esc = (x) => String(x == null ? '' : x).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const num = (x) => (x === null || x === undefined || x === '' || isNaN(Number(x)) ? null : Number(x));
  // Thousands commas.
  const fmt = (x) => (num(x) === null ? '—' : Math.round(num(x)).toLocaleString('en-US'));
  // Percent: whole, one decimal under 10% (DESIGN Typography).
  const pct = (x) => { const n = num(x); if (n === null) { return '—'; } return (Math.abs(n) < 10 ? n.toFixed(1) : String(Math.round(n))) + '%'; };
  // Scores: two decimals.
  const score = (x) => (num(x) === null ? '—' : num(x).toFixed(2));
  const yes = (x) => x === true || x === 1 || x === 't' || x === 'true';

  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  // Postgres dates arrive as ms numbers or 'YYYY-MM-DD' strings; read them as UTC days.
  const toDate = (x) => { if (x == null || x === '') { return null; } const d = typeof x === 'number' ? new Date(x) : new Date(String(x).slice(0, 10) + 'T00:00:00Z'); return isNaN(d) ? null : d; };
  const day = (x) => { const d = toDate(x); return d ? d.getUTCDate() + '-' + MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };
  const month = (x) => { const d = toDate(x); return d ? MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };

  // Rows of the frame with refId ref, as objects.
  const rows = (ref) => {
    const series = (context.panelData && context.panelData.series) || [];
    const f = series.find((s) => s.refId === ref);
    if (!f) { return []; }
    const cols = f.fields.map((x) => [x.name, Array.from(x.values)]);
    const n = cols.length ? cols[0][1].length : 0;
    return Array.from({ length: n }, (_, i) => Object.fromEntries(cols.map(([k, vals]) => [k, vals[i]])));
  };

  // report_flags rows from a flags_json column (json_agg of {report, flag_reason, patients_n}) on each row.
  const flagsFrom = (list) => [].concat(...(list || []).map((r) => {
    let parsed = [];
    try { parsed = r.flags_json ? JSON.parse(r.flags_json) : []; } catch (e) { parsed = []; }
    return (Array.isArray(parsed) ? parsed : []).map((f) => Object.assign({ org_unit_id: r.org_unit_id, org_unit_name: r.org_unit_name }, f));
  }));

  // Variables, read in the browser so no access query is needed.
  const orgUnit = () => { const o = v('org_unit').trim(); return o && o !== '0' ? o : '0'; };
  const reportingMonth = () => v('reporting_month');
  const allowed = () => v('isAllowed') === '1';

  // The user's home unit (hidden variable home_org_unit, the home dashboard's UserOrgUnitId query).
  // '' for admins and users with access everywhere.
  const homeUnit = () => { const h = v('home_org_unit').trim(); return h && h !== '0' ? h : ''; };

  // Tabs from the builder's TABS list: [{report, title, slug}], in tab order. TABS[0] is `Start here`.
  const TABS = [{"report":"start","title":"Start here","slug":"Start-here"},{"report":"titration","title":"Stepping up","slug":"Stepping-up"},{"report":"adherence","title":"Right medicines","slug":"Right-medicines"},{"report":"fudging","title":"BP readings check","slug":"BP-readings-check"},{"report":"calling","title":"Overdue calls","slug":"Overdue-calls"},{"report":"statins","title":"Statins","slug":"Statins"}];
  // The five report tabs (every tab but `Start here`), in tab order.
  const REPORTS = TABS.filter((t) => t.report !== 'start');
  const tab = (report) => TABS.find((t) => t.report === report) || null;
  // AD-29 deep link; keeps the location and month unless given. extra: more URL parameters,
  // for example { 'var-include_new': 'true' }.
  const link = (report, org, mon, extra) => {
    const t = tab(report);
    if (!t) { return ''; }
    const more = Object.keys(extra || {}).map((k) => '&' + encodeURIComponent(k) + '=' + encodeURIComponent(extra[k])).join('');
    return '/d/heart360_reports?var-org_unit=' + encodeURIComponent(org == null ? orgUnit() : org)
      + '&var-reporting_month=' + encodeURIComponent(mon == null ? reportingMonth() : mon) + more + '&-dtab=' + encodeURIComponent(t.slug);
  };
  // A facility name that narrows this tab to that facility (UX-15). Plain text when it is already the place in view.
  const placeLink = (report, id, name) => (id == null || String(id) === orgUnit() || !tab(report)
    ? esc(name) : '<a class="rpt-link" href="' + esc(link(report, id)) + '" title="' + esc('Show ' + name + ' only') + '">' + esc(name) + '</a>');
  // `Next step` line at the end of a tab: one link, sentence case.
  const nextStep = (text, href) => '<div class="rpt-next"><span class="rpt-next-label">Next step</span>'
    + '<a class="rpt-link" href="' + esc(href) + '">' + esc(text) + ' →</a></div>';
  // Same-page links: an <a href="#some-id"> inside el scrolls the element with that id into view
  // (Grafana scrolls its own pane, so a plain hash link does not move it). Use with nextStep('...', '#id').
  // Grafana draws panels lazily: while the target is not drawn yet, the pane scrolls down a screen at a
  // time until it appears.
  const wireScroll = (el) => {
    if (!el || el.__rptScroll) { return; }
    el.__rptScroll = true;
    const pane = (node) => { let p = node.parentElement; while (p && !(p.scrollHeight > p.clientHeight && /auto|scroll/.test(getComputedStyle(p).overflowY))) { p = p.parentElement; } return p; };
    el.addEventListener('click', (e) => {
      const a = e.target.closest && e.target.closest('a[href^="#"]');
      if (!a || !el.contains(a)) { return; }
      e.preventDefault();
      const id = a.getAttribute('href').slice(1);
      const box = pane(el);
      let tries = 0;
      const go = () => {
        const t = document.getElementById(id);
        if (t) { t.scrollIntoView({ behavior: 'smooth', block: 'start' }); return; }
        if (!box || tries++ > 8) { return; }
        box.scrollTop += Math.round(box.clientHeight * 0.8);
        setTimeout(go, 350);
      };
      go();
    });
  };
  // At or below the facility level (selected_level 3 or more): patient lists and the overdue list work here.
  const atFacility = () => (num(v('selected_level')) || 0) >= 3;

  // --- States (DESIGN States, FR-32) ---
  // Grey note, no warning tone (Voice rule 8, UX-21). html is trusted markup; use esc() on data.
  const info = (html) => '<div class="rpt-info">' + html + '</div>';
  // No access: plain words and the next step. The access team names sit in a closed `Details` for the admin.
  const banner = () => {
    const teams = v('requiredGroups').replace(/<[^>]*>/g, '').trim();
    return info('<span>You cannot see this place. Pick your own area in <strong>Change location</strong> above.</span>'
      + (teams ? '<details class="rpt-details"><summary>Details for your admin</summary>Access comes from: ' + esc(teams) + '</details>' : ''));
  };
  // Shown while the page moves a user with no location to their home unit (UX-02).
  const OPENING_HOME = 'Opening your area…';
  // For views that need one facility (patient lists): a grey line with the next step.
  const PICK_FACILITY = 'Pick a facility in Change location above to see its patients.';
  const NO_DATA = 'No data for this place.';
  const NO_FACILITIES = 'No facilities for this location.';
  const NO_FLAGS = 'No facility is flagged.';
  const noData = (text) => '<div class="rpt-empty">' + esc(text || NO_DATA) + '</div>';
  // "Need at least 20; this place has 12."
  const needAtLeast = (k, n) => 'Need at least ' + fmt(k) + '; this place has ' + fmt(n) + '.';
  // Place for the subtitle: the selected name, or all locations.
  const place = (name) => (orgUnit() === '0' ? 'All locations you can access' : (name || 'This place'));

  // Thresholds from report_flag_thresholds rows ({report, key, value}).
  const thresholds = (list) => { const t = {}; (list || []).forEach((r) => { t[r.report + '.' + r.key] = num(r.value); }); return t; };

  // UX-02: a user with no location who may not see all places is moved to their home unit, keeping
  // the month and tab. Returns true when it does so.
  const goHome = () => {
    const home = homeUnit();
    if (allowed() || orgUnit() !== '0' || !home) { return false; }
    // Several panels call this on one render; move once (a later blank pick moves again).
    if (Date.now() - (window.__rptGoHome || 0) > 3000) {
      window.__rptGoHome = Date.now();
      const ls = grafana.locationService;
      if (ls && ls.partial) { ls.partial({ 'var-org_unit': home }, true); }
      else { const u = new URL(window.location.href); u.searchParams.set('var-org_unit', home); window.location.replace(u.toString()); }
    }
    return true;
  };
  // True while the panel's query is still running.
  const loading = () => !!(context.panelData && context.panelData.state === 'Loading');

  // Mount: returns the root element, or null when access is denied. The banner is drawn once per tab,
  // by the panel mounted with { banner: true } (the title strip); other panels stay empty under it.
  // A user with no location is first moved to their home unit (UX-02); meanwhile the banner panel
  // shows `Opening your area…`. opts.loading: a line to show while the query runs (null is returned).
  const mount = (selector, opts) => {
    const o = opts || {};
    const root = context.element.querySelector(selector);
    if (!root) { return null; }
    if (goHome()) { root.innerHTML = o.banner ? '<div class="rpt-muted">' + esc(OPENING_HOME) + '</div>' : ''; return null; }
    if (!allowed()) { root.innerHTML = o.banner ? banner() : ''; return null; }
    if (o.loading && loading()) { root.innerHTML = '<div class="rpt-muted rpt-loading">' + esc(o.loading) + '</div>'; return null; }
    return root;
  };

  return { v, esc, num, fmt, pct, score, yes, day, month, toDate, rows, orgUnit, reportingMonth, allowed, homeUnit,
    TABS, REPORTS, tab, link, placeLink, nextStep, wireScroll, atFacility, flagsFrom, info, banner, OPENING_HOME, PICK_FACILITY,
    NO_DATA, NO_FACILITIES, NO_FLAGS, noData, needAtLeast, place, thresholds, loading, goHome, mount };
})();
// Start here (story 7.9, UX-14, UX-04, UX-39): facilities in view down the side, the five reports across.
// Each cell is one state (Flagged, Check, Too few, Fine) with its number, and opens that report tab
// for that facility and month. Facilities that need a look come first, ordered by report_flags.
const root = rpt.mount('.rpt-start', { banner: true, loading: 'Finding facilities…' });
if (!root) { return; }
const { esc, num, pct, score, yes } = rpt;
const all = rpt.rows('A');
const place = rpt.place(all.length ? all[0].place : '');
const head = '<h2 class="rpt-title">Which facility needs a look first?</h2>'
  + '<div class="rpt-sub">' + esc(place) + ' · ' + esc(rpt.month(rpt.reportingMonth())) + '</div>'
  + '<p class="rpt-start-do">Pick the facility to visit first. Click a cell to see why.</p>';
const demo = '<div class="rpt-demo">Demo data. Facility names and numbers are made up.</div>';
if (!all.length) { root.innerHTML = head + rpt.noData(rpt.NO_FACILITIES) + demo; return; }

// The number in each cell, per report.
const VALUE = {
  titration: (x) => pct(x) + ' stepped up',
  adherence: (x) => pct(x) + ' on one medicine',
  fudging: (x) => score(x) + ' under 140 per 1 over',
  calling: (x) => pct(x) + ' called',
  statins: (x) => pct(x) + ' on a statin',
};
const STATE = {
  flag: { word: 'Flagged', cls: 'rpt-cell-flag' },
  check: { word: 'Check', cls: 'rpt-cell-check' },
  few: { word: 'Too few', cls: 'rpt-cell-few' },
  fine: { word: 'Fine', cls: 'rpt-cell-fine' },
};
const stateOf = (c) => (!c ? null : yes(c.flag) ? 'flag' : yes(c.too_few) ? 'few' : yes(c.look_check) ? 'check' : 'fine');

// One entry per facility: { id, name, cells: {report: row}, nFlags, patients }.
const by = {};
all.forEach((r) => {
  const k = String(r.org_unit_id);
  const f = by[k] = by[k] || { id: r.org_unit_id, name: String(r.org_unit_name || ''), cells: {}, nFlags: 0, patients: 0 };
  f.cells[r.report] = r;
  if (yes(r.in_flags)) { f.nFlags += 1; f.patients = Math.max(f.patients, num(r.patients_n) || 0); }
});
const count = (f, s) => rpt.REPORTS.filter((t) => stateOf(f.cells[t.report]) === s).length;
// Needs a look first: any flag, then any check, then the rest. Within that: more report_flags
// entries, more flagged cells, more patients under care, then name.
const rank = (f) => (count(f, 'flag') ? 0 : count(f, 'check') ? 1 : 2);
const list = Object.values(by).sort((a, b) => rank(a) - rank(b) || b.nFlags - a.nFlags
  || count(b, 'flag') - count(a, 'flag') || b.patients - a.patients || a.name.localeCompare(b.name));

const cell = (f, t) => {
  const c = f.cells[t.report];
  const s = stateOf(c);
  if (!s) { return '<td class="rpt-cell rpt-cell-none">—</td>'; }
  const st = STATE[s];
  const n = s === 'few' || num(c.value) === null ? '' : VALUE[t.report](c.value);
  const why = s === 'flag' && c.flag_reason ? c.flag_reason : '';
  const label = f.name + ', ' + t.title + ': ' + st.word + (n ? ', ' + n : '') + '. Open this report.';
  return '<td class="rpt-cell ' + st.cls + '"><a href="' + esc(rpt.link(t.report, f.id)) + '" aria-label="' + esc(label) + '"'
    + (why ? ' title="' + esc(why) + '"' : '') + '><span class="rpt-cell-word">' + esc(st.word) + '</span>'
    + (n ? '<span class="rpt-cell-n">' + esc(n) + '</span>' : '') + '</a></td>';
};
root.innerHTML = head
  + '<div class="rpt-wrap"><table class="rpt-table rpt-grid">'
  + '<caption class="rpt-sr">Each facility in view against the five reports. Facilities that need a look come first.</caption>'
  + '<thead><tr><th scope="col">Facility</th>' + rpt.REPORTS.map((t) => '<th scope="col">' + esc(t.title) + '</th>').join('') + '</tr></thead>'
  + '<tbody>' + list.map((f) => '<tr class="' + (rank(f) === 0 ? 'rpt-flagged' : '') + '"><th scope="row">' + esc(f.name) + '</th>'
    + rpt.REPORTS.map((t) => cell(f, t)).join('') + '</tr>').join('') + '</tbody></table></div>'
  + '<div class="rpt-start-key"><span><b>Flagged</b> needs a look</span><span><b>Check</b> looks fine, worth a second look</span>'
  + '<span><b>Too few</b> not enough patients to judge</span><span><b>Fine</b> no flag</span></div>'
  + demo;

options.styles:
/* --- Reports shared styles (dashboard_src/reports/_shared/styles.css) ---
   Business Text styles. Every class starts rpt-; put class "rpt" on the panel's root div.
   Tokens: ux-hearts360-mvp-2026-11-04/DESIGN.md front matter. Table, chips, pager and banner copy
   the program dashboard's overdue list (.ovq-*). Light theme only (A40). */
.rpt {
  --text-primary: #111217; --text-muted: #6E6E6E; --border-subtle: #D8D9DA; --accent: #3D71D9;
  --controlled: #3BB231; --uncontrolled: #EEAB00; --no-visit: #ED6300;
  --flag-bar: #ED6300; --flag-row-bg: #FDF0E6; --flag-pill-bg: #FDE3CF; --flag-pill-text: #8A3A00;
  --guard-pill-text: #4E545A; --cell-missing-bg: #EFEFEF;
  font-size: 13px; line-height: 1.35; color: var(--text-primary);
}
.rpt a.rpt-link { color: #0075eb; text-decoration: none; }
.rpt a.rpt-link:hover, .rpt a.rpt-link:focus-visible { text-decoration: underline; }
.rpt-sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.rpt-muted { color: var(--text-muted); }
.rpt-empty { color: var(--text-muted); font-size: 14px; text-align: center; padding: 18px 8px; }

/* Title strip: question (card-title), then "{place} · {period}" (microcopy, muted). */
.rpt-title { font-size: 16px; font-weight: 500; margin: 0 0 2px; line-height: 1.3; }
.rpt-sub { font-size: 12px; color: var(--text-muted); line-height: 1.4; }

/* Headline strip: three equal columns, thin dividers (as panel-outcomes). */
.rpt-strip3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); height: 100%; }
.rpt-strip3 > div { padding: 2px 16px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip3 > div:first-child { border-left: 0; padding-left: 4px; }
.rpt-big { font-size: 32px; font-weight: 600; line-height: 1.1; font-variant-numeric: tabular-nums; }
.rpt-big.rpt-few { font-size: 20px; font-weight: 500; color: var(--text-muted); line-height: 1.6; }
.rpt-label { font-size: 14px; font-weight: 500; margin-top: 2px; }
.rpt-line { font-size: 12px; color: var(--text-muted); line-height: 1.4; margin-top: 2px; }

/* Look at these first: at most three items. */
.rpt-card-title { font-size: 16px; font-weight: 500; margin: 0 0 8px; }
.rpt-look { list-style: none; margin: 0; padding: 0; }
.rpt-look li { padding: 8px 0 8px 10px; border-left: 4px solid var(--flag-bar); background: var(--flag-row-bg); margin-bottom: 8px; border-radius: 0 4px 4px 0; }
.rpt-look-name { font-weight: 600; }
.rpt-look-line { font-size: 12px; line-height: 1.4; margin-top: 2px; }

/* Facility table: overdue list style. No vertical lines or stripes, light header, hover highlight. */
.rpt-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.rpt-chip { font: inherit; font-size: 12px; border: 1px solid #d9e3ff; background: transparent; color: inherit; border-radius: 14px; padding: 2px 10px; cursor: pointer; text-decoration: none; display: inline-block; white-space: nowrap; }
.rpt-chip.on { background: #0075eb; border-color: #0075eb; color: #fff; cursor: default; }
a.rpt-chip:hover, button.rpt-chip:not(.on):hover { background: #EEF3FD; }
.rpt-wrap { overflow-x: auto; }
.rpt-table { width: 100%; border-collapse: collapse; border: 0; }
.rpt-table th, .rpt-table td { border: 0 !important; border-bottom: 1px solid rgba(128,128,128,0.2) !important; padding: 8px 8px; text-align: left; vertical-align: top; }
.rpt-table thead th { background: rgba(0,117,235,0.06); color: #6e7f8d; font-size: 12px; font-weight: 600; white-space: nowrap; vertical-align: bottom; }
.rpt-table tbody th { font-weight: 400; white-space: nowrap; background: transparent; color: inherit; }
.rpt-table tbody tr:hover { background: rgba(0,117,235,0.04); }
.rpt-table .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.rpt-table thead th.num .rpt-sortbtn { text-align: right; }
.rpt-table td.rpt-why { width: 42%; min-width: 260px; }
.rpt-sortbtn { font: inherit; font-weight: 600; background: none; border: 0; padding: 0; color: inherit; cursor: pointer; }
.rpt-sortbtn:focus-visible, .rpt-chip:focus-visible, .rpt-pager button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* Flagged row: 4px orange bar and light tint. */
.rpt-table tr.rpt-flagged, .rpt-table tr.rpt-flagged:hover { background: var(--flag-row-bg); }
.rpt-table tr.rpt-flagged > th:first-child { box-shadow: inset 4px 0 0 var(--flag-bar); padding-left: 12px; }
/* All places in view: bold first row. */
.rpt-table tr.rpt-total > th, .rpt-table tr.rpt-total > td { font-weight: 700; }
.rpt-table tr.rpt-total .rpt-reason, .rpt-table tr.rpt-total .rpt-pill { font-weight: 400; }
.rpt-ctl { color: var(--controlled); font-weight: 600; }
/* Pills: text, never colour only. */
.rpt-pills { display: flex; flex-wrap: wrap; gap: 4px; }
.rpt-pill { display: inline-block; padding: 1px 8px; border-radius: 9999px; font-size: 12px; font-weight: 600; white-space: nowrap; line-height: 1.5; }
.rpt-pill-flag { background: var(--flag-pill-bg); color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-check { background: #FFFFFF; color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-guard { background: var(--cell-missing-bg); color: var(--guard-pill-text); border: 1px solid var(--cell-missing-bg); }
.rpt-reason { font-size: 12px; line-height: 1.4; margin-top: 3px; color: var(--text-primary); }
.rpt-also { font-size: 12px; margin-top: 3px; }
.rpt-also a { color: #0075eb; text-decoration: none; }
.rpt-also a:hover, .rpt-also a:focus-visible { text-decoration: underline; }
.rpt-clean { color: var(--text-muted); }
/* Pager: overdue list. */
.rpt-pager { display: flex; justify-content: center; align-items: center; gap: 12px; padding: 10px 0 2px; }
.rpt-pager button { font: inherit; width: 28px; height: 26px; border-radius: 4px; border: 1px solid #d9e3ff; background: transparent; color: inherit; cursor: pointer; }
.rpt-pager button:disabled { opacity: 0.35; cursor: default; }
/* Access banner: the overdue list's .ovq-warn. */
.rpt-warn { color: #e02424; background: rgba(224,36,36,0.05); border-left: 4px solid #e02424; padding: 8px 14px; font-size: 13px; display: flex; align-items: center; gap: 8px; border-radius: 2px; line-height: 1.4; }

/* How this is worked out. */
.rpt-note { font-size: 12px; color: var(--text-muted); line-height: 1.45; }

.rpt-demo { font-size: 12px; color: var(--text-muted); margin-top: 8px; }

/* Grey note (no warning tone, UX-21): no access, pick a facility, and other next-step lines. */
.rpt-info { color: var(--text-primary); background: #F4F5F5; border-left: 4px solid var(--border-subtle); padding: 8px 14px; font-size: 13px; line-height: 1.45; border-radius: 2px; }
.rpt-details { margin-top: 4px; font-size: 12px; color: var(--text-muted); }
.rpt-details summary { cursor: pointer; }
.rpt-loading { padding: 8px 0; }

/* Next step: one link at the end of a tab. */
.rpt-next { display: flex; align-items: baseline; gap: 10px; font-size: 14px; padding: 4px 0; }
.rpt-next-label { font-size: 12px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.03em; }
.rpt-next a.rpt-link { font-weight: 500; }

/* Start here grid: facilities down the side, reports across; each cell is a link. */
.rpt-start-do { margin: 6px 0 10px; font-size: 14px; }
.rpt-grid { table-layout: fixed; }
.rpt-grid thead th:first-child, .rpt-grid tbody th { width: 16%; }
.rpt-grid tbody th { font-weight: 600; vertical-align: middle; }
.rpt-table.rpt-grid td.rpt-cell { padding: 3px; vertical-align: middle; }
.rpt-cell a { display: block; padding: 5px 8px; border-radius: 4px; text-decoration: none; color: inherit; border: 1px solid transparent; line-height: 1.3; }
.rpt-cell a:hover, .rpt-cell a:focus-visible { border-color: var(--accent); outline: none; }
.rpt-cell-word { display: block; font-weight: 600; font-size: 13px; }
.rpt-cell-n { display: block; font-size: 12px; color: var(--text-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rpt-cell-flag a { background: var(--flag-pill-bg); border-color: var(--flag-bar); }
.rpt-cell-flag .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-flag .rpt-cell-n { color: var(--flag-pill-text); }
.rpt-cell-check a { background: #FFFFFF; border-color: var(--flag-bar); border-style: dashed; }
.rpt-cell-check .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-few a { background: var(--cell-missing-bg); }
.rpt-cell-few .rpt-cell-word { color: var(--guard-pill-text); }
.rpt-cell-fine .rpt-cell-word { font-weight: 400; color: var(--text-muted); }
.rpt-cell-none { color: var(--text-muted); text-align: center; }
.rpt-start-key { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 12px; color: var(--text-muted); margin-top: 8px; }
.rpt-start-key b { color: var(--text-primary); font-weight: 600; }

/* Headline strip with four numbers (Overdue calls). */
.rpt-strip4 { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); height: 100%; }
.rpt-strip4 > div { padding: 2px 14px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip4 > div:first-child { border-left: 0; padding-left: 4px; }

/* Monthly table, place against the average (monthly.js; Metabase titration and statins form). */
.rpt-mt th, .rpt-mt td { padding: 5px 8px; }
.rpt-mt thead tr.rpt-mt-group th { text-align: center; color: var(--text-primary); font-size: 12px; border-bottom: 0 !important; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-place { box-shadow: inset 0 -3px 0 #3D71D9; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-avg { box-shadow: inset 0 -3px 0 #9B7FD4; }
.rpt-mt .rpt-mt-gap { border-left: 1px solid var(--border-subtle) !important; }
.rpt-mt tbody tr.rpt-mt-last > * { font-weight: 700; }
.rpt-mt-few { color: var(--text-muted); font-weight: 400; }

options.afterRender:
// --- Reports shared helpers and states (dashboard_src/reports/_shared/states.js) ---
// Declares one name: rpt. Business Text afterRender only (it reads context.grafana).
const rpt = (() => {
  const grafana = (typeof context !== 'undefined' && context.grafana) || {};
  // A variable's value; '' when the dashboard has no such variable (replaceVariables leaves `${name}`).
  const v = (name) => { const x = grafana.replaceVariables ? String(grafana.replaceVariables('${' + name + '}')) : ''; return x === '${' + name + '}' ? '' : x; };

  const esc = (x) => String(x == null ? '' : x).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const num = (x) => (x === null || x === undefined || x === '' || isNaN(Number(x)) ? null : Number(x));
  // Thousands commas.
  const fmt = (x) => (num(x) === null ? '—' : Math.round(num(x)).toLocaleString('en-US'));
  // Percent: whole, one decimal under 10% (DESIGN Typography).
  const pct = (x) => { const n = num(x); if (n === null) { return '—'; } return (Math.abs(n) < 10 ? n.toFixed(1) : String(Math.round(n))) + '%'; };
  // Scores: two decimals.
  const score = (x) => (num(x) === null ? '—' : num(x).toFixed(2));
  const yes = (x) => x === true || x === 1 || x === 't' || x === 'true';

  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  // Postgres dates arrive as ms numbers or 'YYYY-MM-DD' strings; read them as UTC days.
  const toDate = (x) => { if (x == null || x === '') { return null; } const d = typeof x === 'number' ? new Date(x) : new Date(String(x).slice(0, 10) + 'T00:00:00Z'); return isNaN(d) ? null : d; };
  const day = (x) => { const d = toDate(x); return d ? d.getUTCDate() + '-' + MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };
  const month = (x) => { const d = toDate(x); return d ? MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };

  // Rows of the frame with refId ref, as objects.
  const rows = (ref) => {
    const series = (context.panelData && context.panelData.series) || [];
    const f = series.find((s) => s.refId === ref);
    if (!f) { return []; }
    const cols = f.fields.map((x) => [x.name, Array.from(x.values)]);
    const n = cols.length ? cols[0][1].length : 0;
    return Array.from({ length: n }, (_, i) => Object.fromEntries(cols.map(([k, vals]) => [k, vals[i]])));
  };

  // report_flags rows from a flags_json column (json_agg of {report, flag_reason, patients_n}) on each row.
  const flagsFrom = (list) => [].concat(...(list || []).map((r) => {
    let parsed = [];
    try { parsed = r.flags_json ? JSON.parse(r.flags_json) : []; } catch (e) { parsed = []; }
    return (Array.isArray(parsed) ? parsed : []).map((f) => Object.assign({ org_unit_id: r.org_unit_id, org_unit_name: r.org_unit_name }, f));
  }));

  // Variables, read in the browser so no access query is needed.
  const orgUnit = () => { const o = v('org_unit').trim(); return o && o !== '0' ? o : '0'; };
  const reportingMonth = () => v('reporting_month');
  const allowed = () => v('isAllowed') === '1';

  // The user's home unit (hidden variable home_org_unit, the home dashboard's UserOrgUnitId query).
  // '' for admins and users with access everywhere.
  const homeUnit = () => { const h = v('home_org_unit').trim(); return h && h !== '0' ? h : ''; };

  // Tabs from the builder's TABS list: [{report, title, slug}], in tab order. TABS[0] is `Start here`.
  const TABS = [{"report":"start","title":"Start here","slug":"Start-here"},{"report":"titration","title":"Stepping up","slug":"Stepping-up"},{"report":"adherence","title":"Right medicines","slug":"Right-medicines"},{"report":"fudging","title":"BP readings check","slug":"BP-readings-check"},{"report":"calling","title":"Overdue calls","slug":"Overdue-calls"},{"report":"statins","title":"Statins","slug":"Statins"}];
  // The five report tabs (every tab but `Start here`), in tab order.
  const REPORTS = TABS.filter((t) => t.report !== 'start');
  const tab = (report) => TABS.find((t) => t.report === report) || null;
  // AD-29 deep link; keeps the location and month unless given. extra: more URL parameters,
  // for example { 'var-include_new': 'true' }.
  const link = (report, org, mon, extra) => {
    const t = tab(report);
    if (!t) { return ''; }
    const more = Object.keys(extra || {}).map((k) => '&' + encodeURIComponent(k) + '=' + encodeURIComponent(extra[k])).join('');
    return '/d/heart360_reports?var-org_unit=' + encodeURIComponent(org == null ? orgUnit() : org)
      + '&var-reporting_month=' + encodeURIComponent(mon == null ? reportingMonth() : mon) + more + '&-dtab=' + encodeURIComponent(t.slug);
  };
  // A facility name that narrows this tab to that facility (UX-15). Plain text when it is already the place in view.
  const placeLink = (report, id, name) => (id == null || String(id) === orgUnit() || !tab(report)
    ? esc(name) : '<a class="rpt-link" href="' + esc(link(report, id)) + '" title="' + esc('Show ' + name + ' only') + '">' + esc(name) + '</a>');
  // `Next step` line at the end of a tab: one link, sentence case.
  const nextStep = (text, href) => '<div class="rpt-next"><span class="rpt-next-label">Next step</span>'
    + '<a class="rpt-link" href="' + esc(href) + '">' + esc(text) + ' →</a></div>';
  // Same-page links: an <a href="#some-id"> inside el scrolls the element with that id into view
  // (Grafana scrolls its own pane, so a plain hash link does not move it). Use with nextStep('...', '#id').
  // Grafana draws panels lazily: while the target is not drawn yet, the pane scrolls down a screen at a
  // time until it appears.
  const wireScroll = (el) => {
    if (!el || el.__rptScroll) { return; }
    el.__rptScroll = true;
    const pane = (node) => { let p = node.parentElement; while (p && !(p.scrollHeight > p.clientHeight && /auto|scroll/.test(getComputedStyle(p).overflowY))) { p = p.parentElement; } return p; };
    el.addEventListener('click', (e) => {
      const a = e.target.closest && e.target.closest('a[href^="#"]');
      if (!a || !el.contains(a)) { return; }
      e.preventDefault();
      const id = a.getAttribute('href').slice(1);
      const box = pane(el);
      let tries = 0;
      const go = () => {
        const t = document.getElementById(id);
        if (t) { t.scrollIntoView({ behavior: 'smooth', block: 'start' }); return; }
        if (!box || tries++ > 8) { return; }
        box.scrollTop += Math.round(box.clientHeight * 0.8);
        setTimeout(go, 350);
      };
      go();
    });
  };
  // At or below the facility level (selected_level 3 or more): patient lists and the overdue list work here.
  const atFacility = () => (num(v('selected_level')) || 0) >= 3;

  // --- States (DESIGN States, FR-32) ---
  // Grey note, no warning tone (Voice rule 8, UX-21). html is trusted markup; use esc() on data.
  const info = (html) => '<div class="rpt-info">' + html + '</div>';
  // No access: plain words and the next step. The access team names sit in a closed `Details` for the admin.
  const banner = () => {
    const teams = v('requiredGroups').replace(/<[^>]*>/g, '').trim();
    return info('<span>You cannot see this place. Pick your own area in <strong>Change location</strong> above.</span>'
      + (teams ? '<details class="rpt-details"><summary>Details for your admin</summary>Access comes from: ' + esc(teams) + '</details>' : ''));
  };
  // Shown while the page moves a user with no location to their home unit (UX-02).
  const OPENING_HOME = 'Opening your area…';
  // For views that need one facility (patient lists): a grey line with the next step.
  const PICK_FACILITY = 'Pick a facility in Change location above to see its patients.';
  const NO_DATA = 'No data for this place.';
  const NO_FACILITIES = 'No facilities for this location.';
  const NO_FLAGS = 'No facility is flagged.';
  const noData = (text) => '<div class="rpt-empty">' + esc(text || NO_DATA) + '</div>';
  // "Need at least 20; this place has 12."
  const needAtLeast = (k, n) => 'Need at least ' + fmt(k) + '; this place has ' + fmt(n) + '.';
  // Place for the subtitle: the selected name, or all locations.
  const place = (name) => (orgUnit() === '0' ? 'All locations you can access' : (name || 'This place'));

  // Thresholds from report_flag_thresholds rows ({report, key, value}).
  const thresholds = (list) => { const t = {}; (list || []).forEach((r) => { t[r.report + '.' + r.key] = num(r.value); }); return t; };

  // UX-02: a user with no location who may not see all places is moved to their home unit, keeping
  // the month and tab. Returns true when it does so.
  const goHome = () => {
    const home = homeUnit();
    if (allowed() || orgUnit() !== '0' || !home) { return false; }
    // Several panels call this on one render; move once (a later blank pick moves again).
    if (Date.now() - (window.__rptGoHome || 0) > 3000) {
      window.__rptGoHome = Date.now();
      const ls = grafana.locationService;
      if (ls && ls.partial) { ls.partial({ 'var-org_unit': home }, true); }
      else { const u = new URL(window.location.href); u.searchParams.set('var-org_unit', home); window.location.replace(u.toString()); }
    }
    return true;
  };
  // True while the panel's query is still running.
  const loading = () => !!(context.panelData && context.panelData.state === 'Loading');

  // Mount: returns the root element, or null when access is denied. The banner is drawn once per tab,
  // by the panel mounted with { banner: true } (the title strip); other panels stay empty under it.
  // A user with no location is first moved to their home unit (UX-02); meanwhile the banner panel
  // shows `Opening your area…`. opts.loading: a line to show while the query runs (null is returned).
  const mount = (selector, opts) => {
    const o = opts || {};
    const root = context.element.querySelector(selector);
    if (!root) { return null; }
    if (goHome()) { root.innerHTML = o.banner ? '<div class="rpt-muted">' + esc(OPENING_HOME) + '</div>' : ''; return null; }
    if (!allowed()) { root.innerHTML = o.banner ? banner() : ''; return null; }
    if (o.loading && loading()) { root.innerHTML = '<div class="rpt-muted rpt-loading">' + esc(o.loading) + '</div>'; return null; }
    return root;
  };

  return { v, esc, num, fmt, pct, score, yes, day, month, toDate, rows, orgUnit, reportingMonth, allowed, homeUnit,
    TABS, REPORTS, tab, link, placeLink, nextStep, wireScroll, atFacility, flagsFrom, info, banner, OPENING_HOME, PICK_FACILITY,
    NO_DATA, NO_FACILITIES, NO_FLAGS, noData, needAtLeast, place, thresholds, loading, goHome, mount };
})();
// Title strip: the question, then "{place} · {first month} to {last month}, against the average of all places".
const root = rpt.mount('.rpt-tit-title', { banner: true });
if (!root) { return; }
const w = rpt.rows('A')[0] || {};
root.innerHTML = '<h2 class="rpt-title">Are patients with high BP getting stronger treatment?</h2>'
  + '<div class="rpt-sub">' + rpt.esc(rpt.place(w.place)) + ' · ' + rpt.esc(rpt.month(w.first_month) + ' to ' + rpt.month(w.window_end))
  + ', against the average of all places</div>';

options.styles:
/* --- Reports shared styles (dashboard_src/reports/_shared/styles.css) ---
   Business Text styles. Every class starts rpt-; put class "rpt" on the panel's root div.
   Tokens: ux-hearts360-mvp-2026-11-04/DESIGN.md front matter. Table, chips, pager and banner copy
   the program dashboard's overdue list (.ovq-*). Light theme only (A40). */
.rpt {
  --text-primary: #111217; --text-muted: #6E6E6E; --border-subtle: #D8D9DA; --accent: #3D71D9;
  --controlled: #3BB231; --uncontrolled: #EEAB00; --no-visit: #ED6300;
  --flag-bar: #ED6300; --flag-row-bg: #FDF0E6; --flag-pill-bg: #FDE3CF; --flag-pill-text: #8A3A00;
  --guard-pill-text: #4E545A; --cell-missing-bg: #EFEFEF;
  font-size: 13px; line-height: 1.35; color: var(--text-primary);
}
.rpt a.rpt-link { color: #0075eb; text-decoration: none; }
.rpt a.rpt-link:hover, .rpt a.rpt-link:focus-visible { text-decoration: underline; }
.rpt-sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.rpt-muted { color: var(--text-muted); }
.rpt-empty { color: var(--text-muted); font-size: 14px; text-align: center; padding: 18px 8px; }

/* Title strip: question (card-title), then "{place} · {period}" (microcopy, muted). */
.rpt-title { font-size: 16px; font-weight: 500; margin: 0 0 2px; line-height: 1.3; }
.rpt-sub { font-size: 12px; color: var(--text-muted); line-height: 1.4; }

/* Headline strip: three equal columns, thin dividers (as panel-outcomes). */
.rpt-strip3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); height: 100%; }
.rpt-strip3 > div { padding: 2px 16px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip3 > div:first-child { border-left: 0; padding-left: 4px; }
.rpt-big { font-size: 32px; font-weight: 600; line-height: 1.1; font-variant-numeric: tabular-nums; }
.rpt-big.rpt-few { font-size: 20px; font-weight: 500; color: var(--text-muted); line-height: 1.6; }
.rpt-label { font-size: 14px; font-weight: 500; margin-top: 2px; }
.rpt-line { font-size: 12px; color: var(--text-muted); line-height: 1.4; margin-top: 2px; }

/* Look at these first: at most three items. */
.rpt-card-title { font-size: 16px; font-weight: 500; margin: 0 0 8px; }
.rpt-look { list-style: none; margin: 0; padding: 0; }
.rpt-look li { padding: 8px 0 8px 10px; border-left: 4px solid var(--flag-bar); background: var(--flag-row-bg); margin-bottom: 8px; border-radius: 0 4px 4px 0; }
.rpt-look-name { font-weight: 600; }
.rpt-look-line { font-size: 12px; line-height: 1.4; margin-top: 2px; }

/* Facility table: overdue list style. No vertical lines or stripes, light header, hover highlight. */
.rpt-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.rpt-chip { font: inherit; font-size: 12px; border: 1px solid #d9e3ff; background: transparent; color: inherit; border-radius: 14px; padding: 2px 10px; cursor: pointer; text-decoration: none; display: inline-block; white-space: nowrap; }
.rpt-chip.on { background: #0075eb; border-color: #0075eb; color: #fff; cursor: default; }
a.rpt-chip:hover, button.rpt-chip:not(.on):hover { background: #EEF3FD; }
.rpt-wrap { overflow-x: auto; }
.rpt-table { width: 100%; border-collapse: collapse; border: 0; }
.rpt-table th, .rpt-table td { border: 0 !important; border-bottom: 1px solid rgba(128,128,128,0.2) !important; padding: 8px 8px; text-align: left; vertical-align: top; }
.rpt-table thead th { background: rgba(0,117,235,0.06); color: #6e7f8d; font-size: 12px; font-weight: 600; white-space: nowrap; vertical-align: bottom; }
.rpt-table tbody th { font-weight: 400; white-space: nowrap; background: transparent; color: inherit; }
.rpt-table tbody tr:hover { background: rgba(0,117,235,0.04); }
.rpt-table .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.rpt-table thead th.num .rpt-sortbtn { text-align: right; }
.rpt-table td.rpt-why { width: 42%; min-width: 260px; }
.rpt-sortbtn { font: inherit; font-weight: 600; background: none; border: 0; padding: 0; color: inherit; cursor: pointer; }
.rpt-sortbtn:focus-visible, .rpt-chip:focus-visible, .rpt-pager button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* Flagged row: 4px orange bar and light tint. */
.rpt-table tr.rpt-flagged, .rpt-table tr.rpt-flagged:hover { background: var(--flag-row-bg); }
.rpt-table tr.rpt-flagged > th:first-child { box-shadow: inset 4px 0 0 var(--flag-bar); padding-left: 12px; }
/* All places in view: bold first row. */
.rpt-table tr.rpt-total > th, .rpt-table tr.rpt-total > td { font-weight: 700; }
.rpt-table tr.rpt-total .rpt-reason, .rpt-table tr.rpt-total .rpt-pill { font-weight: 400; }
.rpt-ctl { color: var(--controlled); font-weight: 600; }
/* Pills: text, never colour only. */
.rpt-pills { display: flex; flex-wrap: wrap; gap: 4px; }
.rpt-pill { display: inline-block; padding: 1px 8px; border-radius: 9999px; font-size: 12px; font-weight: 600; white-space: nowrap; line-height: 1.5; }
.rpt-pill-flag { background: var(--flag-pill-bg); color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-check { background: #FFFFFF; color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-guard { background: var(--cell-missing-bg); color: var(--guard-pill-text); border: 1px solid var(--cell-missing-bg); }
.rpt-reason { font-size: 12px; line-height: 1.4; margin-top: 3px; color: var(--text-primary); }
.rpt-also { font-size: 12px; margin-top: 3px; }
.rpt-also a { color: #0075eb; text-decoration: none; }
.rpt-also a:hover, .rpt-also a:focus-visible { text-decoration: underline; }
.rpt-clean { color: var(--text-muted); }
/* Pager: overdue list. */
.rpt-pager { display: flex; justify-content: center; align-items: center; gap: 12px; padding: 10px 0 2px; }
.rpt-pager button { font: inherit; width: 28px; height: 26px; border-radius: 4px; border: 1px solid #d9e3ff; background: transparent; color: inherit; cursor: pointer; }
.rpt-pager button:disabled { opacity: 0.35; cursor: default; }
/* Access banner: the overdue list's .ovq-warn. */
.rpt-warn { color: #e02424; background: rgba(224,36,36,0.05); border-left: 4px solid #e02424; padding: 8px 14px; font-size: 13px; display: flex; align-items: center; gap: 8px; border-radius: 2px; line-height: 1.4; }

/* How this is worked out. */
.rpt-note { font-size: 12px; color: var(--text-muted); line-height: 1.45; }

.rpt-demo { font-size: 12px; color: var(--text-muted); margin-top: 8px; }

/* Grey note (no warning tone, UX-21): no access, pick a facility, and other next-step lines. */
.rpt-info { color: var(--text-primary); background: #F4F5F5; border-left: 4px solid var(--border-subtle); padding: 8px 14px; font-size: 13px; line-height: 1.45; border-radius: 2px; }
.rpt-details { margin-top: 4px; font-size: 12px; color: var(--text-muted); }
.rpt-details summary { cursor: pointer; }
.rpt-loading { padding: 8px 0; }

/* Next step: one link at the end of a tab. */
.rpt-next { display: flex; align-items: baseline; gap: 10px; font-size: 14px; padding: 4px 0; }
.rpt-next-label { font-size: 12px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.03em; }
.rpt-next a.rpt-link { font-weight: 500; }

/* Start here grid: facilities down the side, reports across; each cell is a link. */
.rpt-start-do { margin: 6px 0 10px; font-size: 14px; }
.rpt-grid { table-layout: fixed; }
.rpt-grid thead th:first-child, .rpt-grid tbody th { width: 16%; }
.rpt-grid tbody th { font-weight: 600; vertical-align: middle; }
.rpt-table.rpt-grid td.rpt-cell { padding: 3px; vertical-align: middle; }
.rpt-cell a { display: block; padding: 5px 8px; border-radius: 4px; text-decoration: none; color: inherit; border: 1px solid transparent; line-height: 1.3; }
.rpt-cell a:hover, .rpt-cell a:focus-visible { border-color: var(--accent); outline: none; }
.rpt-cell-word { display: block; font-weight: 600; font-size: 13px; }
.rpt-cell-n { display: block; font-size: 12px; color: var(--text-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rpt-cell-flag a { background: var(--flag-pill-bg); border-color: var(--flag-bar); }
.rpt-cell-flag .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-flag .rpt-cell-n { color: var(--flag-pill-text); }
.rpt-cell-check a { background: #FFFFFF; border-color: var(--flag-bar); border-style: dashed; }
.rpt-cell-check .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-few a { background: var(--cell-missing-bg); }
.rpt-cell-few .rpt-cell-word { color: var(--guard-pill-text); }
.rpt-cell-fine .rpt-cell-word { font-weight: 400; color: var(--text-muted); }
.rpt-cell-none { color: var(--text-muted); text-align: center; }
.rpt-start-key { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 12px; color: var(--text-muted); margin-top: 8px; }
.rpt-start-key b { color: var(--text-primary); font-weight: 600; }

/* Headline strip with four numbers (Overdue calls). */
.rpt-strip4 { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); height: 100%; }
.rpt-strip4 > div { padding: 2px 14px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip4 > div:first-child { border-left: 0; padding-left: 4px; }

/* Monthly table, place against the average (monthly.js; Metabase titration and statins form). */
.rpt-mt th, .rpt-mt td { padding: 5px 8px; }
.rpt-mt thead tr.rpt-mt-group th { text-align: center; color: var(--text-primary); font-size: 12px; border-bottom: 0 !important; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-place { box-shadow: inset 0 -3px 0 #3D71D9; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-avg { box-shadow: inset 0 -3px 0 #9B7FD4; }
.rpt-mt .rpt-mt-gap { border-left: 1px solid var(--border-subtle) !important; }
.rpt-mt tbody tr.rpt-mt-last > * { font-weight: 700; }
.rpt-mt-few { color: var(--text-muted); font-weight: 400; }

options.afterRender:
// --- Reports shared helpers and states (dashboard_src/reports/_shared/states.js) ---
// Declares one name: rpt. Business Text afterRender only (it reads context.grafana).
const rpt = (() => {
  const grafana = (typeof context !== 'undefined' && context.grafana) || {};
  // A variable's value; '' when the dashboard has no such variable (replaceVariables leaves `${name}`).
  const v = (name) => { const x = grafana.replaceVariables ? String(grafana.replaceVariables('${' + name + '}')) : ''; return x === '${' + name + '}' ? '' : x; };

  const esc = (x) => String(x == null ? '' : x).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const num = (x) => (x === null || x === undefined || x === '' || isNaN(Number(x)) ? null : Number(x));
  // Thousands commas.
  const fmt = (x) => (num(x) === null ? '—' : Math.round(num(x)).toLocaleString('en-US'));
  // Percent: whole, one decimal under 10% (DESIGN Typography).
  const pct = (x) => { const n = num(x); if (n === null) { return '—'; } return (Math.abs(n) < 10 ? n.toFixed(1) : String(Math.round(n))) + '%'; };
  // Scores: two decimals.
  const score = (x) => (num(x) === null ? '—' : num(x).toFixed(2));
  const yes = (x) => x === true || x === 1 || x === 't' || x === 'true';

  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  // Postgres dates arrive as ms numbers or 'YYYY-MM-DD' strings; read them as UTC days.
  const toDate = (x) => { if (x == null || x === '') { return null; } const d = typeof x === 'number' ? new Date(x) : new Date(String(x).slice(0, 10) + 'T00:00:00Z'); return isNaN(d) ? null : d; };
  const day = (x) => { const d = toDate(x); return d ? d.getUTCDate() + '-' + MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };
  const month = (x) => { const d = toDate(x); return d ? MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };

  // Rows of the frame with refId ref, as objects.
  const rows = (ref) => {
    const series = (context.panelData && context.panelData.series) || [];
    const f = series.find((s) => s.refId === ref);
    if (!f) { return []; }
    const cols = f.fields.map((x) => [x.name, Array.from(x.values)]);
    const n = cols.length ? cols[0][1].length : 0;
    return Array.from({ length: n }, (_, i) => Object.fromEntries(cols.map(([k, vals]) => [k, vals[i]])));
  };

  // report_flags rows from a flags_json column (json_agg of {report, flag_reason, patients_n}) on each row.
  const flagsFrom = (list) => [].concat(...(list || []).map((r) => {
    let parsed = [];
    try { parsed = r.flags_json ? JSON.parse(r.flags_json) : []; } catch (e) { parsed = []; }
    return (Array.isArray(parsed) ? parsed : []).map((f) => Object.assign({ org_unit_id: r.org_unit_id, org_unit_name: r.org_unit_name }, f));
  }));

  // Variables, read in the browser so no access query is needed.
  const orgUnit = () => { const o = v('org_unit').trim(); return o && o !== '0' ? o : '0'; };
  const reportingMonth = () => v('reporting_month');
  const allowed = () => v('isAllowed') === '1';

  // The user's home unit (hidden variable home_org_unit, the home dashboard's UserOrgUnitId query).
  // '' for admins and users with access everywhere.
  const homeUnit = () => { const h = v('home_org_unit').trim(); return h && h !== '0' ? h : ''; };

  // Tabs from the builder's TABS list: [{report, title, slug}], in tab order. TABS[0] is `Start here`.
  const TABS = [{"report":"start","title":"Start here","slug":"Start-here"},{"report":"titration","title":"Stepping up","slug":"Stepping-up"},{"report":"adherence","title":"Right medicines","slug":"Right-medicines"},{"report":"fudging","title":"BP readings check","slug":"BP-readings-check"},{"report":"calling","title":"Overdue calls","slug":"Overdue-calls"},{"report":"statins","title":"Statins","slug":"Statins"}];
  // The five report tabs (every tab but `Start here`), in tab order.
  const REPORTS = TABS.filter((t) => t.report !== 'start');
  const tab = (report) => TABS.find((t) => t.report === report) || null;
  // AD-29 deep link; keeps the location and month unless given. extra: more URL parameters,
  // for example { 'var-include_new': 'true' }.
  const link = (report, org, mon, extra) => {
    const t = tab(report);
    if (!t) { return ''; }
    const more = Object.keys(extra || {}).map((k) => '&' + encodeURIComponent(k) + '=' + encodeURIComponent(extra[k])).join('');
    return '/d/heart360_reports?var-org_unit=' + encodeURIComponent(org == null ? orgUnit() : org)
      + '&var-reporting_month=' + encodeURIComponent(mon == null ? reportingMonth() : mon) + more + '&-dtab=' + encodeURIComponent(t.slug);
  };
  // A facility name that narrows this tab to that facility (UX-15). Plain text when it is already the place in view.
  const placeLink = (report, id, name) => (id == null || String(id) === orgUnit() || !tab(report)
    ? esc(name) : '<a class="rpt-link" href="' + esc(link(report, id)) + '" title="' + esc('Show ' + name + ' only') + '">' + esc(name) + '</a>');
  // `Next step` line at the end of a tab: one link, sentence case.
  const nextStep = (text, href) => '<div class="rpt-next"><span class="rpt-next-label">Next step</span>'
    + '<a class="rpt-link" href="' + esc(href) + '">' + esc(text) + ' →</a></div>';
  // Same-page links: an <a href="#some-id"> inside el scrolls the element with that id into view
  // (Grafana scrolls its own pane, so a plain hash link does not move it). Use with nextStep('...', '#id').
  // Grafana draws panels lazily: while the target is not drawn yet, the pane scrolls down a screen at a
  // time until it appears.
  const wireScroll = (el) => {
    if (!el || el.__rptScroll) { return; }
    el.__rptScroll = true;
    const pane = (node) => { let p = node.parentElement; while (p && !(p.scrollHeight > p.clientHeight && /auto|scroll/.test(getComputedStyle(p).overflowY))) { p = p.parentElement; } return p; };
    el.addEventListener('click', (e) => {
      const a = e.target.closest && e.target.closest('a[href^="#"]');
      if (!a || !el.contains(a)) { return; }
      e.preventDefault();
      const id = a.getAttribute('href').slice(1);
      const box = pane(el);
      let tries = 0;
      const go = () => {
        const t = document.getElementById(id);
        if (t) { t.scrollIntoView({ behavior: 'smooth', block: 'start' }); return; }
        if (!box || tries++ > 8) { return; }
        box.scrollTop += Math.round(box.clientHeight * 0.8);
        setTimeout(go, 350);
      };
      go();
    });
  };
  // At or below the facility level (selected_level 3 or more): patient lists and the overdue list work here.
  const atFacility = () => (num(v('selected_level')) || 0) >= 3;

  // --- States (DESIGN States, FR-32) ---
  // Grey note, no warning tone (Voice rule 8, UX-21). html is trusted markup; use esc() on data.
  const info = (html) => '<div class="rpt-info">' + html + '</div>';
  // No access: plain words and the next step. The access team names sit in a closed `Details` for the admin.
  const banner = () => {
    const teams = v('requiredGroups').replace(/<[^>]*>/g, '').trim();
    return info('<span>You cannot see this place. Pick your own area in <strong>Change location</strong> above.</span>'
      + (teams ? '<details class="rpt-details"><summary>Details for your admin</summary>Access comes from: ' + esc(teams) + '</details>' : ''));
  };
  // Shown while the page moves a user with no location to their home unit (UX-02).
  const OPENING_HOME = 'Opening your area…';
  // For views that need one facility (patient lists): a grey line with the next step.
  const PICK_FACILITY = 'Pick a facility in Change location above to see its patients.';
  const NO_DATA = 'No data for this place.';
  const NO_FACILITIES = 'No facilities for this location.';
  const NO_FLAGS = 'No facility is flagged.';
  const noData = (text) => '<div class="rpt-empty">' + esc(text || NO_DATA) + '</div>';
  // "Need at least 20; this place has 12."
  const needAtLeast = (k, n) => 'Need at least ' + fmt(k) + '; this place has ' + fmt(n) + '.';
  // Place for the subtitle: the selected name, or all locations.
  const place = (name) => (orgUnit() === '0' ? 'All locations you can access' : (name || 'This place'));

  // Thresholds from report_flag_thresholds rows ({report, key, value}).
  const thresholds = (list) => { const t = {}; (list || []).forEach((r) => { t[r.report + '.' + r.key] = num(r.value); }); return t; };

  // UX-02: a user with no location who may not see all places is moved to their home unit, keeping
  // the month and tab. Returns true when it does so.
  const goHome = () => {
    const home = homeUnit();
    if (allowed() || orgUnit() !== '0' || !home) { return false; }
    // Several panels call this on one render; move once (a later blank pick moves again).
    if (Date.now() - (window.__rptGoHome || 0) > 3000) {
      window.__rptGoHome = Date.now();
      const ls = grafana.locationService;
      if (ls && ls.partial) { ls.partial({ 'var-org_unit': home }, true); }
      else { const u = new URL(window.location.href); u.searchParams.set('var-org_unit', home); window.location.replace(u.toString()); }
    }
    return true;
  };
  // True while the panel's query is still running.
  const loading = () => !!(context.panelData && context.panelData.state === 'Loading');

  // Mount: returns the root element, or null when access is denied. The banner is drawn once per tab,
  // by the panel mounted with { banner: true } (the title strip); other panels stay empty under it.
  // A user with no location is first moved to their home unit (UX-02); meanwhile the banner panel
  // shows `Opening your area…`. opts.loading: a line to show while the query runs (null is returned).
  const mount = (selector, opts) => {
    const o = opts || {};
    const root = context.element.querySelector(selector);
    if (!root) { return null; }
    if (goHome()) { root.innerHTML = o.banner ? '<div class="rpt-muted">' + esc(OPENING_HOME) + '</div>' : ''; return null; }
    if (!allowed()) { root.innerHTML = o.banner ? banner() : ''; return null; }
    if (o.loading && loading()) { root.innerHTML = '<div class="rpt-muted rpt-loading">' + esc(o.loading) + '</div>'; return null; }
    return root;
  };

  return { v, esc, num, fmt, pct, score, yes, day, month, toDate, rows, orgUnit, reportingMonth, allowed, homeUnit,
    TABS, REPORTS, tab, link, placeLink, nextStep, wireScroll, atFacility, flagsFrom, info, banner, OPENING_HOME, PICK_FACILITY,
    NO_DATA, NO_FACILITIES, NO_FLAGS, noData, needAtLeast, place, thresholds, loading, goHome, mount };
})();
const col = (big, color, label, lines, title, few) => '<div' + (title ? ' title="' + rpt.esc(title) + '"' : '') + '>'
  + '<div class="rpt-big' + (few ? ' rpt-few' : '') + '"' + (color ? ' style="color:' + color + '"' : '') + '>' + rpt.esc(big) + '</div>'
  + '<div class="rpt-label">' + rpt.esc(label) + '</div>' + [].concat(lines).filter(Boolean).map((l) => '<div class="rpt-line">' + rpt.esc(l) + '</div>').join('') + '</div>';
// Headline strip: Medicine stepped up, Average of all places, High-BP visits counted.
const root = rpt.mount('.rpt-tit-head');
if (!root) { return; }
const { fmt, num, yes, pct } = rpt;
const r = rpt.rows('A')[0];
const L = ['Medicine stepped up', 'Average of all places', 'High-BP visits counted'];
if (!r) { root.innerHTML = '<div class="rpt-strip3">' + L.map((l) => col('—', '', l, rpt.NO_DATA)).join('') + '</div>'; return; }
const N = num(r.uncontrolled_visits_n) || 0, n = num(r.stepped_up_n) || 0;
const period = '90 days to ' + rpt.day(r.window_end);
let first;
if (yes(r.too_few)) {
  first = col('Too few visits', '', L[0], rpt.needAtLeast(r.min_visits, N), '', true);
} else if (num(r.titration_pct) === null) {
  first = col('—', '', L[0], rpt.NO_DATA);
} else {
  const low = num(r.flag_below_pct) !== null && num(r.titration_pct) < num(r.flag_below_pct);
  first = col(pct(r.titration_pct), low ? 'var(--flag-bar)' : 'var(--controlled)', L[0],
    [fmt(n) + ' of ' + fmt(N) + ' high-BP visits led to a stronger prescription', period]);
}
const avg = num(r.avg_pct) === null ? col('—', '', L[1], rpt.NO_DATA)
  : col(pct(r.avg_pct), '#9B7FD4', L[1], [fmt(r.avg_n) + ' of ' + fmt(r.avg_d) + ' high-BP visits, all places together', period]);
root.innerHTML = '<div class="rpt-strip3">' + first + avg
  + col(fmt(N), 'var(--text-primary)', L[2], ['Visits with BP 140/90 or above', period]) + '</div>';

options.styles:
/* --- Reports shared styles (dashboard_src/reports/_shared/styles.css) ---
   Business Text styles. Every class starts rpt-; put class "rpt" on the panel's root div.
   Tokens: ux-hearts360-mvp-2026-11-04/DESIGN.md front matter. Table, chips, pager and banner copy
   the program dashboard's overdue list (.ovq-*). Light theme only (A40). */
.rpt {
  --text-primary: #111217; --text-muted: #6E6E6E; --border-subtle: #D8D9DA; --accent: #3D71D9;
  --controlled: #3BB231; --uncontrolled: #EEAB00; --no-visit: #ED6300;
  --flag-bar: #ED6300; --flag-row-bg: #FDF0E6; --flag-pill-bg: #FDE3CF; --flag-pill-text: #8A3A00;
  --guard-pill-text: #4E545A; --cell-missing-bg: #EFEFEF;
  font-size: 13px; line-height: 1.35; color: var(--text-primary);
}
.rpt a.rpt-link { color: #0075eb; text-decoration: none; }
.rpt a.rpt-link:hover, .rpt a.rpt-link:focus-visible { text-decoration: underline; }
.rpt-sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.rpt-muted { color: var(--text-muted); }
.rpt-empty { color: var(--text-muted); font-size: 14px; text-align: center; padding: 18px 8px; }

/* Title strip: question (card-title), then "{place} · {period}" (microcopy, muted). */
.rpt-title { font-size: 16px; font-weight: 500; margin: 0 0 2px; line-height: 1.3; }
.rpt-sub { font-size: 12px; color: var(--text-muted); line-height: 1.4; }

/* Headline strip: three equal columns, thin dividers (as panel-outcomes). */
.rpt-strip3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); height: 100%; }
.rpt-strip3 > div { padding: 2px 16px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip3 > div:first-child { border-left: 0; padding-left: 4px; }
.rpt-big { font-size: 32px; font-weight: 600; line-height: 1.1; font-variant-numeric: tabular-nums; }
.rpt-big.rpt-few { font-size: 20px; font-weight: 500; color: var(--text-muted); line-height: 1.6; }
.rpt-label { font-size: 14px; font-weight: 500; margin-top: 2px; }
.rpt-line { font-size: 12px; color: var(--text-muted); line-height: 1.4; margin-top: 2px; }

/* Look at these first: at most three items. */
.rpt-card-title { font-size: 16px; font-weight: 500; margin: 0 0 8px; }
.rpt-look { list-style: none; margin: 0; padding: 0; }
.rpt-look li { padding: 8px 0 8px 10px; border-left: 4px solid var(--flag-bar); background: var(--flag-row-bg); margin-bottom: 8px; border-radius: 0 4px 4px 0; }
.rpt-look-name { font-weight: 600; }
.rpt-look-line { font-size: 12px; line-height: 1.4; margin-top: 2px; }

/* Facility table: overdue list style. No vertical lines or stripes, light header, hover highlight. */
.rpt-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.rpt-chip { font: inherit; font-size: 12px; border: 1px solid #d9e3ff; background: transparent; color: inherit; border-radius: 14px; padding: 2px 10px; cursor: pointer; text-decoration: none; display: inline-block; white-space: nowrap; }
.rpt-chip.on { background: #0075eb; border-color: #0075eb; color: #fff; cursor: default; }
a.rpt-chip:hover, button.rpt-chip:not(.on):hover { background: #EEF3FD; }
.rpt-wrap { overflow-x: auto; }
.rpt-table { width: 100%; border-collapse: collapse; border: 0; }
.rpt-table th, .rpt-table td { border: 0 !important; border-bottom: 1px solid rgba(128,128,128,0.2) !important; padding: 8px 8px; text-align: left; vertical-align: top; }
.rpt-table thead th { background: rgba(0,117,235,0.06); color: #6e7f8d; font-size: 12px; font-weight: 600; white-space: nowrap; vertical-align: bottom; }
.rpt-table tbody th { font-weight: 400; white-space: nowrap; background: transparent; color: inherit; }
.rpt-table tbody tr:hover { background: rgba(0,117,235,0.04); }
.rpt-table .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.rpt-table thead th.num .rpt-sortbtn { text-align: right; }
.rpt-table td.rpt-why { width: 42%; min-width: 260px; }
.rpt-sortbtn { font: inherit; font-weight: 600; background: none; border: 0; padding: 0; color: inherit; cursor: pointer; }
.rpt-sortbtn:focus-visible, .rpt-chip:focus-visible, .rpt-pager button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* Flagged row: 4px orange bar and light tint. */
.rpt-table tr.rpt-flagged, .rpt-table tr.rpt-flagged:hover { background: var(--flag-row-bg); }
.rpt-table tr.rpt-flagged > th:first-child { box-shadow: inset 4px 0 0 var(--flag-bar); padding-left: 12px; }
/* All places in view: bold first row. */
.rpt-table tr.rpt-total > th, .rpt-table tr.rpt-total > td { font-weight: 700; }
.rpt-table tr.rpt-total .rpt-reason, .rpt-table tr.rpt-total .rpt-pill { font-weight: 400; }
.rpt-ctl { color: var(--controlled); font-weight: 600; }
/* Pills: text, never colour only. */
.rpt-pills { display: flex; flex-wrap: wrap; gap: 4px; }
.rpt-pill { display: inline-block; padding: 1px 8px; border-radius: 9999px; font-size: 12px; font-weight: 600; white-space: nowrap; line-height: 1.5; }
.rpt-pill-flag { background: var(--flag-pill-bg); color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-check { background: #FFFFFF; color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-guard { background: var(--cell-missing-bg); color: var(--guard-pill-text); border: 1px solid var(--cell-missing-bg); }
.rpt-reason { font-size: 12px; line-height: 1.4; margin-top: 3px; color: var(--text-primary); }
.rpt-also { font-size: 12px; margin-top: 3px; }
.rpt-also a { color: #0075eb; text-decoration: none; }
.rpt-also a:hover, .rpt-also a:focus-visible { text-decoration: underline; }
.rpt-clean { color: var(--text-muted); }
/* Pager: overdue list. */
.rpt-pager { display: flex; justify-content: center; align-items: center; gap: 12px; padding: 10px 0 2px; }
.rpt-pager button { font: inherit; width: 28px; height: 26px; border-radius: 4px; border: 1px solid #d9e3ff; background: transparent; color: inherit; cursor: pointer; }
.rpt-pager button:disabled { opacity: 0.35; cursor: default; }
/* Access banner: the overdue list's .ovq-warn. */
.rpt-warn { color: #e02424; background: rgba(224,36,36,0.05); border-left: 4px solid #e02424; padding: 8px 14px; font-size: 13px; display: flex; align-items: center; gap: 8px; border-radius: 2px; line-height: 1.4; }

/* How this is worked out. */
.rpt-note { font-size: 12px; color: var(--text-muted); line-height: 1.45; }

.rpt-demo { font-size: 12px; color: var(--text-muted); margin-top: 8px; }

/* Grey note (no warning tone, UX-21): no access, pick a facility, and other next-step lines. */
.rpt-info { color: var(--text-primary); background: #F4F5F5; border-left: 4px solid var(--border-subtle); padding: 8px 14px; font-size: 13px; line-height: 1.45; border-radius: 2px; }
.rpt-details { margin-top: 4px; font-size: 12px; color: var(--text-muted); }
.rpt-details summary { cursor: pointer; }
.rpt-loading { padding: 8px 0; }

/* Next step: one link at the end of a tab. */
.rpt-next { display: flex; align-items: baseline; gap: 10px; font-size: 14px; padding: 4px 0; }
.rpt-next-label { font-size: 12px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.03em; }
.rpt-next a.rpt-link { font-weight: 500; }

/* Start here grid: facilities down the side, reports across; each cell is a link. */
.rpt-start-do { margin: 6px 0 10px; font-size: 14px; }
.rpt-grid { table-layout: fixed; }
.rpt-grid thead th:first-child, .rpt-grid tbody th { width: 16%; }
.rpt-grid tbody th { font-weight: 600; vertical-align: middle; }
.rpt-table.rpt-grid td.rpt-cell { padding: 3px; vertical-align: middle; }
.rpt-cell a { display: block; padding: 5px 8px; border-radius: 4px; text-decoration: none; color: inherit; border: 1px solid transparent; line-height: 1.3; }
.rpt-cell a:hover, .rpt-cell a:focus-visible { border-color: var(--accent); outline: none; }
.rpt-cell-word { display: block; font-weight: 600; font-size: 13px; }
.rpt-cell-n { display: block; font-size: 12px; color: var(--text-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rpt-cell-flag a { background: var(--flag-pill-bg); border-color: var(--flag-bar); }
.rpt-cell-flag .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-flag .rpt-cell-n { color: var(--flag-pill-text); }
.rpt-cell-check a { background: #FFFFFF; border-color: var(--flag-bar); border-style: dashed; }
.rpt-cell-check .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-few a { background: var(--cell-missing-bg); }
.rpt-cell-few .rpt-cell-word { color: var(--guard-pill-text); }
.rpt-cell-fine .rpt-cell-word { font-weight: 400; color: var(--text-muted); }
.rpt-cell-none { color: var(--text-muted); text-align: center; }
.rpt-start-key { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 12px; color: var(--text-muted); margin-top: 8px; }
.rpt-start-key b { color: var(--text-primary); font-weight: 600; }

/* Headline strip with four numbers (Overdue calls). */
.rpt-strip4 { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); height: 100%; }
.rpt-strip4 > div { padding: 2px 14px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip4 > div:first-child { border-left: 0; padding-left: 4px; }

/* Monthly table, place against the average (monthly.js; Metabase titration and statins form). */
.rpt-mt th, .rpt-mt td { padding: 5px 8px; }
.rpt-mt thead tr.rpt-mt-group th { text-align: center; color: var(--text-primary); font-size: 12px; border-bottom: 0 !important; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-place { box-shadow: inset 0 -3px 0 #3D71D9; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-avg { box-shadow: inset 0 -3px 0 #9B7FD4; }
.rpt-mt .rpt-mt-gap { border-left: 1px solid var(--border-subtle) !important; }
.rpt-mt tbody tr.rpt-mt-last > * { font-weight: 700; }
.rpt-mt-few { color: var(--text-muted); font-weight: 400; }

options.getOption:
// --- Reports shared ECharts tooltip (dashboard_src/reports/_shared/tip.js) ---
// Copied from the program dashboard's ECharts panels (panel-outcomes, panel-overdue): same dark card,
// bold header, "Label: 61%" over "3,901 of 6,523 patients" in lighter text.
// Declares: fmt, soft, dot, pctStr, shareRows, tip, chartColors, lineVsAverage. ECharts getOption only.
const fmt = (v) => Math.round(Number(v) || 0).toLocaleString('en-US');
const soft = (t) => '<span style="opacity:0.7">' + t + '</span>';
// Colour key for charts with more than one series. Like hearts360 (Chart.js), the colour sits on
// white with a 1px white border, so translucent series colours read the same as on the chart.
const dot = (c) => '<span style="display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:6px;'
  + (c ? 'border:1px solid #fff;background:linear-gradient(' + c + ',' + c + '),#fff' : 'border:1px solid transparent') + '"></span>';
const pctStr = (v, d) => (Number(d) ? Math.round(100 * (Number(v) || 0) / Number(d)) : 0) + '%';
// "Label: 61%" over "3,901 of 6,523 patients"; several rows become "Label: 29%, 387 patients" over "of 1,352 patients"
// (an optional third item per row adds a colour key).
const shareRows = (rows, d) => rows.length === 1
  ? [rows[0][0] + ': ' + pctStr(rows[0][1], d), soft(fmt(rows[0][1]) + ' of ' + fmt(d) + ' patients')]
  : rows.map(([label, v, c]) => dot(c) + label + ': ' + pctStr(v, d) + ', ' + fmt(v) + ' patients').concat(soft('of ' + fmt(d) + ' patients'));
// Shared tooltip. rowsFor(dataIndex, axisIndex) gives the lines under the bold header; headFor(dataIndex)
// gives the header (default: the hovered axis label, e.g. a month or a band). extra overrides any option,
// e.g. { axisPointer: { type: 'shadow' } } for bars.
const tip = (rowsFor, headFor, extra) => Object.assign({
  trigger: 'axis', backgroundColor: 'rgba(28,28,28,0.92)', borderWidth: 0, padding: [8, 12],
  textStyle: { color: '#fff', fontSize: 13 }, extraCssText: 'border-radius: 6px;',
  axisPointer: { lineStyle: { color: 'rgba(110,127,141,0.6)' } },
  formatter: (ps) => {
    const p = [].concat(ps)[0];
    if (!p || p.dataIndex == null) { return ''; }
    const head = headFor ? headFor(p.dataIndex) : p.axisValueLabel;
    return '<b>' + head + '</b><br>' + rowsFor(p.dataIndex, p.axisIndex || 0).join('<br>');
  }
}, extra || {});
// DESIGN tokens used by charts (cascade colours keep their meaning).
const chartColors = {
  controlled: '#3BB231', uncontrolled: '#EEAB00', noVisit: '#ED6300', estimated: '#DAE0E1',
  text: '#111217', muted: '#6E6E6E', axis: '#6e7f8d', grid: 'rgba(128,128,128,0.15)', axisLine: 'rgba(128,128,128,0.4)',
  step: ['#E1DEF5', '#C3BDEB', '#A49BE0', '#8578D3', '#6655BF', '#4A3A9E'], stepOther: '#B3BAC1', stepOff: '#6E7782',
  // Place against the average (Metabase monthly reports): place blue, average purple.
  place: '#3D71D9', average: '#9B7FD4'
};
// Monthly line of the place in view against the average of all places (Metabase titration and statins form).
// cfg: { months: [ms or 'YYYY-MM-DD'], place: 'District-D', value: [pct|null], avg: [pct|null],
//        placeLines: (k) => ['195 of 535 visits'], avgLines: (k) => [...], empty: 'No data for this place.' }
const lineVsAverage = (cfg) => {
  const C = chartColors;
  const M = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const mon = (x) => { const d = typeof x === 'number' ? new Date(x) : new Date(String(x).slice(0, 10) + 'T00:00:00Z'); return isNaN(d) ? '' : M[d.getUTCMonth()] + '-' + d.getUTCFullYear(); };
  const pc = (v) => (v === null || v === undefined ? '—' : (Math.abs(v) < 10 ? Number(v).toFixed(1) : String(Math.round(v))) + '%');
  if (!cfg.months.length) {
    return { graphic: cfg.empty ? [{ type: 'text', left: 'center', top: 'middle', style: { text: cfg.empty, fontSize: 14, fill: C.muted } }] : [] };
  }
  const avgName = 'Average of all places';
  const last = cfg.months.length - 1;
  const endLabel = (color) => ({ show: true, position: 'right', color: color, fontSize: 12, fontWeight: 600,
    formatter: (p) => (p.dataIndex === last ? pc(p.value) : '') });
  return {
    animation: false,
    color: [C.place, C.average],
    legend: { top: 0, left: 0, icon: 'circle', itemWidth: 10, itemHeight: 10, textStyle: { color: C.text, fontSize: 12 } },
    grid: { left: 8, right: 44, top: 32, bottom: 8, containLabel: true },
    tooltip: tip((k) => [dot(C.place) + cfg.place + ': ' + pc(cfg.value[k])].concat((cfg.placeLines ? cfg.placeLines(k) : []).map(soft))
      .concat([dot(C.average) + 'Average: ' + pc(cfg.avg[k])]).concat((cfg.avgLines ? cfg.avgLines(k) : []).map(soft)),
      (k) => mon(cfg.months[k])),
    xAxis: { type: 'category', data: cfg.months.map(mon), boundaryGap: false, axisTick: { show: false },
      axisLabel: { color: C.axis, fontSize: 11 }, axisLine: { lineStyle: { color: C.axisLine } } },
    yAxis: { type: 'value', min: 0, max: 100, interval: 25, axisLabel: { color: C.axis, fontSize: 11, formatter: (v) => v + '%' },
      splitLine: { lineStyle: { color: C.grid, type: 'dashed' } } },
    series: [
      { type: 'line', name: cfg.place, data: cfg.value, symbol: 'circle', symbolSize: 6, connectNulls: false,
        lineStyle: { width: 2, color: C.place }, itemStyle: { color: C.place }, label: endLabel(C.place) },
      { type: 'line', name: avgName, data: cfg.avg, symbol: 'circle', symbolSize: 6, connectNulls: false,
        lineStyle: { width: 2, color: C.average }, itemStyle: { color: C.average }, label: endLabel(C.average) }
    ]
  };
};
// Titration rate by month: the place in view against the average of all places (Metabase form, UX-06).
const frame = (context.panel.data.series || []).find((s) => s.refId === 'A') || (context.panel.data.series || [])[0];
function col(n) { const f = frame && frame.fields.find((x) => x.name === n); if (!f) { return []; } return Array.from(f.values && f.values.buffer ? f.values.buffer : f.values); }
const rv = context.grafana && context.grafana.replaceVariables;
const allowed = !rv || rv('${isAllowed}') === '1';
const val = (x) => (x === null || x === undefined || x === '' ? null : Number(x));
const yes = (x) => x === true || x === 1 || x === 't' || x === 'true';
const few = col('too_few').map(yes);
const d = col('follow_up_n'), n = col('titrated_n'), ad = col('average_follow_up_n'), an = col('average_titrated_n');
const place = col('place')[0] || 'All locations you can access';
return lineVsAverage({
  months: col('month_date'), place: String(place),
  value: col('rate_pct').map((v, k) => (few[k] ? null : val(v))), avg: col('average_rate_pct').map(val),
  placeLines: (k) => [few[k] ? 'Too few visits' : fmt(n[k]) + ' of ' + fmt(d[k]) + ' high-BP visits'],
  avgLines: (k) => [fmt(an[k]) + ' of ' + fmt(ad[k]) + ' high-BP visits'],
  empty: allowed ? 'No data for this place.' : ''
});

options.afterRender:
// --- Reports shared helpers and states (dashboard_src/reports/_shared/states.js) ---
// Declares one name: rpt. Business Text afterRender only (it reads context.grafana).
const rpt = (() => {
  const grafana = (typeof context !== 'undefined' && context.grafana) || {};
  // A variable's value; '' when the dashboard has no such variable (replaceVariables leaves `${name}`).
  const v = (name) => { const x = grafana.replaceVariables ? String(grafana.replaceVariables('${' + name + '}')) : ''; return x === '${' + name + '}' ? '' : x; };

  const esc = (x) => String(x == null ? '' : x).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const num = (x) => (x === null || x === undefined || x === '' || isNaN(Number(x)) ? null : Number(x));
  // Thousands commas.
  const fmt = (x) => (num(x) === null ? '—' : Math.round(num(x)).toLocaleString('en-US'));
  // Percent: whole, one decimal under 10% (DESIGN Typography).
  const pct = (x) => { const n = num(x); if (n === null) { return '—'; } return (Math.abs(n) < 10 ? n.toFixed(1) : String(Math.round(n))) + '%'; };
  // Scores: two decimals.
  const score = (x) => (num(x) === null ? '—' : num(x).toFixed(2));
  const yes = (x) => x === true || x === 1 || x === 't' || x === 'true';

  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  // Postgres dates arrive as ms numbers or 'YYYY-MM-DD' strings; read them as UTC days.
  const toDate = (x) => { if (x == null || x === '') { return null; } const d = typeof x === 'number' ? new Date(x) : new Date(String(x).slice(0, 10) + 'T00:00:00Z'); return isNaN(d) ? null : d; };
  const day = (x) => { const d = toDate(x); return d ? d.getUTCDate() + '-' + MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };
  const month = (x) => { const d = toDate(x); return d ? MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };

  // Rows of the frame with refId ref, as objects.
  const rows = (ref) => {
    const series = (context.panelData && context.panelData.series) || [];
    const f = series.find((s) => s.refId === ref);
    if (!f) { return []; }
    const cols = f.fields.map((x) => [x.name, Array.from(x.values)]);
    const n = cols.length ? cols[0][1].length : 0;
    return Array.from({ length: n }, (_, i) => Object.fromEntries(cols.map(([k, vals]) => [k, vals[i]])));
  };

  // report_flags rows from a flags_json column (json_agg of {report, flag_reason, patients_n}) on each row.
  const flagsFrom = (list) => [].concat(...(list || []).map((r) => {
    let parsed = [];
    try { parsed = r.flags_json ? JSON.parse(r.flags_json) : []; } catch (e) { parsed = []; }
    return (Array.isArray(parsed) ? parsed : []).map((f) => Object.assign({ org_unit_id: r.org_unit_id, org_unit_name: r.org_unit_name }, f));
  }));

  // Variables, read in the browser so no access query is needed.
  const orgUnit = () => { const o = v('org_unit').trim(); return o && o !== '0' ? o : '0'; };
  const reportingMonth = () => v('reporting_month');
  const allowed = () => v('isAllowed') === '1';

  // The user's home unit (hidden variable home_org_unit, the home dashboard's UserOrgUnitId query).
  // '' for admins and users with access everywhere.
  const homeUnit = () => { const h = v('home_org_unit').trim(); return h && h !== '0' ? h : ''; };

  // Tabs from the builder's TABS list: [{report, title, slug}], in tab order. TABS[0] is `Start here`.
  const TABS = [{"report":"start","title":"Start here","slug":"Start-here"},{"report":"titration","title":"Stepping up","slug":"Stepping-up"},{"report":"adherence","title":"Right medicines","slug":"Right-medicines"},{"report":"fudging","title":"BP readings check","slug":"BP-readings-check"},{"report":"calling","title":"Overdue calls","slug":"Overdue-calls"},{"report":"statins","title":"Statins","slug":"Statins"}];
  // The five report tabs (every tab but `Start here`), in tab order.
  const REPORTS = TABS.filter((t) => t.report !== 'start');
  const tab = (report) => TABS.find((t) => t.report === report) || null;
  // AD-29 deep link; keeps the location and month unless given. extra: more URL parameters,
  // for example { 'var-include_new': 'true' }.
  const link = (report, org, mon, extra) => {
    const t = tab(report);
    if (!t) { return ''; }
    const more = Object.keys(extra || {}).map((k) => '&' + encodeURIComponent(k) + '=' + encodeURIComponent(extra[k])).join('');
    return '/d/heart360_reports?var-org_unit=' + encodeURIComponent(org == null ? orgUnit() : org)
      + '&var-reporting_month=' + encodeURIComponent(mon == null ? reportingMonth() : mon) + more + '&-dtab=' + encodeURIComponent(t.slug);
  };
  // A facility name that narrows this tab to that facility (UX-15). Plain text when it is already the place in view.
  const placeLink = (report, id, name) => (id == null || String(id) === orgUnit() || !tab(report)
    ? esc(name) : '<a class="rpt-link" href="' + esc(link(report, id)) + '" title="' + esc('Show ' + name + ' only') + '">' + esc(name) + '</a>');
  // `Next step` line at the end of a tab: one link, sentence case.
  const nextStep = (text, href) => '<div class="rpt-next"><span class="rpt-next-label">Next step</span>'
    + '<a class="rpt-link" href="' + esc(href) + '">' + esc(text) + ' →</a></div>';
  // Same-page links: an <a href="#some-id"> inside el scrolls the element with that id into view
  // (Grafana scrolls its own pane, so a plain hash link does not move it). Use with nextStep('...', '#id').
  // Grafana draws panels lazily: while the target is not drawn yet, the pane scrolls down a screen at a
  // time until it appears.
  const wireScroll = (el) => {
    if (!el || el.__rptScroll) { return; }
    el.__rptScroll = true;
    const pane = (node) => { let p = node.parentElement; while (p && !(p.scrollHeight > p.clientHeight && /auto|scroll/.test(getComputedStyle(p).overflowY))) { p = p.parentElement; } return p; };
    el.addEventListener('click', (e) => {
      const a = e.target.closest && e.target.closest('a[href^="#"]');
      if (!a || !el.contains(a)) { return; }
      e.preventDefault();
      const id = a.getAttribute('href').slice(1);
      const box = pane(el);
      let tries = 0;
      const go = () => {
        const t = document.getElementById(id);
        if (t) { t.scrollIntoView({ behavior: 'smooth', block: 'start' }); return; }
        if (!box || tries++ > 8) { return; }
        box.scrollTop += Math.round(box.clientHeight * 0.8);
        setTimeout(go, 350);
      };
      go();
    });
  };
  // At or below the facility level (selected_level 3 or more): patient lists and the overdue list work here.
  const atFacility = () => (num(v('selected_level')) || 0) >= 3;

  // --- States (DESIGN States, FR-32) ---
  // Grey note, no warning tone (Voice rule 8, UX-21). html is trusted markup; use esc() on data.
  const info = (html) => '<div class="rpt-info">' + html + '</div>';
  // No access: plain words and the next step. The access team names sit in a closed `Details` for the admin.
  const banner = () => {
    const teams = v('requiredGroups').replace(/<[^>]*>/g, '').trim();
    return info('<span>You cannot see this place. Pick your own area in <strong>Change location</strong> above.</span>'
      + (teams ? '<details class="rpt-details"><summary>Details for your admin</summary>Access comes from: ' + esc(teams) + '</details>' : ''));
  };
  // Shown while the page moves a user with no location to their home unit (UX-02).
  const OPENING_HOME = 'Opening your area…';
  // For views that need one facility (patient lists): a grey line with the next step.
  const PICK_FACILITY = 'Pick a facility in Change location above to see its patients.';
  const NO_DATA = 'No data for this place.';
  const NO_FACILITIES = 'No facilities for this location.';
  const NO_FLAGS = 'No facility is flagged.';
  const noData = (text) => '<div class="rpt-empty">' + esc(text || NO_DATA) + '</div>';
  // "Need at least 20; this place has 12."
  const needAtLeast = (k, n) => 'Need at least ' + fmt(k) + '; this place has ' + fmt(n) + '.';
  // Place for the subtitle: the selected name, or all locations.
  const place = (name) => (orgUnit() === '0' ? 'All locations you can access' : (name || 'This place'));

  // Thresholds from report_flag_thresholds rows ({report, key, value}).
  const thresholds = (list) => { const t = {}; (list || []).forEach((r) => { t[r.report + '.' + r.key] = num(r.value); }); return t; };

  // UX-02: a user with no location who may not see all places is moved to their home unit, keeping
  // the month and tab. Returns true when it does so.
  const goHome = () => {
    const home = homeUnit();
    if (allowed() || orgUnit() !== '0' || !home) { return false; }
    // Several panels call this on one render; move once (a later blank pick moves again).
    if (Date.now() - (window.__rptGoHome || 0) > 3000) {
      window.__rptGoHome = Date.now();
      const ls = grafana.locationService;
      if (ls && ls.partial) { ls.partial({ 'var-org_unit': home }, true); }
      else { const u = new URL(window.location.href); u.searchParams.set('var-org_unit', home); window.location.replace(u.toString()); }
    }
    return true;
  };
  // True while the panel's query is still running.
  const loading = () => !!(context.panelData && context.panelData.state === 'Loading');

  // Mount: returns the root element, or null when access is denied. The banner is drawn once per tab,
  // by the panel mounted with { banner: true } (the title strip); other panels stay empty under it.
  // A user with no location is first moved to their home unit (UX-02); meanwhile the banner panel
  // shows `Opening your area…`. opts.loading: a line to show while the query runs (null is returned).
  const mount = (selector, opts) => {
    const o = opts || {};
    const root = context.element.querySelector(selector);
    if (!root) { return null; }
    if (goHome()) { root.innerHTML = o.banner ? '<div class="rpt-muted">' + esc(OPENING_HOME) + '</div>' : ''; return null; }
    if (!allowed()) { root.innerHTML = o.banner ? banner() : ''; return null; }
    if (o.loading && loading()) { root.innerHTML = '<div class="rpt-muted rpt-loading">' + esc(o.loading) + '</div>'; return null; }
    return root;
  };

  return { v, esc, num, fmt, pct, score, yes, day, month, toDate, rows, orgUnit, reportingMonth, allowed, homeUnit,
    TABS, REPORTS, tab, link, placeLink, nextStep, wireScroll, atFacility, flagsFrom, info, banner, OPENING_HOME, PICK_FACILITY,
    NO_DATA, NO_FACILITIES, NO_FLAGS, noData, needAtLeast, place, thresholds, loading, goHome, mount };
})();
// --- Reports shared monthly table (dashboard_src/reports/_shared/monthly.js) ---
// Declares one name: rptMonthly. Needs states.js (rpt) included first. Business Text afterRender only.
// The Metabase monthly form (titration, statins): one row per month, oldest first, the place in view
// beside the average of all places. The newest month is bold; it equals the tab's headline.
//
// rptMonthly(root, {
//   rows: rpt.rows('A'),                 // report_<name>_monthly rows WHERE is_selected, by month_date
//   place: 'District-D',                 // name over the place columns
//   cols: [                              // the same columns for the place and the average
//     { label: 'High-BP visits', place: 'follow_up_n', avg: 'average_follow_up_n' },
//     { label: 'Stepped up', place: 'titrated_n', avg: 'average_titrated_n' },
//     { label: 'Rate', place: 'rate_pct', avg: 'average_rate_pct', pct: true, of: [1, 0] },  // of: [n col, d col]
//   ],
//   tooFew: 'Too few visits',            // shown in the place's percent cell of a too_few month
//   caption: 'Stepped up by month, ...',
// })
const rptMonthly = (root, cfg) => {
  const { esc, fmt, num, yes } = rpt;
  const rows = (cfg.rows || []).slice().sort((a, b) => (rpt.toDate(a.month_date) || 0) - (rpt.toDate(b.month_date) || 0));
  if (!rows.length) { root.innerHTML = rpt.noData(); return; }
  const cols = cfg.cols || [];
  const cell = (r, c, side, first) => {
    const key = c[side];
    const cls = 'num' + (first ? ' rpt-mt-gap' : '');
    if (!c.pct) { return '<td class="' + cls + '">' + fmt(r[key]) + '</td>'; }
    if (side === 'place' && yes(r.too_few)) {
      return '<td class="' + cls + '"><span class="rpt-mt-few" title="' + esc(cfg.tooFew || 'Too few') + '">—</span></td>';
    }
    const n = c.of ? r[cols[c.of[0]][side]] : null, d = c.of ? r[cols[c.of[1]][side]] : null;
    const title = num(r[key]) === null ? '' : String(num(r[key])) + '%' + (c.of ? ' · ' + fmt(n) + ' of ' + fmt(d) : '');
    return '<td class="' + cls + '"' + (title ? ' title="' + esc(title) + '"' : '') + '>' + rpt.pct(r[key]) + '</td>';
  };
  const n = cols.length;
  root.innerHTML = '<div class="rpt-wrap"><table class="rpt-table rpt-mt">'
    + '<caption class="rpt-sr">' + esc(cfg.caption || 'By month, against the average of all places.') + '</caption>'
    + '<thead><tr class="rpt-mt-group"><th scope="col"></th>'
    + '<th scope="colgroup" colspan="' + n + '" class="rpt-mt-place rpt-mt-gap">' + esc(cfg.place) + '</th>'
    + '<th scope="colgroup" colspan="' + n + '" class="rpt-mt-avg rpt-mt-gap">Average of all places</th></tr>'
    + '<tr><th scope="col">Month</th>'
    + ['place', 'avg'].map((side) => cols.map((c, i) => '<th scope="col" class="num' + (i ? '' : ' rpt-mt-gap') + '">' + esc(c.label) + '</th>').join('')).join('')
    + '</tr></thead><tbody>'
    + rows.map((r, k) => '<tr' + (k === rows.length - 1 ? ' class="rpt-mt-last"' : '') + '><th scope="row">' + esc(rpt.month(r.month_date)) + '</th>'
      + cols.map((c, i) => cell(r, c, 'place', !i)).join('') + cols.map((c, i) => cell(r, c, 'avg', !i)).join('') + '</tr>').join('')
    + '</tbody></table></div>';
};
// The Metabase titration table: month, high-BP visits, stepped up, rate; the place beside the average.
const root = rpt.mount('.rpt-tit-monthly');
if (!root) { return; }
const rows = rpt.rows('A');
rptMonthly(root, {
  rows: rows,
  place: rpt.place(rows.length ? rows[0].place : ''),
  cols: [
    { label: 'High-BP visits', place: 'follow_up_n', avg: 'average_follow_up_n' },
    { label: 'Stepped up', place: 'titrated_n', avg: 'average_titrated_n' },
    { label: 'Rate', place: 'rate_pct', avg: 'average_rate_pct', pct: true, of: [1, 0] }
  ],
  tooFew: 'Too few visits',
  caption: 'High-BP visits stepped up by month, against the average of all places.'
});

options.styles:
/* --- Reports shared styles (dashboard_src/reports/_shared/styles.css) ---
   Business Text styles. Every class starts rpt-; put class "rpt" on the panel's root div.
   Tokens: ux-hearts360-mvp-2026-11-04/DESIGN.md front matter. Table, chips, pager and banner copy
   the program dashboard's overdue list (.ovq-*). Light theme only (A40). */
.rpt {
  --text-primary: #111217; --text-muted: #6E6E6E; --border-subtle: #D8D9DA; --accent: #3D71D9;
  --controlled: #3BB231; --uncontrolled: #EEAB00; --no-visit: #ED6300;
  --flag-bar: #ED6300; --flag-row-bg: #FDF0E6; --flag-pill-bg: #FDE3CF; --flag-pill-text: #8A3A00;
  --guard-pill-text: #4E545A; --cell-missing-bg: #EFEFEF;
  font-size: 13px; line-height: 1.35; color: var(--text-primary);
}
.rpt a.rpt-link { color: #0075eb; text-decoration: none; }
.rpt a.rpt-link:hover, .rpt a.rpt-link:focus-visible { text-decoration: underline; }
.rpt-sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.rpt-muted { color: var(--text-muted); }
.rpt-empty { color: var(--text-muted); font-size: 14px; text-align: center; padding: 18px 8px; }

/* Title strip: question (card-title), then "{place} · {period}" (microcopy, muted). */
.rpt-title { font-size: 16px; font-weight: 500; margin: 0 0 2px; line-height: 1.3; }
.rpt-sub { font-size: 12px; color: var(--text-muted); line-height: 1.4; }

/* Headline strip: three equal columns, thin dividers (as panel-outcomes). */
.rpt-strip3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); height: 100%; }
.rpt-strip3 > div { padding: 2px 16px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip3 > div:first-child { border-left: 0; padding-left: 4px; }
.rpt-big { font-size: 32px; font-weight: 600; line-height: 1.1; font-variant-numeric: tabular-nums; }
.rpt-big.rpt-few { font-size: 20px; font-weight: 500; color: var(--text-muted); line-height: 1.6; }
.rpt-label { font-size: 14px; font-weight: 500; margin-top: 2px; }
.rpt-line { font-size: 12px; color: var(--text-muted); line-height: 1.4; margin-top: 2px; }

/* Look at these first: at most three items. */
.rpt-card-title { font-size: 16px; font-weight: 500; margin: 0 0 8px; }
.rpt-look { list-style: none; margin: 0; padding: 0; }
.rpt-look li { padding: 8px 0 8px 10px; border-left: 4px solid var(--flag-bar); background: var(--flag-row-bg); margin-bottom: 8px; border-radius: 0 4px 4px 0; }
.rpt-look-name { font-weight: 600; }
.rpt-look-line { font-size: 12px; line-height: 1.4; margin-top: 2px; }

/* Facility table: overdue list style. No vertical lines or stripes, light header, hover highlight. */
.rpt-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.rpt-chip { font: inherit; font-size: 12px; border: 1px solid #d9e3ff; background: transparent; color: inherit; border-radius: 14px; padding: 2px 10px; cursor: pointer; text-decoration: none; display: inline-block; white-space: nowrap; }
.rpt-chip.on { background: #0075eb; border-color: #0075eb; color: #fff; cursor: default; }
a.rpt-chip:hover, button.rpt-chip:not(.on):hover { background: #EEF3FD; }
.rpt-wrap { overflow-x: auto; }
.rpt-table { width: 100%; border-collapse: collapse; border: 0; }
.rpt-table th, .rpt-table td { border: 0 !important; border-bottom: 1px solid rgba(128,128,128,0.2) !important; padding: 8px 8px; text-align: left; vertical-align: top; }
.rpt-table thead th { background: rgba(0,117,235,0.06); color: #6e7f8d; font-size: 12px; font-weight: 600; white-space: nowrap; vertical-align: bottom; }
.rpt-table tbody th { font-weight: 400; white-space: nowrap; background: transparent; color: inherit; }
.rpt-table tbody tr:hover { background: rgba(0,117,235,0.04); }
.rpt-table .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.rpt-table thead th.num .rpt-sortbtn { text-align: right; }
.rpt-table td.rpt-why { width: 42%; min-width: 260px; }
.rpt-sortbtn { font: inherit; font-weight: 600; background: none; border: 0; padding: 0; color: inherit; cursor: pointer; }
.rpt-sortbtn:focus-visible, .rpt-chip:focus-visible, .rpt-pager button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* Flagged row: 4px orange bar and light tint. */
.rpt-table tr.rpt-flagged, .rpt-table tr.rpt-flagged:hover { background: var(--flag-row-bg); }
.rpt-table tr.rpt-flagged > th:first-child { box-shadow: inset 4px 0 0 var(--flag-bar); padding-left: 12px; }
/* All places in view: bold first row. */
.rpt-table tr.rpt-total > th, .rpt-table tr.rpt-total > td { font-weight: 700; }
.rpt-table tr.rpt-total .rpt-reason, .rpt-table tr.rpt-total .rpt-pill { font-weight: 400; }
.rpt-ctl { color: var(--controlled); font-weight: 600; }
/* Pills: text, never colour only. */
.rpt-pills { display: flex; flex-wrap: wrap; gap: 4px; }
.rpt-pill { display: inline-block; padding: 1px 8px; border-radius: 9999px; font-size: 12px; font-weight: 600; white-space: nowrap; line-height: 1.5; }
.rpt-pill-flag { background: var(--flag-pill-bg); color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-check { background: #FFFFFF; color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-guard { background: var(--cell-missing-bg); color: var(--guard-pill-text); border: 1px solid var(--cell-missing-bg); }
.rpt-reason { font-size: 12px; line-height: 1.4; margin-top: 3px; color: var(--text-primary); }
.rpt-also { font-size: 12px; margin-top: 3px; }
.rpt-also a { color: #0075eb; text-decoration: none; }
.rpt-also a:hover, .rpt-also a:focus-visible { text-decoration: underline; }
.rpt-clean { color: var(--text-muted); }
/* Pager: overdue list. */
.rpt-pager { display: flex; justify-content: center; align-items: center; gap: 12px; padding: 10px 0 2px; }
.rpt-pager button { font: inherit; width: 28px; height: 26px; border-radius: 4px; border: 1px solid #d9e3ff; background: transparent; color: inherit; cursor: pointer; }
.rpt-pager button:disabled { opacity: 0.35; cursor: default; }
/* Access banner: the overdue list's .ovq-warn. */
.rpt-warn { color: #e02424; background: rgba(224,36,36,0.05); border-left: 4px solid #e02424; padding: 8px 14px; font-size: 13px; display: flex; align-items: center; gap: 8px; border-radius: 2px; line-height: 1.4; }

/* How this is worked out. */
.rpt-note { font-size: 12px; color: var(--text-muted); line-height: 1.45; }

.rpt-demo { font-size: 12px; color: var(--text-muted); margin-top: 8px; }

/* Grey note (no warning tone, UX-21): no access, pick a facility, and other next-step lines. */
.rpt-info { color: var(--text-primary); background: #F4F5F5; border-left: 4px solid var(--border-subtle); padding: 8px 14px; font-size: 13px; line-height: 1.45; border-radius: 2px; }
.rpt-details { margin-top: 4px; font-size: 12px; color: var(--text-muted); }
.rpt-details summary { cursor: pointer; }
.rpt-loading { padding: 8px 0; }

/* Next step: one link at the end of a tab. */
.rpt-next { display: flex; align-items: baseline; gap: 10px; font-size: 14px; padding: 4px 0; }
.rpt-next-label { font-size: 12px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.03em; }
.rpt-next a.rpt-link { font-weight: 500; }

/* Start here grid: facilities down the side, reports across; each cell is a link. */
.rpt-start-do { margin: 6px 0 10px; font-size: 14px; }
.rpt-grid { table-layout: fixed; }
.rpt-grid thead th:first-child, .rpt-grid tbody th { width: 16%; }
.rpt-grid tbody th { font-weight: 600; vertical-align: middle; }
.rpt-table.rpt-grid td.rpt-cell { padding: 3px; vertical-align: middle; }
.rpt-cell a { display: block; padding: 5px 8px; border-radius: 4px; text-decoration: none; color: inherit; border: 1px solid transparent; line-height: 1.3; }
.rpt-cell a:hover, .rpt-cell a:focus-visible { border-color: var(--accent); outline: none; }
.rpt-cell-word { display: block; font-weight: 600; font-size: 13px; }
.rpt-cell-n { display: block; font-size: 12px; color: var(--text-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rpt-cell-flag a { background: var(--flag-pill-bg); border-color: var(--flag-bar); }
.rpt-cell-flag .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-flag .rpt-cell-n { color: var(--flag-pill-text); }
.rpt-cell-check a { background: #FFFFFF; border-color: var(--flag-bar); border-style: dashed; }
.rpt-cell-check .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-few a { background: var(--cell-missing-bg); }
.rpt-cell-few .rpt-cell-word { color: var(--guard-pill-text); }
.rpt-cell-fine .rpt-cell-word { font-weight: 400; color: var(--text-muted); }
.rpt-cell-none { color: var(--text-muted); text-align: center; }
.rpt-start-key { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 12px; color: var(--text-muted); margin-top: 8px; }
.rpt-start-key b { color: var(--text-primary); font-weight: 600; }

/* Headline strip with four numbers (Overdue calls). */
.rpt-strip4 { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); height: 100%; }
.rpt-strip4 > div { padding: 2px 14px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip4 > div:first-child { border-left: 0; padding-left: 4px; }

/* Monthly table, place against the average (monthly.js; Metabase titration and statins form). */
.rpt-mt th, .rpt-mt td { padding: 5px 8px; }
.rpt-mt thead tr.rpt-mt-group th { text-align: center; color: var(--text-primary); font-size: 12px; border-bottom: 0 !important; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-place { box-shadow: inset 0 -3px 0 #3D71D9; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-avg { box-shadow: inset 0 -3px 0 #9B7FD4; }
.rpt-mt .rpt-mt-gap { border-left: 1px solid var(--border-subtle) !important; }
.rpt-mt tbody tr.rpt-mt-last > * { font-weight: 700; }
.rpt-mt-few { color: var(--text-muted); font-weight: 400; }

options.afterRender:
// --- Reports shared helpers and states (dashboard_src/reports/_shared/states.js) ---
// Declares one name: rpt. Business Text afterRender only (it reads context.grafana).
const rpt = (() => {
  const grafana = (typeof context !== 'undefined' && context.grafana) || {};
  // A variable's value; '' when the dashboard has no such variable (replaceVariables leaves `${name}`).
  const v = (name) => { const x = grafana.replaceVariables ? String(grafana.replaceVariables('${' + name + '}')) : ''; return x === '${' + name + '}' ? '' : x; };

  const esc = (x) => String(x == null ? '' : x).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const num = (x) => (x === null || x === undefined || x === '' || isNaN(Number(x)) ? null : Number(x));
  // Thousands commas.
  const fmt = (x) => (num(x) === null ? '—' : Math.round(num(x)).toLocaleString('en-US'));
  // Percent: whole, one decimal under 10% (DESIGN Typography).
  const pct = (x) => { const n = num(x); if (n === null) { return '—'; } return (Math.abs(n) < 10 ? n.toFixed(1) : String(Math.round(n))) + '%'; };
  // Scores: two decimals.
  const score = (x) => (num(x) === null ? '—' : num(x).toFixed(2));
  const yes = (x) => x === true || x === 1 || x === 't' || x === 'true';

  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  // Postgres dates arrive as ms numbers or 'YYYY-MM-DD' strings; read them as UTC days.
  const toDate = (x) => { if (x == null || x === '') { return null; } const d = typeof x === 'number' ? new Date(x) : new Date(String(x).slice(0, 10) + 'T00:00:00Z'); return isNaN(d) ? null : d; };
  const day = (x) => { const d = toDate(x); return d ? d.getUTCDate() + '-' + MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };
  const month = (x) => { const d = toDate(x); return d ? MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };

  // Rows of the frame with refId ref, as objects.
  const rows = (ref) => {
    const series = (context.panelData && context.panelData.series) || [];
    const f = series.find((s) => s.refId === ref);
    if (!f) { return []; }
    const cols = f.fields.map((x) => [x.name, Array.from(x.values)]);
    const n = cols.length ? cols[0][1].length : 0;
    return Array.from({ length: n }, (_, i) => Object.fromEntries(cols.map(([k, vals]) => [k, vals[i]])));
  };

  // report_flags rows from a flags_json column (json_agg of {report, flag_reason, patients_n}) on each row.
  const flagsFrom = (list) => [].concat(...(list || []).map((r) => {
    let parsed = [];
    try { parsed = r.flags_json ? JSON.parse(r.flags_json) : []; } catch (e) { parsed = []; }
    return (Array.isArray(parsed) ? parsed : []).map((f) => Object.assign({ org_unit_id: r.org_unit_id, org_unit_name: r.org_unit_name }, f));
  }));

  // Variables, read in the browser so no access query is needed.
  const orgUnit = () => { const o = v('org_unit').trim(); return o && o !== '0' ? o : '0'; };
  const reportingMonth = () => v('reporting_month');
  const allowed = () => v('isAllowed') === '1';

  // The user's home unit (hidden variable home_org_unit, the home dashboard's UserOrgUnitId query).
  // '' for admins and users with access everywhere.
  const homeUnit = () => { const h = v('home_org_unit').trim(); return h && h !== '0' ? h : ''; };

  // Tabs from the builder's TABS list: [{report, title, slug}], in tab order. TABS[0] is `Start here`.
  const TABS = [{"report":"start","title":"Start here","slug":"Start-here"},{"report":"titration","title":"Stepping up","slug":"Stepping-up"},{"report":"adherence","title":"Right medicines","slug":"Right-medicines"},{"report":"fudging","title":"BP readings check","slug":"BP-readings-check"},{"report":"calling","title":"Overdue calls","slug":"Overdue-calls"},{"report":"statins","title":"Statins","slug":"Statins"}];
  // The five report tabs (every tab but `Start here`), in tab order.
  const REPORTS = TABS.filter((t) => t.report !== 'start');
  const tab = (report) => TABS.find((t) => t.report === report) || null;
  // AD-29 deep link; keeps the location and month unless given. extra: more URL parameters,
  // for example { 'var-include_new': 'true' }.
  const link = (report, org, mon, extra) => {
    const t = tab(report);
    if (!t) { return ''; }
    const more = Object.keys(extra || {}).map((k) => '&' + encodeURIComponent(k) + '=' + encodeURIComponent(extra[k])).join('');
    return '/d/heart360_reports?var-org_unit=' + encodeURIComponent(org == null ? orgUnit() : org)
      + '&var-reporting_month=' + encodeURIComponent(mon == null ? reportingMonth() : mon) + more + '&-dtab=' + encodeURIComponent(t.slug);
  };
  // A facility name that narrows this tab to that facility (UX-15). Plain text when it is already the place in view.
  const placeLink = (report, id, name) => (id == null || String(id) === orgUnit() || !tab(report)
    ? esc(name) : '<a class="rpt-link" href="' + esc(link(report, id)) + '" title="' + esc('Show ' + name + ' only') + '">' + esc(name) + '</a>');
  // `Next step` line at the end of a tab: one link, sentence case.
  const nextStep = (text, href) => '<div class="rpt-next"><span class="rpt-next-label">Next step</span>'
    + '<a class="rpt-link" href="' + esc(href) + '">' + esc(text) + ' →</a></div>';
  // Same-page links: an <a href="#some-id"> inside el scrolls the element with that id into view
  // (Grafana scrolls its own pane, so a plain hash link does not move it). Use with nextStep('...', '#id').
  // Grafana draws panels lazily: while the target is not drawn yet, the pane scrolls down a screen at a
  // time until it appears.
  const wireScroll = (el) => {
    if (!el || el.__rptScroll) { return; }
    el.__rptScroll = true;
    const pane = (node) => { let p = node.parentElement; while (p && !(p.scrollHeight > p.clientHeight && /auto|scroll/.test(getComputedStyle(p).overflowY))) { p = p.parentElement; } return p; };
    el.addEventListener('click', (e) => {
      const a = e.target.closest && e.target.closest('a[href^="#"]');
      if (!a || !el.contains(a)) { return; }
      e.preventDefault();
      const id = a.getAttribute('href').slice(1);
      const box = pane(el);
      let tries = 0;
      const go = () => {
        const t = document.getElementById(id);
        if (t) { t.scrollIntoView({ behavior: 'smooth', block: 'start' }); return; }
        if (!box || tries++ > 8) { return; }
        box.scrollTop += Math.round(box.clientHeight * 0.8);
        setTimeout(go, 350);
      };
      go();
    });
  };
  // At or below the facility level (selected_level 3 or more): patient lists and the overdue list work here.
  const atFacility = () => (num(v('selected_level')) || 0) >= 3;

  // --- States (DESIGN States, FR-32) ---
  // Grey note, no warning tone (Voice rule 8, UX-21). html is trusted markup; use esc() on data.
  const info = (html) => '<div class="rpt-info">' + html + '</div>';
  // No access: plain words and the next step. The access team names sit in a closed `Details` for the admin.
  const banner = () => {
    const teams = v('requiredGroups').replace(/<[^>]*>/g, '').trim();
    return info('<span>You cannot see this place. Pick your own area in <strong>Change location</strong> above.</span>'
      + (teams ? '<details class="rpt-details"><summary>Details for your admin</summary>Access comes from: ' + esc(teams) + '</details>' : ''));
  };
  // Shown while the page moves a user with no location to their home unit (UX-02).
  const OPENING_HOME = 'Opening your area…';
  // For views that need one facility (patient lists): a grey line with the next step.
  const PICK_FACILITY = 'Pick a facility in Change location above to see its patients.';
  const NO_DATA = 'No data for this place.';
  const NO_FACILITIES = 'No facilities for this location.';
  const NO_FLAGS = 'No facility is flagged.';
  const noData = (text) => '<div class="rpt-empty">' + esc(text || NO_DATA) + '</div>';
  // "Need at least 20; this place has 12."
  const needAtLeast = (k, n) => 'Need at least ' + fmt(k) + '; this place has ' + fmt(n) + '.';
  // Place for the subtitle: the selected name, or all locations.
  const place = (name) => (orgUnit() === '0' ? 'All locations you can access' : (name || 'This place'));

  // Thresholds from report_flag_thresholds rows ({report, key, value}).
  const thresholds = (list) => { const t = {}; (list || []).forEach((r) => { t[r.report + '.' + r.key] = num(r.value); }); return t; };

  // UX-02: a user with no location who may not see all places is moved to their home unit, keeping
  // the month and tab. Returns true when it does so.
  const goHome = () => {
    const home = homeUnit();
    if (allowed() || orgUnit() !== '0' || !home) { return false; }
    // Several panels call this on one render; move once (a later blank pick moves again).
    if (Date.now() - (window.__rptGoHome || 0) > 3000) {
      window.__rptGoHome = Date.now();
      const ls = grafana.locationService;
      if (ls && ls.partial) { ls.partial({ 'var-org_unit': home }, true); }
      else { const u = new URL(window.location.href); u.searchParams.set('var-org_unit', home); window.location.replace(u.toString()); }
    }
    return true;
  };
  // True while the panel's query is still running.
  const loading = () => !!(context.panelData && context.panelData.state === 'Loading');

  // Mount: returns the root element, or null when access is denied. The banner is drawn once per tab,
  // by the panel mounted with { banner: true } (the title strip); other panels stay empty under it.
  // A user with no location is first moved to their home unit (UX-02); meanwhile the banner panel
  // shows `Opening your area…`. opts.loading: a line to show while the query runs (null is returned).
  const mount = (selector, opts) => {
    const o = opts || {};
    const root = context.element.querySelector(selector);
    if (!root) { return null; }
    if (goHome()) { root.innerHTML = o.banner ? '<div class="rpt-muted">' + esc(OPENING_HOME) + '</div>' : ''; return null; }
    if (!allowed()) { root.innerHTML = o.banner ? banner() : ''; return null; }
    if (o.loading && loading()) { root.innerHTML = '<div class="rpt-muted rpt-loading">' + esc(o.loading) + '</div>'; return null; }
    return root;
  };

  return { v, esc, num, fmt, pct, score, yes, day, month, toDate, rows, orgUnit, reportingMonth, allowed, homeUnit,
    TABS, REPORTS, tab, link, placeLink, nextStep, wireScroll, atFacility, flagsFrom, info, banner, OPENING_HOME, PICK_FACILITY,
    NO_DATA, NO_FACILITIES, NO_FLAGS, noData, needAtLeast, place, thresholds, loading, goHome, mount };
})();
// --- Reports shared facility table (dashboard_src/reports/_shared/table.js) ---
// Declares one name: rptTable. Needs states.js (rpt) included first. DESIGN "Shared facility table".
//
// rptTable(root, {
//   report: 'fudging',                  // this tab's report key (report_flags.report)
//   rows: [...],                        // report_<name> rows; the selection row comes first
//   flags: [...],                       // optional report_flags rows; default: each row's flags_json column
//                                       // (one result set: a panel with two queries gets Business Text's frame picker)
//   columns: [{ label, value: (r) => sortable, cell: (r) => html, num: true, guard: true, title: (r) => text }],
//   flagNames: (r) => ['Pill text'],    // flag pill(s) of a flagged row, at most two shown
//   reason: (r) => r.flag_reason,       // optional; sentence under the pills
//   guardName: 'Too few readings',      // grey pill of a too_few row
//   guardReason: (r) => 'Need at least 20; this place has 12.',
//   check: { text: '◆ Looks fine, check readings', when: (r) => rpt.yes(r.looks_fine_check) },  // optional two-sided pill
//   alsoOn: false,                      // optional; false hides `Also flagged on …`. Default: every other report
//                                       // that flags this facility in report_flags (UX-16). An array is ignored.
//   nameLinks: false,                   // optional; false keeps facility names as plain text. Default: each name
//                                       // links to this tab narrowed to that facility (UX-15).
//   size: (r) => r.readings_n,          // patients or cases in scope, the last sort key
//   order: 'size',                      // optional; within flagged / too few / clean, sort by size (high first)
//                                       // instead of number of report_flags entries, then patients
//   caption: 'Facilities in view, flagged first',
// })
// 10 rows per page with the overdue list's pager (shown whenever there are rows, as on the overdue list).
// Facility is the first column and `Why look here` the last; columns sit between them.
// A row whose level is under 3 and is_selected is drawn as the bold `All places in view` row and stays on top.
const rptTable = (root, cfg) => {
  const { esc, fmt, num, yes } = rpt;
  const PAGE = 10;
  const all = (cfg.rows || []).filter((r) => r && r.org_unit_id != null);
  const isTotal = (r) => yes(r.is_selected) && (num(r.level) || 0) < 3;
  const total = all.find(isTotal) || null;
  const rows = all.filter((r) => r !== total);
  if (!all.length) { root.innerHTML = rpt.noData(rpt.NO_FACILITIES); return; }

  // report_flags per facility: { id: [{report, flag_reason, patients_n}] }
  const flagsOf = {};
  (cfg.flags || rpt.flagsFrom(all)).forEach((f) => { (flagsOf[f.org_unit_id] = flagsOf[f.org_unit_id] || []).push(f); });
  const nFlags = (r) => (flagsOf[r.org_unit_id] || []).length;
  const patients = (r) => { const f = (flagsOf[r.org_unit_id] || [])[0]; return f && num(f.patients_n) !== null ? num(f.patients_n) : (cfg.size ? num(cfg.size(r)) || 0 : 0); };
  // 0 flagged, 1 too few, 2 clean.
  const rank = (r) => (yes(r.flag) ? 0 : yes(r.too_few) ? 1 : 2);
  const sizeOf = (r) => (cfg.size ? num(cfg.size(r)) || 0 : 0);
  const needsALook = (a, b) => rank(a) - rank(b)
    || (cfg.order === 'size' ? sizeOf(b) - sizeOf(a) : nFlags(b) - nFlags(a) || patients(b) - patients(a))
    || String(a.org_unit_name).localeCompare(String(b.org_unit_name));

  const FACILITY = { label: 'Facility', value: (r) => String(r.org_unit_name || '') };
  const WHY = { label: 'Why look here', value: (r) => rank(r) };
  const cols = [FACILITY].concat(cfg.columns || [], [WHY]);
  const state = { sort: -1, dir: 1, page: 0 };   // sort -1 = needs a look first

  const pill = (cls, text) => '<span class="rpt-pill ' + cls + '">' + esc(text) + '</span>';
  // `Also flagged on`: every other report tab that flags this facility in report_flags, in tab order.
  // Each link opens that tab for this facility.
  const also = (r) => {
    if (cfg.alsoOn === false) { return ''; }
    const mine = flagsOf[r.org_unit_id] || [];
    const links = rpt.REPORTS.filter((t) => t.report !== cfg.report && mine.some((f) => f.report === t.report))
      .map((t) => '<a class="rpt-link" href="' + esc(rpt.link(t.report, r.org_unit_id)) + '">' + esc(t.title) + '</a>');
    return links.length ? '<div class="rpt-also">Also flagged on ' + links.join(', ') + '</div>' : '';
  };
  const name = (r) => (cfg.nameLinks === false ? esc(r.org_unit_name) : rpt.placeLink(cfg.report, r.org_unit_id, r.org_unit_name));
  const why = (r, totalRow) => {
    if (yes(r.flag)) {
      const names = [].concat(cfg.flagNames ? cfg.flagNames(r) : []).filter(Boolean).slice(0, 2);
      const check = !totalRow && cfg.check && cfg.check.when(r) ? pill('rpt-pill-check', cfg.check.text) : '';
      const reason = cfg.reason ? cfg.reason(r) : r.flag_reason;
      return '<div class="rpt-pills">' + check + names.map((n) => pill('rpt-pill-flag', n)).join('') + '</div>'
        + (reason ? '<div class="rpt-reason">' + esc(reason) + '</div>' : '') + (totalRow ? '' : also(r));
    }
    if (yes(r.too_few)) {
      return '<div class="rpt-pills">' + pill('rpt-pill-guard', cfg.guardName || 'Too few') + '</div>'
        + (cfg.guardReason ? '<div class="rpt-reason">' + esc(cfg.guardReason(r)) + '</div>' : '');
    }
    return '<span class="rpt-clean">No flag</span>';
  };
  const cell = (c, r) => (c.guard && yes(r.too_few) ? '—' : c.cell ? c.cell(r) : esc(c.value(r)));
  const tr = (r, totalRow) => '<tr class="' + (totalRow ? 'rpt-total' : rank(r) === 0 ? 'rpt-flagged' : '') + '">'
    + '<th scope="row">' + (totalRow ? 'All places in view' : name(r)) + '</th>'
    + (cfg.columns || []).map((c) => '<td class="' + (c.num ? 'num' : '') + '"' + (c.title && c.title(r) ? ' title="' + esc(c.title(r)) + '"' : '') + '>' + cell(c, r) + '</td>').join('')
    + '<td class="rpt-why">' + why(r, totalRow) + '</td></tr>';

  const sorted = () => {
    if (state.sort < 0) { return rows.slice().sort(needsALook); }
    const c = cols[state.sort];
    const key = (r) => (c.guard && yes(r.too_few) ? null : c.value(r));
    return rows.slice().sort((a, b) => {
      const x = key(a), y = key(b);
      if (x === null || x === undefined) { return y === null || y === undefined ? needsALook(a, b) : 1; }   // blanks last
      if (y === null || y === undefined) { return -1; }
      const d = typeof x === 'number' && typeof y === 'number' ? x - y : String(x).localeCompare(String(y), 'en', { numeric: true });
      return state.dir * d || needsALook(a, b);
    });
  };

  const render = () => {
    const list = sorted();
    const pages = Math.max(1, Math.ceil(list.length / PAGE));
    state.page = Math.min(Math.max(state.page, 0), pages - 1);
    const shown = list.slice(state.page * PAGE, (state.page + 1) * PAGE);
    const head = cols.map((c, i) => {
      const on = state.sort === i;
      const aria = on ? (state.dir > 0 ? 'ascending' : 'descending') : 'none';
      return '<th scope="col" aria-sort="' + aria + '" class="' + (c.num ? 'num' : '') + '">'
        + '<button type="button" class="rpt-sortbtn" data-col="' + i + '">' + esc(c.label)
        + '<span class="rpt-sort" aria-hidden="true">' + (on ? (state.dir > 0 ? ' ↑' : ' ↓') : '') + '</span></button></th>';
    }).join('');
    const byNeed = state.sort < 0;
    root.innerHTML = '<div class="rpt-chips">'
      + '<button type="button" class="rpt-chip' + (byNeed ? ' on' : '') + '" data-reset="1" aria-pressed="' + byNeed + '">Sort: needs a look first</button></div>'
      + '<div class="rpt-wrap"><table class="rpt-table">'
      + '<caption class="rpt-sr">' + esc(cfg.caption || 'Facilities in view. Flagged facilities come first.') + '</caption>'
      + '<thead><tr>' + head + '</tr></thead><tbody>'
      + (total && rows.length ? tr(total, true) : '')
      + (shown.length ? shown.map((r) => tr(r, false)).join('') : total ? tr(total, false) : '')
      + '</tbody></table></div>'
      + (list.length ? '<div class="rpt-pager">'
        + '<button type="button" data-page="-1"' + (state.page ? '' : ' disabled') + ' aria-label="Previous page">‹</button>'
        + '<span>' + fmt(state.page * PAGE + 1) + '–' + fmt(state.page * PAGE + shown.length) + ' of ' + fmt(list.length) + '</span>'
        + '<button type="button" data-page="1"' + (state.page < pages - 1 ? '' : ' disabled') + ' aria-label="Next page">›</button></div>' : '');
  };
  render();

  root.addEventListener('click', (e) => {
    const b = e.target.closest('button');
    if (!b || !root.contains(b)) { return; }
    let focus = null;
    if (b.dataset.reset) { state.sort = -1; state.dir = 1; state.page = 0; focus = '[data-reset]'; }
    else if (b.dataset.page) { state.page += Number(b.dataset.page); focus = '[data-page="' + b.dataset.page + '"]'; }
    else if (b.dataset.col) {
      const i = Number(b.dataset.col);
      // First click: names A to Z, numbers high to low; a second click flips it.
      state.dir = state.sort === i ? -state.dir : (cols[i].num ? -1 : 1);
      state.sort = i; state.page = 0; focus = '[data-col="' + i + '"]';
    } else { return; }
    render();
    const f = focus && root.querySelector(focus);
    if (f && !f.disabled) { f.focus(); }
  });
};
// Facility table: Facility, BP controlled, High-BP visits, Stepped up, Share stepped up, Why look here.
const root = rpt.mount('.rpt-tit-table');
if (!root) { return; }
const { fmt, num, yes } = rpt;
// Stock first (UX-09): low stepping up may come from missing medicine.
const reasonOf = (r) => 'Only ' + fmt(r.stepped_up_n) + ' of ' + fmt(r.uncontrolled_visits_n)
  + ' high-BP visits led to a stronger prescription (' + rpt.pct(r.titration_pct) + '). Check medicine stock first.';
rptTable(root, {
  report: 'titration',
  rows: rpt.rows('A'),
  caption: 'High-BP visits followed by a stronger prescription, by facility. Flagged facilities come first.',
  columns: [
    { label: 'BP controlled', num: true, value: (r) => num(r.control_pct), cell: (r) => (num(r.control_pct) === null ? '—' : '<span class="rpt-ctl">' + rpt.pct(r.control_pct) + '</span>') },
    { label: 'High-BP visits', num: true, value: (r) => num(r.uncontrolled_visits_n), cell: (r) => fmt(r.uncontrolled_visits_n) },
    { label: 'Stepped up', num: true, value: (r) => num(r.stepped_up_n), cell: (r) => fmt(r.stepped_up_n) },
    { label: 'Share stepped up', num: true, guard: true, value: (r) => num(r.titration_pct), cell: (r) => rpt.pct(r.titration_pct),
      title: (r) => fmt(r.stepped_up_n) + ' of ' + fmt(r.uncontrolled_visits_n) + ' high-BP visits' }
  ],
  flagNames: () => ['Medicine rarely stepped up'],
  reason: reasonOf,
  guardName: 'Too few visits',
  guardReason: (r) => rpt.needAtLeast(r.min_visits, r.uncontrolled_visits_n),
  check: { text: '◆ Control looks fine, check stock', when: (r) => yes(r.looks_fine_check) },
  size: (r) => num(r.uncontrolled_visits_n),
  order: 'size'
});

options.styles:
/* --- Reports shared styles (dashboard_src/reports/_shared/styles.css) ---
   Business Text styles. Every class starts rpt-; put class "rpt" on the panel's root div.
   Tokens: ux-hearts360-mvp-2026-11-04/DESIGN.md front matter. Table, chips, pager and banner copy
   the program dashboard's overdue list (.ovq-*). Light theme only (A40). */
.rpt {
  --text-primary: #111217; --text-muted: #6E6E6E; --border-subtle: #D8D9DA; --accent: #3D71D9;
  --controlled: #3BB231; --uncontrolled: #EEAB00; --no-visit: #ED6300;
  --flag-bar: #ED6300; --flag-row-bg: #FDF0E6; --flag-pill-bg: #FDE3CF; --flag-pill-text: #8A3A00;
  --guard-pill-text: #4E545A; --cell-missing-bg: #EFEFEF;
  font-size: 13px; line-height: 1.35; color: var(--text-primary);
}
.rpt a.rpt-link { color: #0075eb; text-decoration: none; }
.rpt a.rpt-link:hover, .rpt a.rpt-link:focus-visible { text-decoration: underline; }
.rpt-sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.rpt-muted { color: var(--text-muted); }
.rpt-empty { color: var(--text-muted); font-size: 14px; text-align: center; padding: 18px 8px; }

/* Title strip: question (card-title), then "{place} · {period}" (microcopy, muted). */
.rpt-title { font-size: 16px; font-weight: 500; margin: 0 0 2px; line-height: 1.3; }
.rpt-sub { font-size: 12px; color: var(--text-muted); line-height: 1.4; }

/* Headline strip: three equal columns, thin dividers (as panel-outcomes). */
.rpt-strip3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); height: 100%; }
.rpt-strip3 > div { padding: 2px 16px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip3 > div:first-child { border-left: 0; padding-left: 4px; }
.rpt-big { font-size: 32px; font-weight: 600; line-height: 1.1; font-variant-numeric: tabular-nums; }
.rpt-big.rpt-few { font-size: 20px; font-weight: 500; color: var(--text-muted); line-height: 1.6; }
.rpt-label { font-size: 14px; font-weight: 500; margin-top: 2px; }
.rpt-line { font-size: 12px; color: var(--text-muted); line-height: 1.4; margin-top: 2px; }

/* Look at these first: at most three items. */
.rpt-card-title { font-size: 16px; font-weight: 500; margin: 0 0 8px; }
.rpt-look { list-style: none; margin: 0; padding: 0; }
.rpt-look li { padding: 8px 0 8px 10px; border-left: 4px solid var(--flag-bar); background: var(--flag-row-bg); margin-bottom: 8px; border-radius: 0 4px 4px 0; }
.rpt-look-name { font-weight: 600; }
.rpt-look-line { font-size: 12px; line-height: 1.4; margin-top: 2px; }

/* Facility table: overdue list style. No vertical lines or stripes, light header, hover highlight. */
.rpt-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.rpt-chip { font: inherit; font-size: 12px; border: 1px solid #d9e3ff; background: transparent; color: inherit; border-radius: 14px; padding: 2px 10px; cursor: pointer; text-decoration: none; display: inline-block; white-space: nowrap; }
.rpt-chip.on { background: #0075eb; border-color: #0075eb; color: #fff; cursor: default; }
a.rpt-chip:hover, button.rpt-chip:not(.on):hover { background: #EEF3FD; }
.rpt-wrap { overflow-x: auto; }
.rpt-table { width: 100%; border-collapse: collapse; border: 0; }
.rpt-table th, .rpt-table td { border: 0 !important; border-bottom: 1px solid rgba(128,128,128,0.2) !important; padding: 8px 8px; text-align: left; vertical-align: top; }
.rpt-table thead th { background: rgba(0,117,235,0.06); color: #6e7f8d; font-size: 12px; font-weight: 600; white-space: nowrap; vertical-align: bottom; }
.rpt-table tbody th { font-weight: 400; white-space: nowrap; background: transparent; color: inherit; }
.rpt-table tbody tr:hover { background: rgba(0,117,235,0.04); }
.rpt-table .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.rpt-table thead th.num .rpt-sortbtn { text-align: right; }
.rpt-table td.rpt-why { width: 42%; min-width: 260px; }
.rpt-sortbtn { font: inherit; font-weight: 600; background: none; border: 0; padding: 0; color: inherit; cursor: pointer; }
.rpt-sortbtn:focus-visible, .rpt-chip:focus-visible, .rpt-pager button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* Flagged row: 4px orange bar and light tint. */
.rpt-table tr.rpt-flagged, .rpt-table tr.rpt-flagged:hover { background: var(--flag-row-bg); }
.rpt-table tr.rpt-flagged > th:first-child { box-shadow: inset 4px 0 0 var(--flag-bar); padding-left: 12px; }
/* All places in view: bold first row. */
.rpt-table tr.rpt-total > th, .rpt-table tr.rpt-total > td { font-weight: 700; }
.rpt-table tr.rpt-total .rpt-reason, .rpt-table tr.rpt-total .rpt-pill { font-weight: 400; }
.rpt-ctl { color: var(--controlled); font-weight: 600; }
/* Pills: text, never colour only. */
.rpt-pills { display: flex; flex-wrap: wrap; gap: 4px; }
.rpt-pill { display: inline-block; padding: 1px 8px; border-radius: 9999px; font-size: 12px; font-weight: 600; white-space: nowrap; line-height: 1.5; }
.rpt-pill-flag { background: var(--flag-pill-bg); color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-check { background: #FFFFFF; color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-guard { background: var(--cell-missing-bg); color: var(--guard-pill-text); border: 1px solid var(--cell-missing-bg); }
.rpt-reason { font-size: 12px; line-height: 1.4; margin-top: 3px; color: var(--text-primary); }
.rpt-also { font-size: 12px; margin-top: 3px; }
.rpt-also a { color: #0075eb; text-decoration: none; }
.rpt-also a:hover, .rpt-also a:focus-visible { text-decoration: underline; }
.rpt-clean { color: var(--text-muted); }
/* Pager: overdue list. */
.rpt-pager { display: flex; justify-content: center; align-items: center; gap: 12px; padding: 10px 0 2px; }
.rpt-pager button { font: inherit; width: 28px; height: 26px; border-radius: 4px; border: 1px solid #d9e3ff; background: transparent; color: inherit; cursor: pointer; }
.rpt-pager button:disabled { opacity: 0.35; cursor: default; }
/* Access banner: the overdue list's .ovq-warn. */
.rpt-warn { color: #e02424; background: rgba(224,36,36,0.05); border-left: 4px solid #e02424; padding: 8px 14px; font-size: 13px; display: flex; align-items: center; gap: 8px; border-radius: 2px; line-height: 1.4; }

/* How this is worked out. */
.rpt-note { font-size: 12px; color: var(--text-muted); line-height: 1.45; }

.rpt-demo { font-size: 12px; color: var(--text-muted); margin-top: 8px; }

/* Grey note (no warning tone, UX-21): no access, pick a facility, and other next-step lines. */
.rpt-info { color: var(--text-primary); background: #F4F5F5; border-left: 4px solid var(--border-subtle); padding: 8px 14px; font-size: 13px; line-height: 1.45; border-radius: 2px; }
.rpt-details { margin-top: 4px; font-size: 12px; color: var(--text-muted); }
.rpt-details summary { cursor: pointer; }
.rpt-loading { padding: 8px 0; }

/* Next step: one link at the end of a tab. */
.rpt-next { display: flex; align-items: baseline; gap: 10px; font-size: 14px; padding: 4px 0; }
.rpt-next-label { font-size: 12px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.03em; }
.rpt-next a.rpt-link { font-weight: 500; }

/* Start here grid: facilities down the side, reports across; each cell is a link. */
.rpt-start-do { margin: 6px 0 10px; font-size: 14px; }
.rpt-grid { table-layout: fixed; }
.rpt-grid thead th:first-child, .rpt-grid tbody th { width: 16%; }
.rpt-grid tbody th { font-weight: 600; vertical-align: middle; }
.rpt-table.rpt-grid td.rpt-cell { padding: 3px; vertical-align: middle; }
.rpt-cell a { display: block; padding: 5px 8px; border-radius: 4px; text-decoration: none; color: inherit; border: 1px solid transparent; line-height: 1.3; }
.rpt-cell a:hover, .rpt-cell a:focus-visible { border-color: var(--accent); outline: none; }
.rpt-cell-word { display: block; font-weight: 600; font-size: 13px; }
.rpt-cell-n { display: block; font-size: 12px; color: var(--text-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rpt-cell-flag a { background: var(--flag-pill-bg); border-color: var(--flag-bar); }
.rpt-cell-flag .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-flag .rpt-cell-n { color: var(--flag-pill-text); }
.rpt-cell-check a { background: #FFFFFF; border-color: var(--flag-bar); border-style: dashed; }
.rpt-cell-check .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-few a { background: var(--cell-missing-bg); }
.rpt-cell-few .rpt-cell-word { color: var(--guard-pill-text); }
.rpt-cell-fine .rpt-cell-word { font-weight: 400; color: var(--text-muted); }
.rpt-cell-none { color: var(--text-muted); text-align: center; }
.rpt-start-key { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 12px; color: var(--text-muted); margin-top: 8px; }
.rpt-start-key b { color: var(--text-primary); font-weight: 600; }

/* Headline strip with four numbers (Overdue calls). */
.rpt-strip4 { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); height: 100%; }
.rpt-strip4 > div { padding: 2px 14px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip4 > div:first-child { border-left: 0; padding-left: 4px; }

/* Monthly table, place against the average (monthly.js; Metabase titration and statins form). */
.rpt-mt th, .rpt-mt td { padding: 5px 8px; }
.rpt-mt thead tr.rpt-mt-group th { text-align: center; color: var(--text-primary); font-size: 12px; border-bottom: 0 !important; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-place { box-shadow: inset 0 -3px 0 #3D71D9; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-avg { box-shadow: inset 0 -3px 0 #9B7FD4; }
.rpt-mt .rpt-mt-gap { border-left: 1px solid var(--border-subtle) !important; }
.rpt-mt tbody tr.rpt-mt-last > * { font-weight: 700; }
.rpt-mt-few { color: var(--text-muted); font-weight: 400; }

options.afterRender:
// --- Reports shared helpers and states (dashboard_src/reports/_shared/states.js) ---
// Declares one name: rpt. Business Text afterRender only (it reads context.grafana).
const rpt = (() => {
  const grafana = (typeof context !== 'undefined' && context.grafana) || {};
  // A variable's value; '' when the dashboard has no such variable (replaceVariables leaves `${name}`).
  const v = (name) => { const x = grafana.replaceVariables ? String(grafana.replaceVariables('${' + name + '}')) : ''; return x === '${' + name + '}' ? '' : x; };

  const esc = (x) => String(x == null ? '' : x).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const num = (x) => (x === null || x === undefined || x === '' || isNaN(Number(x)) ? null : Number(x));
  // Thousands commas.
  const fmt = (x) => (num(x) === null ? '—' : Math.round(num(x)).toLocaleString('en-US'));
  // Percent: whole, one decimal under 10% (DESIGN Typography).
  const pct = (x) => { const n = num(x); if (n === null) { return '—'; } return (Math.abs(n) < 10 ? n.toFixed(1) : String(Math.round(n))) + '%'; };
  // Scores: two decimals.
  const score = (x) => (num(x) === null ? '—' : num(x).toFixed(2));
  const yes = (x) => x === true || x === 1 || x === 't' || x === 'true';

  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  // Postgres dates arrive as ms numbers or 'YYYY-MM-DD' strings; read them as UTC days.
  const toDate = (x) => { if (x == null || x === '') { return null; } const d = typeof x === 'number' ? new Date(x) : new Date(String(x).slice(0, 10) + 'T00:00:00Z'); return isNaN(d) ? null : d; };
  const day = (x) => { const d = toDate(x); return d ? d.getUTCDate() + '-' + MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };
  const month = (x) => { const d = toDate(x); return d ? MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };

  // Rows of the frame with refId ref, as objects.
  const rows = (ref) => {
    const series = (context.panelData && context.panelData.series) || [];
    const f = series.find((s) => s.refId === ref);
    if (!f) { return []; }
    const cols = f.fields.map((x) => [x.name, Array.from(x.values)]);
    const n = cols.length ? cols[0][1].length : 0;
    return Array.from({ length: n }, (_, i) => Object.fromEntries(cols.map(([k, vals]) => [k, vals[i]])));
  };

  // report_flags rows from a flags_json column (json_agg of {report, flag_reason, patients_n}) on each row.
  const flagsFrom = (list) => [].concat(...(list || []).map((r) => {
    let parsed = [];
    try { parsed = r.flags_json ? JSON.parse(r.flags_json) : []; } catch (e) { parsed = []; }
    return (Array.isArray(parsed) ? parsed : []).map((f) => Object.assign({ org_unit_id: r.org_unit_id, org_unit_name: r.org_unit_name }, f));
  }));

  // Variables, read in the browser so no access query is needed.
  const orgUnit = () => { const o = v('org_unit').trim(); return o && o !== '0' ? o : '0'; };
  const reportingMonth = () => v('reporting_month');
  const allowed = () => v('isAllowed') === '1';

  // The user's home unit (hidden variable home_org_unit, the home dashboard's UserOrgUnitId query).
  // '' for admins and users with access everywhere.
  const homeUnit = () => { const h = v('home_org_unit').trim(); return h && h !== '0' ? h : ''; };

  // Tabs from the builder's TABS list: [{report, title, slug}], in tab order. TABS[0] is `Start here`.
  const TABS = [{"report":"start","title":"Start here","slug":"Start-here"},{"report":"titration","title":"Stepping up","slug":"Stepping-up"},{"report":"adherence","title":"Right medicines","slug":"Right-medicines"},{"report":"fudging","title":"BP readings check","slug":"BP-readings-check"},{"report":"calling","title":"Overdue calls","slug":"Overdue-calls"},{"report":"statins","title":"Statins","slug":"Statins"}];
  // The five report tabs (every tab but `Start here`), in tab order.
  const REPORTS = TABS.filter((t) => t.report !== 'start');
  const tab = (report) => TABS.find((t) => t.report === report) || null;
  // AD-29 deep link; keeps the location and month unless given. extra: more URL parameters,
  // for example { 'var-include_new': 'true' }.
  const link = (report, org, mon, extra) => {
    const t = tab(report);
    if (!t) { return ''; }
    const more = Object.keys(extra || {}).map((k) => '&' + encodeURIComponent(k) + '=' + encodeURIComponent(extra[k])).join('');
    return '/d/heart360_reports?var-org_unit=' + encodeURIComponent(org == null ? orgUnit() : org)
      + '&var-reporting_month=' + encodeURIComponent(mon == null ? reportingMonth() : mon) + more + '&-dtab=' + encodeURIComponent(t.slug);
  };
  // A facility name that narrows this tab to that facility (UX-15). Plain text when it is already the place in view.
  const placeLink = (report, id, name) => (id == null || String(id) === orgUnit() || !tab(report)
    ? esc(name) : '<a class="rpt-link" href="' + esc(link(report, id)) + '" title="' + esc('Show ' + name + ' only') + '">' + esc(name) + '</a>');
  // `Next step` line at the end of a tab: one link, sentence case.
  const nextStep = (text, href) => '<div class="rpt-next"><span class="rpt-next-label">Next step</span>'
    + '<a class="rpt-link" href="' + esc(href) + '">' + esc(text) + ' →</a></div>';
  // Same-page links: an <a href="#some-id"> inside el scrolls the element with that id into view
  // (Grafana scrolls its own pane, so a plain hash link does not move it). Use with nextStep('...', '#id').
  // Grafana draws panels lazily: while the target is not drawn yet, the pane scrolls down a screen at a
  // time until it appears.
  const wireScroll = (el) => {
    if (!el || el.__rptScroll) { return; }
    el.__rptScroll = true;
    const pane = (node) => { let p = node.parentElement; while (p && !(p.scrollHeight > p.clientHeight && /auto|scroll/.test(getComputedStyle(p).overflowY))) { p = p.parentElement; } return p; };
    el.addEventListener('click', (e) => {
      const a = e.target.closest && e.target.closest('a[href^="#"]');
      if (!a || !el.contains(a)) { return; }
      e.preventDefault();
      const id = a.getAttribute('href').slice(1);
      const box = pane(el);
      let tries = 0;
      const go = () => {
        const t = document.getElementById(id);
        if (t) { t.scrollIntoView({ behavior: 'smooth', block: 'start' }); return; }
        if (!box || tries++ > 8) { return; }
        box.scrollTop += Math.round(box.clientHeight * 0.8);
        setTimeout(go, 350);
      };
      go();
    });
  };
  // At or below the facility level (selected_level 3 or more): patient lists and the overdue list work here.
  const atFacility = () => (num(v('selected_level')) || 0) >= 3;

  // --- States (DESIGN States, FR-32) ---
  // Grey note, no warning tone (Voice rule 8, UX-21). html is trusted markup; use esc() on data.
  const info = (html) => '<div class="rpt-info">' + html + '</div>';
  // No access: plain words and the next step. The access team names sit in a closed `Details` for the admin.
  const banner = () => {
    const teams = v('requiredGroups').replace(/<[^>]*>/g, '').trim();
    return info('<span>You cannot see this place. Pick your own area in <strong>Change location</strong> above.</span>'
      + (teams ? '<details class="rpt-details"><summary>Details for your admin</summary>Access comes from: ' + esc(teams) + '</details>' : ''));
  };
  // Shown while the page moves a user with no location to their home unit (UX-02).
  const OPENING_HOME = 'Opening your area…';
  // For views that need one facility (patient lists): a grey line with the next step.
  const PICK_FACILITY = 'Pick a facility in Change location above to see its patients.';
  const NO_DATA = 'No data for this place.';
  const NO_FACILITIES = 'No facilities for this location.';
  const NO_FLAGS = 'No facility is flagged.';
  const noData = (text) => '<div class="rpt-empty">' + esc(text || NO_DATA) + '</div>';
  // "Need at least 20; this place has 12."
  const needAtLeast = (k, n) => 'Need at least ' + fmt(k) + '; this place has ' + fmt(n) + '.';
  // Place for the subtitle: the selected name, or all locations.
  const place = (name) => (orgUnit() === '0' ? 'All locations you can access' : (name || 'This place'));

  // Thresholds from report_flag_thresholds rows ({report, key, value}).
  const thresholds = (list) => { const t = {}; (list || []).forEach((r) => { t[r.report + '.' + r.key] = num(r.value); }); return t; };

  // UX-02: a user with no location who may not see all places is moved to their home unit, keeping
  // the month and tab. Returns true when it does so.
  const goHome = () => {
    const home = homeUnit();
    if (allowed() || orgUnit() !== '0' || !home) { return false; }
    // Several panels call this on one render; move once (a later blank pick moves again).
    if (Date.now() - (window.__rptGoHome || 0) > 3000) {
      window.__rptGoHome = Date.now();
      const ls = grafana.locationService;
      if (ls && ls.partial) { ls.partial({ 'var-org_unit': home }, true); }
      else { const u = new URL(window.location.href); u.searchParams.set('var-org_unit', home); window.location.replace(u.toString()); }
    }
    return true;
  };
  // True while the panel's query is still running.
  const loading = () => !!(context.panelData && context.panelData.state === 'Loading');

  // Mount: returns the root element, or null when access is denied. The banner is drawn once per tab,
  // by the panel mounted with { banner: true } (the title strip); other panels stay empty under it.
  // A user with no location is first moved to their home unit (UX-02); meanwhile the banner panel
  // shows `Opening your area…`. opts.loading: a line to show while the query runs (null is returned).
  const mount = (selector, opts) => {
    const o = opts || {};
    const root = context.element.querySelector(selector);
    if (!root) { return null; }
    if (goHome()) { root.innerHTML = o.banner ? '<div class="rpt-muted">' + esc(OPENING_HOME) + '</div>' : ''; return null; }
    if (!allowed()) { root.innerHTML = o.banner ? banner() : ''; return null; }
    if (o.loading && loading()) { root.innerHTML = '<div class="rpt-muted rpt-loading">' + esc(o.loading) + '</div>'; return null; }
    return root;
  };

  return { v, esc, num, fmt, pct, score, yes, day, month, toDate, rows, orgUnit, reportingMonth, allowed, homeUnit,
    TABS, REPORTS, tab, link, placeLink, nextStep, wireScroll, atFacility, flagsFrom, info, banner, OPENING_HOME, PICK_FACILITY,
    NO_DATA, NO_FACILITIES, NO_FLAGS, noData, needAtLeast, place, thresholds, loading, goHome, mount };
})();
const stockHref = '/d/heart360_drug_stock?' + (rpt.orgUnit() !== '0' ? 'var-org_unit=' + encodeURIComponent(rpt.orgUnit()) + '&' : '')
  + 'var-reporting_month=' + encodeURIComponent(rpt.reportingMonth());
// How this is worked out (with the visits left out, UX-31), then the Next step.
const root = rpt.mount('.rpt-tit-note');
if (!root) { return; }
const r = rpt.rows('A')[0] || {};
const a = rpt.num(r.excluded_too_recent_n), b = rpt.num(r.excluded_no_baseline_n);
const left = (a ? ' ' + rpt.fmt(a) + ' visits were too recent to check.' : '') + (b ? ' ' + rpt.fmt(b) + ' visits had no earlier prescription.' : '');
root.innerHTML = '<div class="rpt-note"><strong>How this is worked out.</strong> Looks at visits with BP 140/90 or above in the 90 days to each month end. '
  + 'A visit counts as stepped up if it, or the next within 30 days, has a stronger prescription. '
  + 'Stronger means more medicines or a higher dose than before. Average is all places together.' + rpt.esc(left)
  + ' Low stepping up may come from missing medicine, so check stock first.</div>'
  + rpt.nextStep('Check medicine stock first', stockHref);

options.styles:
/* --- Reports shared styles (dashboard_src/reports/_shared/styles.css) ---
   Business Text styles. Every class starts rpt-; put class "rpt" on the panel's root div.
   Tokens: ux-hearts360-mvp-2026-11-04/DESIGN.md front matter. Table, chips, pager and banner copy
   the program dashboard's overdue list (.ovq-*). Light theme only (A40). */
.rpt {
  --text-primary: #111217; --text-muted: #6E6E6E; --border-subtle: #D8D9DA; --accent: #3D71D9;
  --controlled: #3BB231; --uncontrolled: #EEAB00; --no-visit: #ED6300;
  --flag-bar: #ED6300; --flag-row-bg: #FDF0E6; --flag-pill-bg: #FDE3CF; --flag-pill-text: #8A3A00;
  --guard-pill-text: #4E545A; --cell-missing-bg: #EFEFEF;
  font-size: 13px; line-height: 1.35; color: var(--text-primary);
}
.rpt a.rpt-link { color: #0075eb; text-decoration: none; }
.rpt a.rpt-link:hover, .rpt a.rpt-link:focus-visible { text-decoration: underline; }
.rpt-sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.rpt-muted { color: var(--text-muted); }
.rpt-empty { color: var(--text-muted); font-size: 14px; text-align: center; padding: 18px 8px; }

/* Title strip: question (card-title), then "{place} · {period}" (microcopy, muted). */
.rpt-title { font-size: 16px; font-weight: 500; margin: 0 0 2px; line-height: 1.3; }
.rpt-sub { font-size: 12px; color: var(--text-muted); line-height: 1.4; }

/* Headline strip: three equal columns, thin dividers (as panel-outcomes). */
.rpt-strip3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); height: 100%; }
.rpt-strip3 > div { padding: 2px 16px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip3 > div:first-child { border-left: 0; padding-left: 4px; }
.rpt-big { font-size: 32px; font-weight: 600; line-height: 1.1; font-variant-numeric: tabular-nums; }
.rpt-big.rpt-few { font-size: 20px; font-weight: 500; color: var(--text-muted); line-height: 1.6; }
.rpt-label { font-size: 14px; font-weight: 500; margin-top: 2px; }
.rpt-line { font-size: 12px; color: var(--text-muted); line-height: 1.4; margin-top: 2px; }

/* Look at these first: at most three items. */
.rpt-card-title { font-size: 16px; font-weight: 500; margin: 0 0 8px; }
.rpt-look { list-style: none; margin: 0; padding: 0; }
.rpt-look li { padding: 8px 0 8px 10px; border-left: 4px solid var(--flag-bar); background: var(--flag-row-bg); margin-bottom: 8px; border-radius: 0 4px 4px 0; }
.rpt-look-name { font-weight: 600; }
.rpt-look-line { font-size: 12px; line-height: 1.4; margin-top: 2px; }

/* Facility table: overdue list style. No vertical lines or stripes, light header, hover highlight. */
.rpt-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.rpt-chip { font: inherit; font-size: 12px; border: 1px solid #d9e3ff; background: transparent; color: inherit; border-radius: 14px; padding: 2px 10px; cursor: pointer; text-decoration: none; display: inline-block; white-space: nowrap; }
.rpt-chip.on { background: #0075eb; border-color: #0075eb; color: #fff; cursor: default; }
a.rpt-chip:hover, button.rpt-chip:not(.on):hover { background: #EEF3FD; }
.rpt-wrap { overflow-x: auto; }
.rpt-table { width: 100%; border-collapse: collapse; border: 0; }
.rpt-table th, .rpt-table td { border: 0 !important; border-bottom: 1px solid rgba(128,128,128,0.2) !important; padding: 8px 8px; text-align: left; vertical-align: top; }
.rpt-table thead th { background: rgba(0,117,235,0.06); color: #6e7f8d; font-size: 12px; font-weight: 600; white-space: nowrap; vertical-align: bottom; }
.rpt-table tbody th { font-weight: 400; white-space: nowrap; background: transparent; color: inherit; }
.rpt-table tbody tr:hover { background: rgba(0,117,235,0.04); }
.rpt-table .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.rpt-table thead th.num .rpt-sortbtn { text-align: right; }
.rpt-table td.rpt-why { width: 42%; min-width: 260px; }
.rpt-sortbtn { font: inherit; font-weight: 600; background: none; border: 0; padding: 0; color: inherit; cursor: pointer; }
.rpt-sortbtn:focus-visible, .rpt-chip:focus-visible, .rpt-pager button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* Flagged row: 4px orange bar and light tint. */
.rpt-table tr.rpt-flagged, .rpt-table tr.rpt-flagged:hover { background: var(--flag-row-bg); }
.rpt-table tr.rpt-flagged > th:first-child { box-shadow: inset 4px 0 0 var(--flag-bar); padding-left: 12px; }
/* All places in view: bold first row. */
.rpt-table tr.rpt-total > th, .rpt-table tr.rpt-total > td { font-weight: 700; }
.rpt-table tr.rpt-total .rpt-reason, .rpt-table tr.rpt-total .rpt-pill { font-weight: 400; }
.rpt-ctl { color: var(--controlled); font-weight: 600; }
/* Pills: text, never colour only. */
.rpt-pills { display: flex; flex-wrap: wrap; gap: 4px; }
.rpt-pill { display: inline-block; padding: 1px 8px; border-radius: 9999px; font-size: 12px; font-weight: 600; white-space: nowrap; line-height: 1.5; }
.rpt-pill-flag { background: var(--flag-pill-bg); color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-check { background: #FFFFFF; color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-guard { background: var(--cell-missing-bg); color: var(--guard-pill-text); border: 1px solid var(--cell-missing-bg); }
.rpt-reason { font-size: 12px; line-height: 1.4; margin-top: 3px; color: var(--text-primary); }
.rpt-also { font-size: 12px; margin-top: 3px; }
.rpt-also a { color: #0075eb; text-decoration: none; }
.rpt-also a:hover, .rpt-also a:focus-visible { text-decoration: underline; }
.rpt-clean { color: var(--text-muted); }
/* Pager: overdue list. */
.rpt-pager { display: flex; justify-content: center; align-items: center; gap: 12px; padding: 10px 0 2px; }
.rpt-pager button { font: inherit; width: 28px; height: 26px; border-radius: 4px; border: 1px solid #d9e3ff; background: transparent; color: inherit; cursor: pointer; }
.rpt-pager button:disabled { opacity: 0.35; cursor: default; }
/* Access banner: the overdue list's .ovq-warn. */
.rpt-warn { color: #e02424; background: rgba(224,36,36,0.05); border-left: 4px solid #e02424; padding: 8px 14px; font-size: 13px; display: flex; align-items: center; gap: 8px; border-radius: 2px; line-height: 1.4; }

/* How this is worked out. */
.rpt-note { font-size: 12px; color: var(--text-muted); line-height: 1.45; }

.rpt-demo { font-size: 12px; color: var(--text-muted); margin-top: 8px; }

/* Grey note (no warning tone, UX-21): no access, pick a facility, and other next-step lines. */
.rpt-info { color: var(--text-primary); background: #F4F5F5; border-left: 4px solid var(--border-subtle); padding: 8px 14px; font-size: 13px; line-height: 1.45; border-radius: 2px; }
.rpt-details { margin-top: 4px; font-size: 12px; color: var(--text-muted); }
.rpt-details summary { cursor: pointer; }
.rpt-loading { padding: 8px 0; }

/* Next step: one link at the end of a tab. */
.rpt-next { display: flex; align-items: baseline; gap: 10px; font-size: 14px; padding: 4px 0; }
.rpt-next-label { font-size: 12px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.03em; }
.rpt-next a.rpt-link { font-weight: 500; }

/* Start here grid: facilities down the side, reports across; each cell is a link. */
.rpt-start-do { margin: 6px 0 10px; font-size: 14px; }
.rpt-grid { table-layout: fixed; }
.rpt-grid thead th:first-child, .rpt-grid tbody th { width: 16%; }
.rpt-grid tbody th { font-weight: 600; vertical-align: middle; }
.rpt-table.rpt-grid td.rpt-cell { padding: 3px; vertical-align: middle; }
.rpt-cell a { display: block; padding: 5px 8px; border-radius: 4px; text-decoration: none; color: inherit; border: 1px solid transparent; line-height: 1.3; }
.rpt-cell a:hover, .rpt-cell a:focus-visible { border-color: var(--accent); outline: none; }
.rpt-cell-word { display: block; font-weight: 600; font-size: 13px; }
.rpt-cell-n { display: block; font-size: 12px; color: var(--text-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rpt-cell-flag a { background: var(--flag-pill-bg); border-color: var(--flag-bar); }
.rpt-cell-flag .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-flag .rpt-cell-n { color: var(--flag-pill-text); }
.rpt-cell-check a { background: #FFFFFF; border-color: var(--flag-bar); border-style: dashed; }
.rpt-cell-check .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-few a { background: var(--cell-missing-bg); }
.rpt-cell-few .rpt-cell-word { color: var(--guard-pill-text); }
.rpt-cell-fine .rpt-cell-word { font-weight: 400; color: var(--text-muted); }
.rpt-cell-none { color: var(--text-muted); text-align: center; }
.rpt-start-key { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 12px; color: var(--text-muted); margin-top: 8px; }
.rpt-start-key b { color: var(--text-primary); font-weight: 600; }

/* Headline strip with four numbers (Overdue calls). */
.rpt-strip4 { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); height: 100%; }
.rpt-strip4 > div { padding: 2px 14px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip4 > div:first-child { border-left: 0; padding-left: 4px; }

/* Monthly table, place against the average (monthly.js; Metabase titration and statins form). */
.rpt-mt th, .rpt-mt td { padding: 5px 8px; }
.rpt-mt thead tr.rpt-mt-group th { text-align: center; color: var(--text-primary); font-size: 12px; border-bottom: 0 !important; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-place { box-shadow: inset 0 -3px 0 #3D71D9; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-avg { box-shadow: inset 0 -3px 0 #9B7FD4; }
.rpt-mt .rpt-mt-gap { border-left: 1px solid var(--border-subtle) !important; }
.rpt-mt tbody tr.rpt-mt-last > * { font-weight: 700; }
.rpt-mt-few { color: var(--text-muted); font-weight: 400; }

options.afterRender:
// --- Reports shared helpers and states (dashboard_src/reports/_shared/states.js) ---
// Declares one name: rpt. Business Text afterRender only (it reads context.grafana).
const rpt = (() => {
  const grafana = (typeof context !== 'undefined' && context.grafana) || {};
  // A variable's value; '' when the dashboard has no such variable (replaceVariables leaves `${name}`).
  const v = (name) => { const x = grafana.replaceVariables ? String(grafana.replaceVariables('${' + name + '}')) : ''; return x === '${' + name + '}' ? '' : x; };

  const esc = (x) => String(x == null ? '' : x).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const num = (x) => (x === null || x === undefined || x === '' || isNaN(Number(x)) ? null : Number(x));
  // Thousands commas.
  const fmt = (x) => (num(x) === null ? '—' : Math.round(num(x)).toLocaleString('en-US'));
  // Percent: whole, one decimal under 10% (DESIGN Typography).
  const pct = (x) => { const n = num(x); if (n === null) { return '—'; } return (Math.abs(n) < 10 ? n.toFixed(1) : String(Math.round(n))) + '%'; };
  // Scores: two decimals.
  const score = (x) => (num(x) === null ? '—' : num(x).toFixed(2));
  const yes = (x) => x === true || x === 1 || x === 't' || x === 'true';

  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  // Postgres dates arrive as ms numbers or 'YYYY-MM-DD' strings; read them as UTC days.
  const toDate = (x) => { if (x == null || x === '') { return null; } const d = typeof x === 'number' ? new Date(x) : new Date(String(x).slice(0, 10) + 'T00:00:00Z'); return isNaN(d) ? null : d; };
  const day = (x) => { const d = toDate(x); return d ? d.getUTCDate() + '-' + MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };
  const month = (x) => { const d = toDate(x); return d ? MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };

  // Rows of the frame with refId ref, as objects.
  const rows = (ref) => {
    const series = (context.panelData && context.panelData.series) || [];
    const f = series.find((s) => s.refId === ref);
    if (!f) { return []; }
    const cols = f.fields.map((x) => [x.name, Array.from(x.values)]);
    const n = cols.length ? cols[0][1].length : 0;
    return Array.from({ length: n }, (_, i) => Object.fromEntries(cols.map(([k, vals]) => [k, vals[i]])));
  };

  // report_flags rows from a flags_json column (json_agg of {report, flag_reason, patients_n}) on each row.
  const flagsFrom = (list) => [].concat(...(list || []).map((r) => {
    let parsed = [];
    try { parsed = r.flags_json ? JSON.parse(r.flags_json) : []; } catch (e) { parsed = []; }
    return (Array.isArray(parsed) ? parsed : []).map((f) => Object.assign({ org_unit_id: r.org_unit_id, org_unit_name: r.org_unit_name }, f));
  }));

  // Variables, read in the browser so no access query is needed.
  const orgUnit = () => { const o = v('org_unit').trim(); return o && o !== '0' ? o : '0'; };
  const reportingMonth = () => v('reporting_month');
  const allowed = () => v('isAllowed') === '1';

  // The user's home unit (hidden variable home_org_unit, the home dashboard's UserOrgUnitId query).
  // '' for admins and users with access everywhere.
  const homeUnit = () => { const h = v('home_org_unit').trim(); return h && h !== '0' ? h : ''; };

  // Tabs from the builder's TABS list: [{report, title, slug}], in tab order. TABS[0] is `Start here`.
  const TABS = [{"report":"start","title":"Start here","slug":"Start-here"},{"report":"titration","title":"Stepping up","slug":"Stepping-up"},{"report":"adherence","title":"Right medicines","slug":"Right-medicines"},{"report":"fudging","title":"BP readings check","slug":"BP-readings-check"},{"report":"calling","title":"Overdue calls","slug":"Overdue-calls"},{"report":"statins","title":"Statins","slug":"Statins"}];
  // The five report tabs (every tab but `Start here`), in tab order.
  const REPORTS = TABS.filter((t) => t.report !== 'start');
  const tab = (report) => TABS.find((t) => t.report === report) || null;
  // AD-29 deep link; keeps the location and month unless given. extra: more URL parameters,
  // for example { 'var-include_new': 'true' }.
  const link = (report, org, mon, extra) => {
    const t = tab(report);
    if (!t) { return ''; }
    const more = Object.keys(extra || {}).map((k) => '&' + encodeURIComponent(k) + '=' + encodeURIComponent(extra[k])).join('');
    return '/d/heart360_reports?var-org_unit=' + encodeURIComponent(org == null ? orgUnit() : org)
      + '&var-reporting_month=' + encodeURIComponent(mon == null ? reportingMonth() : mon) + more + '&-dtab=' + encodeURIComponent(t.slug);
  };
  // A facility name that narrows this tab to that facility (UX-15). Plain text when it is already the place in view.
  const placeLink = (report, id, name) => (id == null || String(id) === orgUnit() || !tab(report)
    ? esc(name) : '<a class="rpt-link" href="' + esc(link(report, id)) + '" title="' + esc('Show ' + name + ' only') + '">' + esc(name) + '</a>');
  // `Next step` line at the end of a tab: one link, sentence case.
  const nextStep = (text, href) => '<div class="rpt-next"><span class="rpt-next-label">Next step</span>'
    + '<a class="rpt-link" href="' + esc(href) + '">' + esc(text) + ' →</a></div>';
  // Same-page links: an <a href="#some-id"> inside el scrolls the element with that id into view
  // (Grafana scrolls its own pane, so a plain hash link does not move it). Use with nextStep('...', '#id').
  // Grafana draws panels lazily: while the target is not drawn yet, the pane scrolls down a screen at a
  // time until it appears.
  const wireScroll = (el) => {
    if (!el || el.__rptScroll) { return; }
    el.__rptScroll = true;
    const pane = (node) => { let p = node.parentElement; while (p && !(p.scrollHeight > p.clientHeight && /auto|scroll/.test(getComputedStyle(p).overflowY))) { p = p.parentElement; } return p; };
    el.addEventListener('click', (e) => {
      const a = e.target.closest && e.target.closest('a[href^="#"]');
      if (!a || !el.contains(a)) { return; }
      e.preventDefault();
      const id = a.getAttribute('href').slice(1);
      const box = pane(el);
      let tries = 0;
      const go = () => {
        const t = document.getElementById(id);
        if (t) { t.scrollIntoView({ behavior: 'smooth', block: 'start' }); return; }
        if (!box || tries++ > 8) { return; }
        box.scrollTop += Math.round(box.clientHeight * 0.8);
        setTimeout(go, 350);
      };
      go();
    });
  };
  // At or below the facility level (selected_level 3 or more): patient lists and the overdue list work here.
  const atFacility = () => (num(v('selected_level')) || 0) >= 3;

  // --- States (DESIGN States, FR-32) ---
  // Grey note, no warning tone (Voice rule 8, UX-21). html is trusted markup; use esc() on data.
  const info = (html) => '<div class="rpt-info">' + html + '</div>';
  // No access: plain words and the next step. The access team names sit in a closed `Details` for the admin.
  const banner = () => {
    const teams = v('requiredGroups').replace(/<[^>]*>/g, '').trim();
    return info('<span>You cannot see this place. Pick your own area in <strong>Change location</strong> above.</span>'
      + (teams ? '<details class="rpt-details"><summary>Details for your admin</summary>Access comes from: ' + esc(teams) + '</details>' : ''));
  };
  // Shown while the page moves a user with no location to their home unit (UX-02).
  const OPENING_HOME = 'Opening your area…';
  // For views that need one facility (patient lists): a grey line with the next step.
  const PICK_FACILITY = 'Pick a facility in Change location above to see its patients.';
  const NO_DATA = 'No data for this place.';
  const NO_FACILITIES = 'No facilities for this location.';
  const NO_FLAGS = 'No facility is flagged.';
  const noData = (text) => '<div class="rpt-empty">' + esc(text || NO_DATA) + '</div>';
  // "Need at least 20; this place has 12."
  const needAtLeast = (k, n) => 'Need at least ' + fmt(k) + '; this place has ' + fmt(n) + '.';
  // Place for the subtitle: the selected name, or all locations.
  const place = (name) => (orgUnit() === '0' ? 'All locations you can access' : (name || 'This place'));

  // Thresholds from report_flag_thresholds rows ({report, key, value}).
  const thresholds = (list) => { const t = {}; (list || []).forEach((r) => { t[r.report + '.' + r.key] = num(r.value); }); return t; };

  // UX-02: a user with no location who may not see all places is moved to their home unit, keeping
  // the month and tab. Returns true when it does so.
  const goHome = () => {
    const home = homeUnit();
    if (allowed() || orgUnit() !== '0' || !home) { return false; }
    // Several panels call this on one render; move once (a later blank pick moves again).
    if (Date.now() - (window.__rptGoHome || 0) > 3000) {
      window.__rptGoHome = Date.now();
      const ls = grafana.locationService;
      if (ls && ls.partial) { ls.partial({ 'var-org_unit': home }, true); }
      else { const u = new URL(window.location.href); u.searchParams.set('var-org_unit', home); window.location.replace(u.toString()); }
    }
    return true;
  };
  // True while the panel's query is still running.
  const loading = () => !!(context.panelData && context.panelData.state === 'Loading');

  // Mount: returns the root element, or null when access is denied. The banner is drawn once per tab,
  // by the panel mounted with { banner: true } (the title strip); other panels stay empty under it.
  // A user with no location is first moved to their home unit (UX-02); meanwhile the banner panel
  // shows `Opening your area…`. opts.loading: a line to show while the query runs (null is returned).
  const mount = (selector, opts) => {
    const o = opts || {};
    const root = context.element.querySelector(selector);
    if (!root) { return null; }
    if (goHome()) { root.innerHTML = o.banner ? '<div class="rpt-muted">' + esc(OPENING_HOME) + '</div>' : ''; return null; }
    if (!allowed()) { root.innerHTML = o.banner ? banner() : ''; return null; }
    if (o.loading && loading()) { root.innerHTML = '<div class="rpt-muted rpt-loading">' + esc(o.loading) + '</div>'; return null; }
    return root;
  };

  return { v, esc, num, fmt, pct, score, yes, day, month, toDate, rows, orgUnit, reportingMonth, allowed, homeUnit,
    TABS, REPORTS, tab, link, placeLink, nextStep, wireScroll, atFacility, flagsFrom, info, banner, OPENING_HOME, PICK_FACILITY,
    NO_DATA, NO_FACILITIES, NO_FLAGS, noData, needAtLeast, place, thresholds, loading, goHome, mount };
})();
// Title strip: the question, then "{place} · latest visit up to {date}", and the Patients counted switch (UX-38).
const root = rpt.mount('.rpt-adh-title', { banner: true });
if (!root) { return; }
const w = rpt.rows('A')[0] || {};
const withNew = rpt.v('include_new') === 'true';
const chip = (on, text, val) => (on ? '<span class="rpt-chip on" aria-current="true">' + rpt.esc(text) + '</span>'
  : '<a class="rpt-chip" href="' + rpt.esc(rpt.link('adherence', null, null, { 'var-include_new': val })) + '">' + rpt.esc(text) + '</a>');
root.innerHTML = '<div class="rpt-adh-row"><div><h2 class="rpt-title">Are patients on the medicines the protocol says?</h2>'
  + '<div class="rpt-sub">' + rpt.esc(rpt.place(w.place)) + ' · medicines at the latest visit up to ' + rpt.esc(rpt.day(w.window_end)) + '</div></div>'
  + '<div class="rpt-chips" role="group" aria-label="Patients counted"><span class="rpt-sub">Patients counted:</span>'
  + chip(!withNew, 'Registered before ' + rpt.day(w.window_start), 'false') + chip(withNew, 'Include new patients', 'true') + '</div></div>';

options.styles:
/* --- Reports shared styles (dashboard_src/reports/_shared/styles.css) ---
   Business Text styles. Every class starts rpt-; put class "rpt" on the panel's root div.
   Tokens: ux-hearts360-mvp-2026-11-04/DESIGN.md front matter. Table, chips, pager and banner copy
   the program dashboard's overdue list (.ovq-*). Light theme only (A40). */
.rpt {
  --text-primary: #111217; --text-muted: #6E6E6E; --border-subtle: #D8D9DA; --accent: #3D71D9;
  --controlled: #3BB231; --uncontrolled: #EEAB00; --no-visit: #ED6300;
  --flag-bar: #ED6300; --flag-row-bg: #FDF0E6; --flag-pill-bg: #FDE3CF; --flag-pill-text: #8A3A00;
  --guard-pill-text: #4E545A; --cell-missing-bg: #EFEFEF;
  font-size: 13px; line-height: 1.35; color: var(--text-primary);
}
.rpt a.rpt-link { color: #0075eb; text-decoration: none; }
.rpt a.rpt-link:hover, .rpt a.rpt-link:focus-visible { text-decoration: underline; }
.rpt-sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.rpt-muted { color: var(--text-muted); }
.rpt-empty { color: var(--text-muted); font-size: 14px; text-align: center; padding: 18px 8px; }

/* Title strip: question (card-title), then "{place} · {period}" (microcopy, muted). */
.rpt-title { font-size: 16px; font-weight: 500; margin: 0 0 2px; line-height: 1.3; }
.rpt-sub { font-size: 12px; color: var(--text-muted); line-height: 1.4; }

/* Headline strip: three equal columns, thin dividers (as panel-outcomes). */
.rpt-strip3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); height: 100%; }
.rpt-strip3 > div { padding: 2px 16px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip3 > div:first-child { border-left: 0; padding-left: 4px; }
.rpt-big { font-size: 32px; font-weight: 600; line-height: 1.1; font-variant-numeric: tabular-nums; }
.rpt-big.rpt-few { font-size: 20px; font-weight: 500; color: var(--text-muted); line-height: 1.6; }
.rpt-label { font-size: 14px; font-weight: 500; margin-top: 2px; }
.rpt-line { font-size: 12px; color: var(--text-muted); line-height: 1.4; margin-top: 2px; }

/* Look at these first: at most three items. */
.rpt-card-title { font-size: 16px; font-weight: 500; margin: 0 0 8px; }
.rpt-look { list-style: none; margin: 0; padding: 0; }
.rpt-look li { padding: 8px 0 8px 10px; border-left: 4px solid var(--flag-bar); background: var(--flag-row-bg); margin-bottom: 8px; border-radius: 0 4px 4px 0; }
.rpt-look-name { font-weight: 600; }
.rpt-look-line { font-size: 12px; line-height: 1.4; margin-top: 2px; }

/* Facility table: overdue list style. No vertical lines or stripes, light header, hover highlight. */
.rpt-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.rpt-chip { font: inherit; font-size: 12px; border: 1px solid #d9e3ff; background: transparent; color: inherit; border-radius: 14px; padding: 2px 10px; cursor: pointer; text-decoration: none; display: inline-block; white-space: nowrap; }
.rpt-chip.on { background: #0075eb; border-color: #0075eb; color: #fff; cursor: default; }
a.rpt-chip:hover, button.rpt-chip:not(.on):hover { background: #EEF3FD; }
.rpt-wrap { overflow-x: auto; }
.rpt-table { width: 100%; border-collapse: collapse; border: 0; }
.rpt-table th, .rpt-table td { border: 0 !important; border-bottom: 1px solid rgba(128,128,128,0.2) !important; padding: 8px 8px; text-align: left; vertical-align: top; }
.rpt-table thead th { background: rgba(0,117,235,0.06); color: #6e7f8d; font-size: 12px; font-weight: 600; white-space: nowrap; vertical-align: bottom; }
.rpt-table tbody th { font-weight: 400; white-space: nowrap; background: transparent; color: inherit; }
.rpt-table tbody tr:hover { background: rgba(0,117,235,0.04); }
.rpt-table .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.rpt-table thead th.num .rpt-sortbtn { text-align: right; }
.rpt-table td.rpt-why { width: 42%; min-width: 260px; }
.rpt-sortbtn { font: inherit; font-weight: 600; background: none; border: 0; padding: 0; color: inherit; cursor: pointer; }
.rpt-sortbtn:focus-visible, .rpt-chip:focus-visible, .rpt-pager button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* Flagged row: 4px orange bar and light tint. */
.rpt-table tr.rpt-flagged, .rpt-table tr.rpt-flagged:hover { background: var(--flag-row-bg); }
.rpt-table tr.rpt-flagged > th:first-child { box-shadow: inset 4px 0 0 var(--flag-bar); padding-left: 12px; }
/* All places in view: bold first row. */
.rpt-table tr.rpt-total > th, .rpt-table tr.rpt-total > td { font-weight: 700; }
.rpt-table tr.rpt-total .rpt-reason, .rpt-table tr.rpt-total .rpt-pill { font-weight: 400; }
.rpt-ctl { color: var(--controlled); font-weight: 600; }
/* Pills: text, never colour only. */
.rpt-pills { display: flex; flex-wrap: wrap; gap: 4px; }
.rpt-pill { display: inline-block; padding: 1px 8px; border-radius: 9999px; font-size: 12px; font-weight: 600; white-space: nowrap; line-height: 1.5; }
.rpt-pill-flag { background: var(--flag-pill-bg); color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-check { background: #FFFFFF; color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-guard { background: var(--cell-missing-bg); color: var(--guard-pill-text); border: 1px solid var(--cell-missing-bg); }
.rpt-reason { font-size: 12px; line-height: 1.4; margin-top: 3px; color: var(--text-primary); }
.rpt-also { font-size: 12px; margin-top: 3px; }
.rpt-also a { color: #0075eb; text-decoration: none; }
.rpt-also a:hover, .rpt-also a:focus-visible { text-decoration: underline; }
.rpt-clean { color: var(--text-muted); }
/* Pager: overdue list. */
.rpt-pager { display: flex; justify-content: center; align-items: center; gap: 12px; padding: 10px 0 2px; }
.rpt-pager button { font: inherit; width: 28px; height: 26px; border-radius: 4px; border: 1px solid #d9e3ff; background: transparent; color: inherit; cursor: pointer; }
.rpt-pager button:disabled { opacity: 0.35; cursor: default; }
/* Access banner: the overdue list's .ovq-warn. */
.rpt-warn { color: #e02424; background: rgba(224,36,36,0.05); border-left: 4px solid #e02424; padding: 8px 14px; font-size: 13px; display: flex; align-items: center; gap: 8px; border-radius: 2px; line-height: 1.4; }

/* How this is worked out. */
.rpt-note { font-size: 12px; color: var(--text-muted); line-height: 1.45; }

.rpt-demo { font-size: 12px; color: var(--text-muted); margin-top: 8px; }

/* Grey note (no warning tone, UX-21): no access, pick a facility, and other next-step lines. */
.rpt-info { color: var(--text-primary); background: #F4F5F5; border-left: 4px solid var(--border-subtle); padding: 8px 14px; font-size: 13px; line-height: 1.45; border-radius: 2px; }
.rpt-details { margin-top: 4px; font-size: 12px; color: var(--text-muted); }
.rpt-details summary { cursor: pointer; }
.rpt-loading { padding: 8px 0; }

/* Next step: one link at the end of a tab. */
.rpt-next { display: flex; align-items: baseline; gap: 10px; font-size: 14px; padding: 4px 0; }
.rpt-next-label { font-size: 12px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.03em; }
.rpt-next a.rpt-link { font-weight: 500; }

/* Start here grid: facilities down the side, reports across; each cell is a link. */
.rpt-start-do { margin: 6px 0 10px; font-size: 14px; }
.rpt-grid { table-layout: fixed; }
.rpt-grid thead th:first-child, .rpt-grid tbody th { width: 16%; }
.rpt-grid tbody th { font-weight: 600; vertical-align: middle; }
.rpt-table.rpt-grid td.rpt-cell { padding: 3px; vertical-align: middle; }
.rpt-cell a { display: block; padding: 5px 8px; border-radius: 4px; text-decoration: none; color: inherit; border: 1px solid transparent; line-height: 1.3; }
.rpt-cell a:hover, .rpt-cell a:focus-visible { border-color: var(--accent); outline: none; }
.rpt-cell-word { display: block; font-weight: 600; font-size: 13px; }
.rpt-cell-n { display: block; font-size: 12px; color: var(--text-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rpt-cell-flag a { background: var(--flag-pill-bg); border-color: var(--flag-bar); }
.rpt-cell-flag .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-flag .rpt-cell-n { color: var(--flag-pill-text); }
.rpt-cell-check a { background: #FFFFFF; border-color: var(--flag-bar); border-style: dashed; }
.rpt-cell-check .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-few a { background: var(--cell-missing-bg); }
.rpt-cell-few .rpt-cell-word { color: var(--guard-pill-text); }
.rpt-cell-fine .rpt-cell-word { font-weight: 400; color: var(--text-muted); }
.rpt-cell-none { color: var(--text-muted); text-align: center; }
.rpt-start-key { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 12px; color: var(--text-muted); margin-top: 8px; }
.rpt-start-key b { color: var(--text-primary); font-weight: 600; }

/* Headline strip with four numbers (Overdue calls). */
.rpt-strip4 { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); height: 100%; }
.rpt-strip4 > div { padding: 2px 14px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip4 > div:first-child { border-left: 0; padding-left: 4px; }

/* Monthly table, place against the average (monthly.js; Metabase titration and statins form). */
.rpt-mt th, .rpt-mt td { padding: 5px 8px; }
.rpt-mt thead tr.rpt-mt-group th { text-align: center; color: var(--text-primary); font-size: 12px; border-bottom: 0 !important; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-place { box-shadow: inset 0 -3px 0 #3D71D9; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-avg { box-shadow: inset 0 -3px 0 #9B7FD4; }
.rpt-mt .rpt-mt-gap { border-left: 1px solid var(--border-subtle) !important; }
.rpt-mt tbody tr.rpt-mt-last > * { font-weight: 700; }
.rpt-mt-few { color: var(--text-muted); font-weight: 400; }
.rpt-adh-row { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; flex-wrap: wrap; }
.rpt-adh-row .rpt-chips { align-items: center; margin: 0; }

options.afterRender:
// --- Reports shared helpers and states (dashboard_src/reports/_shared/states.js) ---
// Declares one name: rpt. Business Text afterRender only (it reads context.grafana).
const rpt = (() => {
  const grafana = (typeof context !== 'undefined' && context.grafana) || {};
  // A variable's value; '' when the dashboard has no such variable (replaceVariables leaves `${name}`).
  const v = (name) => { const x = grafana.replaceVariables ? String(grafana.replaceVariables('${' + name + '}')) : ''; return x === '${' + name + '}' ? '' : x; };

  const esc = (x) => String(x == null ? '' : x).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const num = (x) => (x === null || x === undefined || x === '' || isNaN(Number(x)) ? null : Number(x));
  // Thousands commas.
  const fmt = (x) => (num(x) === null ? '—' : Math.round(num(x)).toLocaleString('en-US'));
  // Percent: whole, one decimal under 10% (DESIGN Typography).
  const pct = (x) => { const n = num(x); if (n === null) { return '—'; } return (Math.abs(n) < 10 ? n.toFixed(1) : String(Math.round(n))) + '%'; };
  // Scores: two decimals.
  const score = (x) => (num(x) === null ? '—' : num(x).toFixed(2));
  const yes = (x) => x === true || x === 1 || x === 't' || x === 'true';

  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  // Postgres dates arrive as ms numbers or 'YYYY-MM-DD' strings; read them as UTC days.
  const toDate = (x) => { if (x == null || x === '') { return null; } const d = typeof x === 'number' ? new Date(x) : new Date(String(x).slice(0, 10) + 'T00:00:00Z'); return isNaN(d) ? null : d; };
  const day = (x) => { const d = toDate(x); return d ? d.getUTCDate() + '-' + MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };
  const month = (x) => { const d = toDate(x); return d ? MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };

  // Rows of the frame with refId ref, as objects.
  const rows = (ref) => {
    const series = (context.panelData && context.panelData.series) || [];
    const f = series.find((s) => s.refId === ref);
    if (!f) { return []; }
    const cols = f.fields.map((x) => [x.name, Array.from(x.values)]);
    const n = cols.length ? cols[0][1].length : 0;
    return Array.from({ length: n }, (_, i) => Object.fromEntries(cols.map(([k, vals]) => [k, vals[i]])));
  };

  // report_flags rows from a flags_json column (json_agg of {report, flag_reason, patients_n}) on each row.
  const flagsFrom = (list) => [].concat(...(list || []).map((r) => {
    let parsed = [];
    try { parsed = r.flags_json ? JSON.parse(r.flags_json) : []; } catch (e) { parsed = []; }
    return (Array.isArray(parsed) ? parsed : []).map((f) => Object.assign({ org_unit_id: r.org_unit_id, org_unit_name: r.org_unit_name }, f));
  }));

  // Variables, read in the browser so no access query is needed.
  const orgUnit = () => { const o = v('org_unit').trim(); return o && o !== '0' ? o : '0'; };
  const reportingMonth = () => v('reporting_month');
  const allowed = () => v('isAllowed') === '1';

  // The user's home unit (hidden variable home_org_unit, the home dashboard's UserOrgUnitId query).
  // '' for admins and users with access everywhere.
  const homeUnit = () => { const h = v('home_org_unit').trim(); return h && h !== '0' ? h : ''; };

  // Tabs from the builder's TABS list: [{report, title, slug}], in tab order. TABS[0] is `Start here`.
  const TABS = [{"report":"start","title":"Start here","slug":"Start-here"},{"report":"titration","title":"Stepping up","slug":"Stepping-up"},{"report":"adherence","title":"Right medicines","slug":"Right-medicines"},{"report":"fudging","title":"BP readings check","slug":"BP-readings-check"},{"report":"calling","title":"Overdue calls","slug":"Overdue-calls"},{"report":"statins","title":"Statins","slug":"Statins"}];
  // The five report tabs (every tab but `Start here`), in tab order.
  const REPORTS = TABS.filter((t) => t.report !== 'start');
  const tab = (report) => TABS.find((t) => t.report === report) || null;
  // AD-29 deep link; keeps the location and month unless given. extra: more URL parameters,
  // for example { 'var-include_new': 'true' }.
  const link = (report, org, mon, extra) => {
    const t = tab(report);
    if (!t) { return ''; }
    const more = Object.keys(extra || {}).map((k) => '&' + encodeURIComponent(k) + '=' + encodeURIComponent(extra[k])).join('');
    return '/d/heart360_reports?var-org_unit=' + encodeURIComponent(org == null ? orgUnit() : org)
      + '&var-reporting_month=' + encodeURIComponent(mon == null ? reportingMonth() : mon) + more + '&-dtab=' + encodeURIComponent(t.slug);
  };
  // A facility name that narrows this tab to that facility (UX-15). Plain text when it is already the place in view.
  const placeLink = (report, id, name) => (id == null || String(id) === orgUnit() || !tab(report)
    ? esc(name) : '<a class="rpt-link" href="' + esc(link(report, id)) + '" title="' + esc('Show ' + name + ' only') + '">' + esc(name) + '</a>');
  // `Next step` line at the end of a tab: one link, sentence case.
  const nextStep = (text, href) => '<div class="rpt-next"><span class="rpt-next-label">Next step</span>'
    + '<a class="rpt-link" href="' + esc(href) + '">' + esc(text) + ' →</a></div>';
  // Same-page links: an <a href="#some-id"> inside el scrolls the element with that id into view
  // (Grafana scrolls its own pane, so a plain hash link does not move it). Use with nextStep('...', '#id').
  // Grafana draws panels lazily: while the target is not drawn yet, the pane scrolls down a screen at a
  // time until it appears.
  const wireScroll = (el) => {
    if (!el || el.__rptScroll) { return; }
    el.__rptScroll = true;
    const pane = (node) => { let p = node.parentElement; while (p && !(p.scrollHeight > p.clientHeight && /auto|scroll/.test(getComputedStyle(p).overflowY))) { p = p.parentElement; } return p; };
    el.addEventListener('click', (e) => {
      const a = e.target.closest && e.target.closest('a[href^="#"]');
      if (!a || !el.contains(a)) { return; }
      e.preventDefault();
      const id = a.getAttribute('href').slice(1);
      const box = pane(el);
      let tries = 0;
      const go = () => {
        const t = document.getElementById(id);
        if (t) { t.scrollIntoView({ behavior: 'smooth', block: 'start' }); return; }
        if (!box || tries++ > 8) { return; }
        box.scrollTop += Math.round(box.clientHeight * 0.8);
        setTimeout(go, 350);
      };
      go();
    });
  };
  // At or below the facility level (selected_level 3 or more): patient lists and the overdue list work here.
  const atFacility = () => (num(v('selected_level')) || 0) >= 3;

  // --- States (DESIGN States, FR-32) ---
  // Grey note, no warning tone (Voice rule 8, UX-21). html is trusted markup; use esc() on data.
  const info = (html) => '<div class="rpt-info">' + html + '</div>';
  // No access: plain words and the next step. The access team names sit in a closed `Details` for the admin.
  const banner = () => {
    const teams = v('requiredGroups').replace(/<[^>]*>/g, '').trim();
    return info('<span>You cannot see this place. Pick your own area in <strong>Change location</strong> above.</span>'
      + (teams ? '<details class="rpt-details"><summary>Details for your admin</summary>Access comes from: ' + esc(teams) + '</details>' : ''));
  };
  // Shown while the page moves a user with no location to their home unit (UX-02).
  const OPENING_HOME = 'Opening your area…';
  // For views that need one facility (patient lists): a grey line with the next step.
  const PICK_FACILITY = 'Pick a facility in Change location above to see its patients.';
  const NO_DATA = 'No data for this place.';
  const NO_FACILITIES = 'No facilities for this location.';
  const NO_FLAGS = 'No facility is flagged.';
  const noData = (text) => '<div class="rpt-empty">' + esc(text || NO_DATA) + '</div>';
  // "Need at least 20; this place has 12."
  const needAtLeast = (k, n) => 'Need at least ' + fmt(k) + '; this place has ' + fmt(n) + '.';
  // Place for the subtitle: the selected name, or all locations.
  const place = (name) => (orgUnit() === '0' ? 'All locations you can access' : (name || 'This place'));

  // Thresholds from report_flag_thresholds rows ({report, key, value}).
  const thresholds = (list) => { const t = {}; (list || []).forEach((r) => { t[r.report + '.' + r.key] = num(r.value); }); return t; };

  // UX-02: a user with no location who may not see all places is moved to their home unit, keeping
  // the month and tab. Returns true when it does so.
  const goHome = () => {
    const home = homeUnit();
    if (allowed() || orgUnit() !== '0' || !home) { return false; }
    // Several panels call this on one render; move once (a later blank pick moves again).
    if (Date.now() - (window.__rptGoHome || 0) > 3000) {
      window.__rptGoHome = Date.now();
      const ls = grafana.locationService;
      if (ls && ls.partial) { ls.partial({ 'var-org_unit': home }, true); }
      else { const u = new URL(window.location.href); u.searchParams.set('var-org_unit', home); window.location.replace(u.toString()); }
    }
    return true;
  };
  // True while the panel's query is still running.
  const loading = () => !!(context.panelData && context.panelData.state === 'Loading');

  // Mount: returns the root element, or null when access is denied. The banner is drawn once per tab,
  // by the panel mounted with { banner: true } (the title strip); other panels stay empty under it.
  // A user with no location is first moved to their home unit (UX-02); meanwhile the banner panel
  // shows `Opening your area…`. opts.loading: a line to show while the query runs (null is returned).
  const mount = (selector, opts) => {
    const o = opts || {};
    const root = context.element.querySelector(selector);
    if (!root) { return null; }
    if (goHome()) { root.innerHTML = o.banner ? '<div class="rpt-muted">' + esc(OPENING_HOME) + '</div>' : ''; return null; }
    if (!allowed()) { root.innerHTML = o.banner ? banner() : ''; return null; }
    if (o.loading && loading()) { root.innerHTML = '<div class="rpt-muted rpt-loading">' + esc(o.loading) + '</div>'; return null; }
    return root;
  };

  return { v, esc, num, fmt, pct, score, yes, day, month, toDate, rows, orgUnit, reportingMonth, allowed, homeUnit,
    TABS, REPORTS, tab, link, placeLink, nextStep, wireScroll, atFacility, flagsFrom, info, banner, OPENING_HOME, PICK_FACILITY,
    NO_DATA, NO_FACILITIES, NO_FLAGS, noData, needAtLeast, place, thresholds, loading, goHome, mount };
})();
const col = (big, color, label, lines, title, few) => '<div' + (title ? ' title="' + rpt.esc(title) + '"' : '') + '>'
  + '<div class="rpt-big' + (few ? ' rpt-few' : '') + '"' + (color ? ' style="color:' + color + '"' : '') + '>' + rpt.esc(big) + '</div>'
  + '<div class="rpt-label">' + rpt.esc(label) + '</div>' + [].concat(lines).filter(Boolean).map((l) => '<div class="rpt-line">' + rpt.esc(l) + '</div>').join('') + '</div>';
// Headline strip: BP controlled (the Hypertension tab's number, UX-03), On step 3 or higher, Off protocol.
const root = rpt.mount('.rpt-adh-head');
if (!root) { return; }
const { fmt, num, yes, pct } = rpt;
const r = rpt.rows('A')[0];
const L = ['BP controlled', 'On step 3 or higher', 'Off protocol'];
if (!r) { root.innerHTML = '<div class="rpt-strip3">' + L.map((l) => col('—', '', l, rpt.NO_DATA)).join('') + '</div>'; return; }
const ctl = num(r.control_pct) === null ? col('—', '', L[0], rpt.NO_DATA)
  : col(pct(r.control_pct), 'var(--controlled)', L[0], [fmt(r.controlled_n) + ' of ' + fmt(r.under_care_n) + ' patients under care', 'Same as the Hypertension tab']);
const N = num(r.cohort_n) || 0;
const seen = ' of ' + fmt(N) + ' patients seen in the last 3 months';
if (!N || yes(r.too_few)) {
  const why = N ? rpt.needAtLeast(r.min_cohort, N) : rpt.NO_DATA;
  root.innerHTML = '<div class="rpt-strip3">' + ctl + col(N ? 'Too few patients' : '—', '', L[1], why, '', !!N)
    + col(N ? 'Too few patients' : '—', '', L[2], why, '', !!N) + '</div>';
  return;
}
const offHigh = num(r.off_protocol_pct) !== null && num(r.off_protocol_pct) >= num(r.off_protocol_pct_line);
root.innerHTML = '<div class="rpt-strip3">' + ctl
  + col(pct(r.step_3_plus_pct), 'var(--text-primary)', L[1], [fmt(r.step_3_plus_n) + seen, 'Steps 3 to 6: two or three medicines'])
  + col(pct(r.off_protocol_pct), offHigh ? 'var(--flag-bar)' : 'var(--text-primary)', L[2],
    [fmt(r.off_protocol_n) + seen, 'Another mix, or medicine outside the protocol']) + '</div>';

options.styles:
/* --- Reports shared styles (dashboard_src/reports/_shared/styles.css) ---
   Business Text styles. Every class starts rpt-; put class "rpt" on the panel's root div.
   Tokens: ux-hearts360-mvp-2026-11-04/DESIGN.md front matter. Table, chips, pager and banner copy
   the program dashboard's overdue list (.ovq-*). Light theme only (A40). */
.rpt {
  --text-primary: #111217; --text-muted: #6E6E6E; --border-subtle: #D8D9DA; --accent: #3D71D9;
  --controlled: #3BB231; --uncontrolled: #EEAB00; --no-visit: #ED6300;
  --flag-bar: #ED6300; --flag-row-bg: #FDF0E6; --flag-pill-bg: #FDE3CF; --flag-pill-text: #8A3A00;
  --guard-pill-text: #4E545A; --cell-missing-bg: #EFEFEF;
  font-size: 13px; line-height: 1.35; color: var(--text-primary);
}
.rpt a.rpt-link { color: #0075eb; text-decoration: none; }
.rpt a.rpt-link:hover, .rpt a.rpt-link:focus-visible { text-decoration: underline; }
.rpt-sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.rpt-muted { color: var(--text-muted); }
.rpt-empty { color: var(--text-muted); font-size: 14px; text-align: center; padding: 18px 8px; }

/* Title strip: question (card-title), then "{place} · {period}" (microcopy, muted). */
.rpt-title { font-size: 16px; font-weight: 500; margin: 0 0 2px; line-height: 1.3; }
.rpt-sub { font-size: 12px; color: var(--text-muted); line-height: 1.4; }

/* Headline strip: three equal columns, thin dividers (as panel-outcomes). */
.rpt-strip3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); height: 100%; }
.rpt-strip3 > div { padding: 2px 16px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip3 > div:first-child { border-left: 0; padding-left: 4px; }
.rpt-big { font-size: 32px; font-weight: 600; line-height: 1.1; font-variant-numeric: tabular-nums; }
.rpt-big.rpt-few { font-size: 20px; font-weight: 500; color: var(--text-muted); line-height: 1.6; }
.rpt-label { font-size: 14px; font-weight: 500; margin-top: 2px; }
.rpt-line { font-size: 12px; color: var(--text-muted); line-height: 1.4; margin-top: 2px; }

/* Look at these first: at most three items. */
.rpt-card-title { font-size: 16px; font-weight: 500; margin: 0 0 8px; }
.rpt-look { list-style: none; margin: 0; padding: 0; }
.rpt-look li { padding: 8px 0 8px 10px; border-left: 4px solid var(--flag-bar); background: var(--flag-row-bg); margin-bottom: 8px; border-radius: 0 4px 4px 0; }
.rpt-look-name { font-weight: 600; }
.rpt-look-line { font-size: 12px; line-height: 1.4; margin-top: 2px; }

/* Facility table: overdue list style. No vertical lines or stripes, light header, hover highlight. */
.rpt-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.rpt-chip { font: inherit; font-size: 12px; border: 1px solid #d9e3ff; background: transparent; color: inherit; border-radius: 14px; padding: 2px 10px; cursor: pointer; text-decoration: none; display: inline-block; white-space: nowrap; }
.rpt-chip.on { background: #0075eb; border-color: #0075eb; color: #fff; cursor: default; }
a.rpt-chip:hover, button.rpt-chip:not(.on):hover { background: #EEF3FD; }
.rpt-wrap { overflow-x: auto; }
.rpt-table { width: 100%; border-collapse: collapse; border: 0; }
.rpt-table th, .rpt-table td { border: 0 !important; border-bottom: 1px solid rgba(128,128,128,0.2) !important; padding: 8px 8px; text-align: left; vertical-align: top; }
.rpt-table thead th { background: rgba(0,117,235,0.06); color: #6e7f8d; font-size: 12px; font-weight: 600; white-space: nowrap; vertical-align: bottom; }
.rpt-table tbody th { font-weight: 400; white-space: nowrap; background: transparent; color: inherit; }
.rpt-table tbody tr:hover { background: rgba(0,117,235,0.04); }
.rpt-table .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.rpt-table thead th.num .rpt-sortbtn { text-align: right; }
.rpt-table td.rpt-why { width: 42%; min-width: 260px; }
.rpt-sortbtn { font: inherit; font-weight: 600; background: none; border: 0; padding: 0; color: inherit; cursor: pointer; }
.rpt-sortbtn:focus-visible, .rpt-chip:focus-visible, .rpt-pager button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* Flagged row: 4px orange bar and light tint. */
.rpt-table tr.rpt-flagged, .rpt-table tr.rpt-flagged:hover { background: var(--flag-row-bg); }
.rpt-table tr.rpt-flagged > th:first-child { box-shadow: inset 4px 0 0 var(--flag-bar); padding-left: 12px; }
/* All places in view: bold first row. */
.rpt-table tr.rpt-total > th, .rpt-table tr.rpt-total > td { font-weight: 700; }
.rpt-table tr.rpt-total .rpt-reason, .rpt-table tr.rpt-total .rpt-pill { font-weight: 400; }
.rpt-ctl { color: var(--controlled); font-weight: 600; }
/* Pills: text, never colour only. */
.rpt-pills { display: flex; flex-wrap: wrap; gap: 4px; }
.rpt-pill { display: inline-block; padding: 1px 8px; border-radius: 9999px; font-size: 12px; font-weight: 600; white-space: nowrap; line-height: 1.5; }
.rpt-pill-flag { background: var(--flag-pill-bg); color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-check { background: #FFFFFF; color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-guard { background: var(--cell-missing-bg); color: var(--guard-pill-text); border: 1px solid var(--cell-missing-bg); }
.rpt-reason { font-size: 12px; line-height: 1.4; margin-top: 3px; color: var(--text-primary); }
.rpt-also { font-size: 12px; margin-top: 3px; }
.rpt-also a { color: #0075eb; text-decoration: none; }
.rpt-also a:hover, .rpt-also a:focus-visible { text-decoration: underline; }
.rpt-clean { color: var(--text-muted); }
/* Pager: overdue list. */
.rpt-pager { display: flex; justify-content: center; align-items: center; gap: 12px; padding: 10px 0 2px; }
.rpt-pager button { font: inherit; width: 28px; height: 26px; border-radius: 4px; border: 1px solid #d9e3ff; background: transparent; color: inherit; cursor: pointer; }
.rpt-pager button:disabled { opacity: 0.35; cursor: default; }
/* Access banner: the overdue list's .ovq-warn. */
.rpt-warn { color: #e02424; background: rgba(224,36,36,0.05); border-left: 4px solid #e02424; padding: 8px 14px; font-size: 13px; display: flex; align-items: center; gap: 8px; border-radius: 2px; line-height: 1.4; }

/* How this is worked out. */
.rpt-note { font-size: 12px; color: var(--text-muted); line-height: 1.45; }

.rpt-demo { font-size: 12px; color: var(--text-muted); margin-top: 8px; }

/* Grey note (no warning tone, UX-21): no access, pick a facility, and other next-step lines. */
.rpt-info { color: var(--text-primary); background: #F4F5F5; border-left: 4px solid var(--border-subtle); padding: 8px 14px; font-size: 13px; line-height: 1.45; border-radius: 2px; }
.rpt-details { margin-top: 4px; font-size: 12px; color: var(--text-muted); }
.rpt-details summary { cursor: pointer; }
.rpt-loading { padding: 8px 0; }

/* Next step: one link at the end of a tab. */
.rpt-next { display: flex; align-items: baseline; gap: 10px; font-size: 14px; padding: 4px 0; }
.rpt-next-label { font-size: 12px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.03em; }
.rpt-next a.rpt-link { font-weight: 500; }

/* Start here grid: facilities down the side, reports across; each cell is a link. */
.rpt-start-do { margin: 6px 0 10px; font-size: 14px; }
.rpt-grid { table-layout: fixed; }
.rpt-grid thead th:first-child, .rpt-grid tbody th { width: 16%; }
.rpt-grid tbody th { font-weight: 600; vertical-align: middle; }
.rpt-table.rpt-grid td.rpt-cell { padding: 3px; vertical-align: middle; }
.rpt-cell a { display: block; padding: 5px 8px; border-radius: 4px; text-decoration: none; color: inherit; border: 1px solid transparent; line-height: 1.3; }
.rpt-cell a:hover, .rpt-cell a:focus-visible { border-color: var(--accent); outline: none; }
.rpt-cell-word { display: block; font-weight: 600; font-size: 13px; }
.rpt-cell-n { display: block; font-size: 12px; color: var(--text-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rpt-cell-flag a { background: var(--flag-pill-bg); border-color: var(--flag-bar); }
.rpt-cell-flag .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-flag .rpt-cell-n { color: var(--flag-pill-text); }
.rpt-cell-check a { background: #FFFFFF; border-color: var(--flag-bar); border-style: dashed; }
.rpt-cell-check .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-few a { background: var(--cell-missing-bg); }
.rpt-cell-few .rpt-cell-word { color: var(--guard-pill-text); }
.rpt-cell-fine .rpt-cell-word { font-weight: 400; color: var(--text-muted); }
.rpt-cell-none { color: var(--text-muted); text-align: center; }
.rpt-start-key { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 12px; color: var(--text-muted); margin-top: 8px; }
.rpt-start-key b { color: var(--text-primary); font-weight: 600; }

/* Headline strip with four numbers (Overdue calls). */
.rpt-strip4 { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); height: 100%; }
.rpt-strip4 > div { padding: 2px 14px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip4 > div:first-child { border-left: 0; padding-left: 4px; }

/* Monthly table, place against the average (monthly.js; Metabase titration and statins form). */
.rpt-mt th, .rpt-mt td { padding: 5px 8px; }
.rpt-mt thead tr.rpt-mt-group th { text-align: center; color: var(--text-primary); font-size: 12px; border-bottom: 0 !important; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-place { box-shadow: inset 0 -3px 0 #3D71D9; }
.rpt-mt thead tr.rpt-mt-group th.rpt-mt-avg { box-shadow: inset 0 -3px 0 #9B7FD4; }
.rpt-mt .rpt-mt-gap { border-left: 1px solid var(--border-subtle) !important; }
.rpt-mt tbody tr.rpt-mt-last > * { font-weight: 700; }
.rpt-mt-few { color: var(--text-muted); font-weight: 400; }

options.afterRender:
// --- Reports shared helpers and states (dashboard_src/reports/_shared/states.js) ---
// Declares one name: rpt. Business Text afterRender only (it reads context.grafana).
const rpt = (() => {
  const grafana = (typeof context !== 'undefined' && context.grafana) || {};
  // A variable's value; '' when the dashboard has no such variable (replaceVariables leaves `${name}`).
  const v = (name) => { const x = grafana.replaceVariables ? String(grafana.replaceVariables('${' + name + '}')) : ''; return x === '${' + name + '}' ? '' : x; };

  const esc = (x) => String(x == null ? '' : x).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const num = (x) => (x === null || x === undefined || x === '' || isNaN(Number(x)) ? null : Number(x));
  // Thousands commas.
  const fmt = (x) => (num(x) === null ? '—' : Math.round(num(x)).toLocaleString('en-US'));
  // Percent: whole, one decimal under 10% (DESIGN Typography).
  const pct = (x) => { const n = num(x); if (n === null) { return '—'; } return (Math.abs(n) < 10 ? n.toFixed(1) : String(Math.round(n))) + '%'; };
  // Scores: two decimals.
  const score = (x) => (num(x) === null ? '—' : num(x).toFixed(2));
  const yes = (x) => x === true || x === 1 || x === 't' || x === 'true';

  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  // Postgres dates arrive as ms numbers or 'YYYY-MM-DD' strings; read them as UTC days.
  const toDate = (x) => { if (x == null || x === '') { return null; } const d = typeof x === 'number' ? new Date(x) : new Date(String(x).slice(0, 10) + 'T00:00:00Z'); return isNaN(d) ? null : d; };
  const day = (x) => { const d = toDate(x); return d ? d.getUTCDate() + '-' + MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };
  const month = (x) => { const d = toDate(x); return d ? MONTHS[d.getUTCMonth()] + '-' + d.getUTCFullYear() : ''; };

  // Rows of the frame with refId ref, as objects.
  const rows = (ref) => {
    const series = (context.panelData && context.panelData.series) || [];
    const f = series.find((s) => s.refId === ref);
    if (!f) { return []; }
    const cols = f.fields.map((x) => [x.name, Array.from(x.values)]);
    const n = cols.length ? cols[0][1].length : 0;
    return Array.from({ length: n }, (_, i) => Object.fromEntries(cols.map(([k, vals]) => [k, vals[i]])));
  };

  // report_flags rows from a flags_json column (json_agg of {report, flag_reason, patients_n}) on each row.
  const flagsFrom = (list) => [].concat(...(list || []).map((r) => {
    let parsed = [];
    try { parsed = r.flags_json ? JSON.parse(r.flags_json) : []; } catch (e) { parsed = []; }
    return (Array.isArray(parsed) ? parsed : []).map((f) => Object.assign({ org_unit_id: r.org_unit_id, org_unit_name: r.org_unit_name }, f));
  }));

  // Variables, read in the browser so no access query is needed.
  const orgUnit = () => { const o = v('org_unit').trim(); return o && o !== '0' ? o : '0'; };
  const reportingMonth = () => v('reporting_month');
  const allowed = () => v('isAllowed') === '1';

  // The user's home unit (hidden variable home_org_unit, the home dashboard's UserOrgUnitId query).
  // '' for admins and users with access everywhere.
  const homeUnit = () => { const h = v('home_org_unit').trim(); return h && h !== '0' ? h : ''; };

  // Tabs from the builder's TABS list: [{report, title, slug}], in tab order. TABS[0] is `Start here`.
  const TABS = [{"report":"start","title":"Start here","slug":"Start-here"},{"report":"titration","title":"Stepping up","slug":"Stepping-up"},{"report":"adherence","title":"Right medicines","slug":"Right-medicines"},{"report":"fudging","title":"BP readings check","slug":"BP-readings-check"},{"report":"calling","title":"Overdue calls","slug":"Overdue-calls"},{"report":"statins","title":"Statins","slug":"Statins"}];
  // The five report tabs (every tab but `Start here`), in tab order.
  const REPORTS = TABS.filter((t) => t.report !== 'start');
  const tab = (report) => TABS.find((t) => t.report === report) || null;
  // AD-29 deep link; keeps the location and month unless given. extra: more URL parameters,
  // for example { 'var-include_new': 'true' }.
  const link = (report, org, mon, extra) => {
    const t = tab(report);
    if (!t) { return ''; }
    const more = Object.keys(extra || {}).map((k) => '&' + encodeURIComponent(k) + '=' + encodeURIComponent(extra[k])).join('');
    return '/d/heart360_reports?var-org_unit=' + encodeURIComponent(org == null ? orgUnit() : org)
      + '&var-reporting_month=' + encodeURIComponent(mon == null ? reportingMonth() : mon) + more + '&-dtab=' + encodeURIComponent(t.slug);
  };
  // A facility name that narrows this tab to that facility (UX-15). Plain text when it is already the place in view.
  const placeLink = (report, id, name) => (id == null || String(id) === orgUnit() || !tab(report)
    ? esc(name) : '<a class="rpt-link" href="' + esc(link(report, id)) + '" title="' + esc('Show ' + name + ' only') + '">' + esc(name) + '</a>');
  // `Next step` line at the end of a tab: one link, sentence case.
  const nextStep = (text, href) => '<div class="rpt-next"><span class="rpt-next-label">Next step</span>'
    + '<a class="rpt-link" href="' + esc(href) + '">' + esc(text) + ' →</a></div>';
  // Same-page links: an <a href="#some-id"> inside el scrolls the element with that id into view
  // (Grafana scrolls its own pane, so a plain hash link does not move it). Use with nextStep('...', '#id').
  // Grafana draws panels lazily: while the target is not drawn yet, the pane scrolls down a screen at a
  // time until it appears.
  const wireScroll = (el) => {
    if (!el || el.__rptScroll) { return; }
    el.__rptScroll = true;
    const pane = (node) => { let p = node.parentElement; while (p && !(p.scrollHeight > p.clientHeight && /auto|scroll/.test(getComputedStyle(p).overflowY))) { p = p.parentElement; } return p; };
    el.addEventListener('click', (e) => {
      const a = e.target.closest && e.target.closest('a[href^="#"]');
      if (!a || !el.contains(a)) { return; }
      e.preventDefault();
      const id = a.getAttribute('href').slice(1);
      const box = pane(el);
      let tries = 0;
      const go = () => {
        const t = document.getElementById(id);
        if (t) { t.scrollIntoView({ behavior: 'smooth', block: 'start' }); return; }
        if (!box || tries++ > 8) { return; }
        box.scrollTop += Math.round(box.clientHeight * 0.8);
        setTimeout(go, 350);
      };
      go();
    });
  };
  // At or below the facility level (selected_level 3 or more): patient lists and the overdue list work here.
  const atFacility = () => (num(v('selected_level')) || 0) >= 3;

  // --- States (DESIGN States, FR-32) ---
  // Grey note, no warning tone (Voice rule 8, UX-21). html is trusted markup; use esc() on data.
  const info = (html) => '<div class="rpt-info">' + html + '</div>';
  // No access: plain words and the next step. The access team names sit in a closed `Details` for the admin.
  const banner = () => {
    const teams = v('requiredGroups').replace(/<[^>]*>/g, '').trim();
    return info('<span>You cannot see this place. Pick your own area in <strong>Change location</strong> above.</span>'
      + (teams ? '<details class="rpt-details"><summary>Details for your admin</summary>Access comes from: ' + esc(teams) + '</details>' : ''));
  };
  // Shown while the page moves a user with no location to their home unit (UX-02).
  const OPENING_HOME = 'Opening your area…';
  // For views that need one facility (patient lists): a grey line with the next step.
  const PICK_FACILITY = 'Pick a facility in Change location above to see its patients.';
  const NO_DATA = 'No data for this place.';
  const NO_FACILITIES = 'No facilities for this location.';
  const NO_FLAGS = 'No facility is flagged.';
  const noData = (text) => '<div class="rpt-empty">' + esc(text || NO_DATA) + '</div>';
  // "Need at least 20; this place has 12."
  const needAtLeast = (k, n) => 'Need at least ' + fmt(k) + '; this place has ' + fmt(n) + '.';
  // Place for the subtitle: the selected name, or all locations.
  const place = (name) => (orgUnit() === '0' ? 'All locations you can access' : (name || 'This place'));

  // Thresholds from report_flag_thresholds rows ({report, key, value}).
  const thresholds = (list) => { const t = {}; (list || []).forEach((r) => { t[r.report + '.' + r.key] = num(r.value); }); return t; };

  // UX-02: a user with no location who may not see all places is moved to their home unit, keeping
  // the month and tab. Returns true when it does so.
  const goHome = () => {
    const home = homeUnit();
    if (allowed() || orgUnit() !== '0' || !home) { return false; }
    // Several panels call this on one render; move once (a later blank pick moves again).
    if (Date.now() - (window.__rptGoHome || 0) > 3000) {
      window.__rptGoHome = Date.now();
      const ls = grafana.locationService;
      if (ls && ls.partial) { ls.partial({ 'var-org_unit': home }, true); }
      else { const u = new URL(window.location.href); u.searchParams.set('var-org_unit', home); window.location.replace(u.toString()); }
    }
    return true;
  };
  // True while the panel's query is still running.
  const loading = () => !!(context.panelData && context.panelData.state === 'Loading');

  // Mount: returns the root element, or null when access is denied. The banner is drawn once per tab,
  // by the panel mounted with { banner: true } (the title strip); other panels stay empty under it.
  // A user with no location is first moved to their home unit (UX-02); meanwhile the banner panel
  // shows `Opening your area…`. opts.loading: a line to show while the query runs (null is returned).
  const mount = (selector, opts) => {
    const o = opts || {};
    const root = context.element.querySelector(selector);
    if (!root) { return null; }
    if (goHome()) { root.innerHTML = o.banner ? '<div class="rpt-muted">' + esc(OPENING_HOME) + '</div>' : ''; return null; }
    if (!allowed()) { root.innerHTML = o.banner ? banner() : ''; return null; }
    if (o.loading && loading()) { root.innerHTML = '<div class="rpt-muted rpt-loading">' + esc(o.loading) + '</div>'; return null; }
    return root;
  };

  return { v, esc, num, fmt, pct, score, yes, day, month, toDate, rows, orgUnit, reportingMonth, allowed, homeUnit,
    TABS, REPORTS, tab, link, placeLink, nextStep, wireScroll, atFacility, flagsFrom, info, banner, OPENING_HOME, PICK_FACILITY,
    NO_DATA, NO_FACILITIES, NO_FLAGS, noData, needAtLeast, place, thresholds, loading, goHome, mount };
})();
// The Excel protocol adherence table (protocol_engine.py write_protocol_report_table, UX-05):
// one row per medicine group, in the tool's order and columns. Blank where the tool leaves it blank.
const root = rpt.mount('.rpt-adh-steps');
if (!root) { return; }
const { esc, fmt, num } = rpt;
const rows = rpt.rows('A').sort((a, b) => num(a.row_order) - num(b.row_order));
if (!rows.length) { root.innerHTML = rpt.noData(); return; }
const by = {};
rows.forEach((r) => { by[r.row_key] = r; });
const all = by.grand_total || {}, steps = by.steps_total || {};
const noCohort = (r) => r.row_key === 'no_htn_medicine';
// Running sum of controlled patients from Step 1 to Step n, for the `n of N` behind `Control so far`.
let cum = 0;
const cumN = {};
rows.forEach((r) => { if (num(r.step_no) !== null) { cum += num(r.cohort_controlled_n) || 0; cumN[r.row_key] = cum; } });
// Percent whole (DESIGN), the exact value and its n of N on hover.
const pc = (v, n, d, what) => (num(v) === null ? '' : '<span title="' + esc(num(v) + '% · ' + fmt(n) + ' of ' + fmt(d) + ' ' + what) + '">' + rpt.pct(v) + '</span>');
const cells = (r) => {
  const step = num(r.step_no) !== null;
  const blank = noCohort(r);
  return [
    fmt(r.patients_n),
    pc(r.patients_pct, r.patients_n, all.patients_n, 'patients'),
    pc(r.step_share_pct, r.patients_n, steps.patients_n, 'patients on a step'),
    blank ? '' : fmt(r.cohort_n),
    blank ? '' : fmt(r.cohort_controlled_n),
    blank ? '' : pc(r.cohort_controlled_pct, r.cohort_controlled_n, r.cohort_n, 'controlled'),
    step ? pc(r.controlled_share_cum_pct, cumN[r.row_key], steps.cohort_controlled_n, 'controlled patients on a step') : ''
  ];
};
const TOTALS = ['protocol_total', 'steps_total', 'grand_total'];
const HEAD = ['Patients', '% of all patients', '% of patients on a step', 'Came back in last 3 months', 'Controlled', '% controlled', 'Control so far (steps 1 to n)'];
root.innerHTML = '<div class="rpt-wrap"><table class="rpt-table rpt-steps">'
  + '<caption class="rpt-sr">Patients by the BP medicines at their latest visit, and how many are controlled.</caption>'
  + '<thead><tr><th scope="col">Medicines at latest visit</th>' + HEAD.map((h) => '<th scope="col" class="num">' + esc(h) + '</th>').join('') + '</tr></thead><tbody>'
  + rows.map((r) => {
    const step = num(r.step_no) !== null;
    const cls = TOTALS.includes(r.row_key) ? 'rpt-steps-total' : step ? 'rpt-steps-step' : 'rpt-steps-group';
    return '<tr class="' + cls + '"><th scope="row">' + esc(r.label) + '</th>' + cells(r).map((c) => '<td class="num">' + c + '</td>').join('') + '</tr>';
  }).join('') + '</tbody></table></div>';

options.styles:
/* --- Reports shared styles (dashboard_src/reports/_shared/styles.css) ---
   Business Text styles. Every class starts rpt-; put class "rpt" on the panel's root div.
   Tokens: ux-hearts360-mvp-2026-11-04/DESIGN.md front matter. Table, chips, pager and banner copy
   the program dashboard's overdue list (.ovq-*). Light theme only (A40). */
.rpt {
  --text-primary: #111217; --text-muted: #6E6E6E; --border-subtle: #D8D9DA; --accent: #3D71D9;
  --controlled: #3BB231; --uncontrolled: #EEAB00; --no-visit: #ED6300;
  --flag-bar: #ED6300; --flag-row-bg: #FDF0E6; --flag-pill-bg: #FDE3CF; --flag-pill-text: #8A3A00;
  --guard-pill-text: #4E545A; --cell-missing-bg: #EFEFEF;
  font-size: 13px; line-height: 1.35; color: var(--text-primary);
}
.rpt a.rpt-link { color: #0075eb; text-decoration: none; }
.rpt a.rpt-link:hover, .rpt a.rpt-link:focus-visible { text-decoration: underline; }
.rpt-sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.rpt-muted { color: var(--text-muted); }
.rpt-empty { color: var(--text-muted); font-size: 14px; text-align: center; padding: 18px 8px; }

/* Title strip: question (card-title), then "{place} · {period}" (microcopy, muted). */
.rpt-title { font-size: 16px; font-weight: 500; margin: 0 0 2px; line-height: 1.3; }
.rpt-sub { font-size: 12px; color: var(--text-muted); line-height: 1.4; }

/* Headline strip: three equal columns, thin dividers (as panel-outcomes). */
.rpt-strip3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); height: 100%; }
.rpt-strip3 > div { padding: 2px 16px; border-left: 1px solid var(--border-subtle); min-width: 0; }
.rpt-strip3 > div:first-child { border-left: 0; padding-left: 4px; }
.rpt-big { font-size: 32px; font-weight: 600; line-height: 1.1; font-variant-numeric: tabular-nums; }
.rpt-big.rpt-few { font-size: 20px; font-weight: 500; color: var(--text-muted); line-height: 1.6; }
.rpt-label { font-size: 14px; font-weight: 500; margin-top: 2px; }
.rpt-line { font-size: 12px; color: var(--text-muted); line-height: 1.4; margin-top: 2px; }

/* Look at these first: at most three items. */
.rpt-card-title { font-size: 16px; font-weight: 500; margin: 0 0 8px; }
.rpt-look { list-style: none; margin: 0; padding: 0; }
.rpt-look li { padding: 8px 0 8px 10px; border-left: 4px solid var(--flag-bar); background: var(--flag-row-bg); margin-bottom: 8px; border-radius: 0 4px 4px 0; }
.rpt-look-name { font-weight: 600; }
.rpt-look-line { font-size: 12px; line-height: 1.4; margin-top: 2px; }

/* Facility table: overdue list style. No vertical lines or stripes, light header, hover highlight. */
.rpt-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 8px; }
.rpt-chip { font: inherit; font-size: 12px; border: 1px solid #d9e3ff; background: transparent; color: inherit; border-radius: 14px; padding: 2px 10px; cursor: pointer; text-decoration: none; display: inline-block; white-space: nowrap; }
.rpt-chip.on { background: #0075eb; border-color: #0075eb; color: #fff; cursor: default; }
a.rpt-chip:hover, button.rpt-chip:not(.on):hover { background: #EEF3FD; }
.rpt-wrap { overflow-x: auto; }
.rpt-table { width: 100%; border-collapse: collapse; border: 0; }
.rpt-table th, .rpt-table td { border: 0 !important; border-bottom: 1px solid rgba(128,128,128,0.2) !important; padding: 8px 8px; text-align: left; vertical-align: top; }
.rpt-table thead th { background: rgba(0,117,235,0.06); color: #6e7f8d; font-size: 12px; font-weight: 600; white-space: nowrap; vertical-align: bottom; }
.rpt-table tbody th { font-weight: 400; white-space: nowrap; background: transparent; color: inherit; }
.rpt-table tbody tr:hover { background: rgba(0,117,235,0.04); }
.rpt-table .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.rpt-table thead th.num .rpt-sortbtn { text-align: right; }
.rpt-table td.rpt-why { width: 42%; min-width: 260px; }
.rpt-sortbtn { font: inherit; font-weight: 600; background: none; border: 0; padding: 0; color: inherit; cursor: pointer; }
.rpt-sortbtn:focus-visible, .rpt-chip:focus-visible, .rpt-pager button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* Flagged row: 4px orange bar and light tint. */
.rpt-table tr.rpt-flagged, .rpt-table tr.rpt-flagged:hover { background: var(--flag-row-bg); }
.rpt-table tr.rpt-flagged > th:first-child { box-shadow: inset 4px 0 0 var(--flag-bar); padding-left: 12px; }
/* All places in view: bold first row. */
.rpt-table tr.rpt-total > th, .rpt-table tr.rpt-total > td { font-weight: 700; }
.rpt-table tr.rpt-total .rpt-reason, .rpt-table tr.rpt-total .rpt-pill { font-weight: 400; }
.rpt-ctl { color: var(--controlled); font-weight: 600; }
/* Pills: text, never colour only. */
.rpt-pills { display: flex; flex-wrap: wrap; gap: 4px; }
.rpt-pill { display: inline-block; padding: 1px 8px; border-radius: 9999px; font-size: 12px; font-weight: 600; white-space: nowrap; line-height: 1.5; }
.rpt-pill-flag { background: var(--flag-pill-bg); color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-check { background: #FFFFFF; color: var(--flag-pill-text); border: 1px solid var(--flag-bar); }
.rpt-pill-guard { background: var(--cell-missing-bg); color: var(--guard-pill-text); border: 1px solid var(--cell-missing-bg); }
.rpt-reason { font-size: 12px; line-height: 1.4; margin-top: 3px; color: var(--text-primary); }
.rpt-also { font-size: 12px; margin-top: 3px; }
.rpt-also a { color: #0075eb; text-decoration: none; }
.rpt-also a:hover, .rpt-also a:focus-visible { text-decoration: underline; }
.rpt-clean { color: var(--text-muted); }
/* Pager: overdue list. */
.rpt-pager { display: flex; justify-content: center; align-items: center; gap: 12px; padding: 10px 0 2px; }
.rpt-pager button { font: inherit; width: 28px; height: 26px; border-radius: 4px; border: 1px solid #d9e3ff; background: transparent; color: inherit; cursor: pointer; }
.rpt-pager button:disabled { opacity: 0.35; cursor: default; }
/* Access banner: the overdue list's .ovq-warn. */
.rpt-warn { color: #e02424; background: rgba(224,36,36,0.05); border-left: 4px solid #e02424; padding: 8px 14px; font-size: 13px; display: flex; align-items: center; gap: 8px; border-radius: 2px; line-height: 1.4; }

/* How this is worked out. */
.rpt-note { font-size: 12px; color: var(--text-muted); line-height: 1.45; }

.rpt-demo { font-size: 12px; color: var(--text-muted); margin-top: 8px; }

/* Grey note (no warning tone, UX-21): no access, pick a facility, and other next-step lines. */
.rpt-info { color: var(--text-primary); background: #F4F5F5; border-left: 4px solid var(--border-subtle); padding: 8px 14px; font-size: 13px; line-height: 1.45; border-radius: 2px; }
.rpt-details { margin-top: 4px; font-size: 12px; color: var(--text-muted); }
.rpt-details summary { cursor: pointer; }
.rpt-loading { padding: 8px 0; }

/* Next step: one link at the end of a tab. */
.rpt-next { display: flex; align-items: baseline; gap: 10px; font-size: 14px; padding: 4px 0; }
.rpt-next-label { font-size: 12px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.03em; }
.rpt-next a.rpt-link { font-weight: 500; }

/* Start here grid: facilities down the side, reports across; each cell is a link. */
.rpt-start-do { margin: 6px 0 10px; font-size: 14px; }
.rpt-grid { table-layout: fixed; }
.rpt-grid thead th:first-child, .rpt-grid tbody th { width: 16%; }
.rpt-grid tbody th { font-weight: 600; vertical-align: middle; }
.rpt-table.rpt-grid td.rpt-cell { padding: 3px; vertical-align: middle; }
.rpt-cell a { display: block; padding: 5px 8px; border-radius: 4px; text-decoration: none; color: inherit; border: 1px solid transparent; line-height: 1.3; }
.rpt-cell a:hover, .rpt-cell a:focus-visible { border-color: var(--accent); outline: none; }
.rpt-cell-word { display: block; font-weight: 600; font-size: 13px; }
.rpt-cell-n { display: block; font-size: 12px; color: var(--text-muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rpt-cell-flag a { background: var(--flag-pill-bg); border-color: var(--flag-bar); }
.rpt-cell-flag .rpt-cell-word { color: var(--flag-pill-text); }
.rpt-cell-flag .rpt-cell-n { color: var(--flag-pill-text); }
